INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C1','math',4,2,'u6',2,'점의 이동 — 점을 옮기면 점은 그대로이고 자리만 변하며, 옮긴 것을 말할 때는 방향(위쪽·아래쪽·왼쪽·오른쪽)과 칸 수(거리)를 함께 말한다',ARRAY['4수03-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C2','math',4,2,'u6',2,'두 방향 이동과 되돌리기 — 두 방향으로 옮길 때는 말하는 순서를 바꾸어도 도착하는 자리가 같고, 반대 방향으로 같은 칸 수만큼 옮기면 처음 자리로 돌아오며, 모눈 한 칸의 길이로 cm를 칸 수로 바꾼다',ARRAY['4수03-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C3','math',4,2,'u6',3,'밀기 — 평면도형을 밀면 모양과 방향은 그대로이고 자리만 변하며, 미는 방향과 칸 수가 정해지면 민 도형을 정확히 그릴 수 있다',ARRAY['4수03-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C4','math',4,2,'u6',3,'민 거리 읽기와 이어 밀기 — 밀기 전과 민 후의 같은 꼭짓점끼리 칸 수를 세어 민 방향과 거리를 읽고, 같은 방향으로 이어 밀면 더하고 반대 방향이면 뺀다',ARRAY['4수03-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C5','math',4,2,'u6',4,'뒤집기 — 평면도형을 뒤집으면 모양은 그대로이고 방향이 변하며, 왼쪽·오른쪽으로 뒤집으면 왼쪽과 오른쪽이, 위쪽·아래쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀐다',ARRAY['4수03-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C6','math',4,2,'u6',4,'여러 번 뒤집기와 글자 뒤집기 — 위쪽 뒤집기와 아래쪽 뒤집기, 왼쪽 뒤집기와 오른쪽 뒤집기는 결과가 같고, 같은 방향으로 두 번 뒤집으면 처음과 같으며, 글자·숫자는 뒤집으면 순서까지 바뀌고 늘 같은 글자로 보이지는 않는다',ARRAY['4수03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C7','math',4,2,'u6',5,'돌리기 — 평면도형을 돌리면 모양은 그대로이고 방향이 변하며, 돌린 것을 말할 때는 시계 방향인지 시계 반대 방향인지와 몇 도(90°·180°·270°·360°)인지를 함께 말한다',ARRAY['4수03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C8','math',4,2,'u6',5,'같은 결과의 돌리기와 뒤집기 — 시계 반대 방향 90° = 시계 방향 270°, 180°는 어느 쪽으로 돌려도 같고 360°는 처음과 같으며, 뒤집기와 돌리기는 다른 방법이라 도형에 따라 결과가 다르다',ARRAY['4수03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C9','math',4,2,'u6',6,'무늬의 규칙 — 무늬는 한 모양을 밀거나 뒤집거나 돌려 되풀이해 만들며, 첫 줄을 만든 방법과 줄을 늘려 간 방법을 함께 찾아 말한다',ARRAY['4수03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u6-C10','math',4,2,'u6',6,'무늬 완성하고 만들기 — 찾은 규칙으로 빈칸에 들어갈 모양을 정하고, 모양과 이동 방법을 골라 나만의 무늬를 만들며, 같은 무늬도 여러 방법으로 설명할 수 있다',ARRAY['4수03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X01','math',4,'u6',ARRAY['M4-2-u6-C1','M4-2-u6-C3','M4-2-u6-C7']::text[],'이동을 말할 때 방향이나 거리(칸 수·각도) 가운데 하나만 말해도 된다고 생각한다 — 「오른쪽으로 옮겨」·「돌려」처럼 하나를 빠뜨린다','방향과 거리를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X02','math',4,'u6',ARRAY['M4-2-u6-C1','M4-2-u6-C3']::text[],'위쪽↔아래쪽, 왼쪽↔오른쪽을 거꾸로 읽는다 — 이동한 뒤의 자리에서 처음 자리를 보고 방향을 정한다','처음에서 나중 쪽으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X03','math',4,'u6',ARRAY['M4-2-u6-C1','M4-2-u6-C4']::text[],'옮긴 칸 수를 셀 때 처음 자리까지 세어 하나 많게(또는 하나 적게) 센다','칸이 아니라 선을 넘은 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X04','math',4,'u6',ARRAY['M4-2-u6-C2']::text[],'모눈 한 칸의 길이를 생각하지 않고 칸 수와 cm를 같게 본다','한 칸이 몇 cm인지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X05','math',4,'u6',ARRAY['M4-2-u6-C2','M4-2-u6-C4']::text[],'두 방향으로 옮길 때 말하는 순서를 바꾸면 도착하는 자리가 달라진다고 생각한다','순서를 바꾸어도 도착은 같다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X06','math',4,'u6',ARRAY['M4-2-u6-C2','M4-2-u6-C4']::text[],'두 방향으로 옮긴 칸 수를 서로 바꾸어 붙인다 — 오른쪽 4칸·아래쪽 5칸을 오른쪽 5칸·아래쪽 4칸이라고 한다','방향마다 칸 수를 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X07','math',4,'u6',ARRAY['M4-2-u6-C2','M4-2-u6-C4']::text[],'처음 자리로 되돌릴 때 같은 방향으로 옮기거나, 반대 방향으로 옮긴 칸 수를 더한다','반대 방향은 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X08','math',4,'u6',ARRAY['M4-2-u6-C1','M4-2-u6-C3']::text[],'점을 옮기거나 도형을 밀면 모양·크기·방향이 바뀐다고 생각한다','밀면 자리만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X09','math',4,'u6',ARRAY['M4-2-u6-C4']::text[],'민 칸 수를 두 도형 사이의 빈칸으로 센다 — 같은 꼭짓점끼리 세지 않는다','같은 꼭짓점끼리 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X10','math',4,'u6',ARRAY['M4-2-u6-C5','M4-2-u6-C6']::text[],'뒤집는 방향을 헷갈린다 — 왼쪽·오른쪽으로 뒤집었는데 위아래가 바뀐다고(또는 거꾸로) 생각한다','뒤집는 쪽이 서로 바뀐다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X11','math',4,'u6',ARRAY['M4-2-u6-C5']::text[],'뒤집으면 모양·크기가 바뀌거나, 자리만 바뀐다(밀기)고 생각한다','뒤집으면 방향이 변한다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X12','math',4,'u6',ARRAY['M4-2-u6-C6']::text[],'위쪽으로 뒤집기와 아래쪽으로 뒤집기(왼쪽과 오른쪽도)는 결과가 다르다고 생각한다','위쪽 = 아래쪽, 왼쪽 = 오른쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X13','math',4,'u6',ARRAY['M4-2-u6-C6']::text[],'여러 번 뒤집은 결과를 잘못 센다 — 짝수 번이면 처음과 같음을 놓치거나, 서로 다른 방향으로 두 번 뒤집어도 처음으로 돌아온다고 생각한다','같은 쪽 두 번이면 처음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X14','math',4,'u6',ARRAY['M4-2-u6-C6']::text[],'글자·숫자를 뒤집을 때 하나하나만 뒤집고 순서는 그대로 두거나, 뒤집어도 언제나 같은 글자로 보인다고 생각한다','순서까지 통째로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X15','math',4,'u6',ARRAY['M4-2-u6-C7','M4-2-u6-C8']::text[],'시계 방향과 시계 반대 방향을 바꾸어 생각한다','시곗바늘이 도는 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X16','math',4,'u6',ARRAY['M4-2-u6-C7']::text[],'돌린 각도를 잘못 본다 — 90°와 180°·270°를 헷갈리거나 위쪽 부분이 간 자리를 잘못 짚는다','위쪽이 어디로 갔는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X17','math',4,'u6',ARRAY['M4-2-u6-C8']::text[],'같은 결과를 내는 돌리기를 잘못 구한다 — 시계 반대 90° = 시계 90°라고 하거나 360°에서 빼지 않는다','한 바퀴 360°에서 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X18','math',4,'u6',ARRAY['M4-2-u6-C5','M4-2-u6-C7','M4-2-u6-C8']::text[],'뒤집기와 돌리기를 같은 것으로 생각한다 — 아래쪽으로 뒤집기와 180° 돌리기는 언제나 같다고 한다','뒤집기 ≠ 돌리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X19','math',4,'u6',ARRAY['M4-2-u6-C9','M4-2-u6-C10']::text[],'무늬의 규칙을 잘못 찾는다 — 이동의 종류(밀기·뒤집기·돌리기)나 방향을 섞거나 첫 줄만 본다','첫 줄과 줄 늘리기 둘 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X20','math',4,'u6',ARRAY['M4-2-u6-C9','M4-2-u6-C10']::text[],'같은 무늬를 만드는 방법(설명)은 한 가지뿐이라고 생각한다','방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X21','math',4,'u6',ARRAY['M4-2-u6-C1','M4-2-u6-C2','M4-2-u6-C3','M4-2-u6-C4','M4-2-u6-C5','M4-2-u6-C6','M4-2-u6-C7','M4-2-u6-C8','M4-2-u6-C9','M4-2-u6-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못↔바르게','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X22','math',4,'u6',ARRAY['M4-2-u6-C5','M4-2-u6-C7']::text[],'뒤집거나 돌린 도형을 모눈에 그릴 때 배경 모눈(판)까지 함께 뒤집거나 돌린다고 생각한다 — 도형만 움직인다는 것을 놓친다(지도서 416 유의 ②·442)','모눈은 그대로, 도형만 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X23','math',4,'u6',ARRAY['M4-2-u6-C1','M4-2-u6-C2']::text[],'위쪽·아래쪽·왼쪽·오른쪽을 지도(모눈)에서 정하지 않고 움직이는 로봇(사람)이 바라보는 쪽을 기준으로 정한다 — 「오른쪽으로 꺾어서」처럼(지도서 429)','지도에서 ↑ 쪽이 위쪽, → 쪽이 오른쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X24','math',4,'u6',ARRAY['M4-2-u6-C5','M4-2-u6-C6']::text[],'위쪽과 아래쪽, 왼쪽과 오른쪽이 모두 바뀐 도형을 한 번 뒤집은 것이라고 한다 — 한 방향으로 뒤집으면 한쪽만 바뀐다는 것을 놓친다(지도서 420·443)','한 번 뒤집으면 한쪽만 서로 바뀌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X25','math',4,'u6',ARRAY['M4-2-u6-C3','M4-2-u6-C4']::text[],'자동차(도형)를 밀 때 길이 다 비었는지 확인하지 않고 덜 밀거나, 가로막은 것을 먼저 비키지 않는다 — 「파란색 자동차를 아래쪽으로 2칸」(지도서 437)','한 칸씩 밀며 길이 다 비었는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u6-X26','math',4,'u6',ARRAY['M4-2-u6-C6','M4-2-u6-C8']::text[],'글자를 돌려도 언제나 같은 글자로(또는 글자처럼) 보인다고 생각한다 — 「응」을 90°만큼 돌려도 「응」, 「곰」을 180°만큼 돌려도 「곰」이라고 한다(지도서 424~425 오류 2)','돌리면 다른 글자가 되거나 글자가 아닐 수도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#1','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C1',1,'mc','auto','『수학』 132쪽 — 민혜는 로봇 친구 로니에게 「지도를 보면 집에서 위쪽으로 오다가 오른쪽으로 꺾어서 쭉 오면 학교야.」라고 했는데, 로니는 그 설명을 이해할 수 없었어요. 민혜의 설명에 빠진 것은 무엇인가요?',ARRAY['M4-2-u6-X01','M4-2-u6-X23','M4-2-u6-X21']::text[],false,'{"seq":1,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"『수학』 132쪽 — 민혜는 로봇 친구 로니에게 「지도를 보면 집에서 위쪽으로 오다가 오른쪽으로 꺾어서 쭉 오면 학교야.」라고 했는데, 로니는 그 설명을 이해할 수 없었어요. 민혜의 설명에 빠진 것은 무엇인가요?","options":[{"t":"몇 칸 이동해야 하는지(거리)","correct":true},{"t":"어느 쪽으로 이동해야 하는지(방향)","mis":"M4-2-u6-X01"},{"t":"로니가 바라보는 쪽에서 본 오른쪽","mis":"M4-2-u6-X23"},{"t":"학교의 이름","mis":"M4-2-u6-X21"}],"explanation":["민혜는 위쪽·오른쪽처럼 방향은 말했어요.","하지만 몇 칸 이동하는지는 말하지 않았어요.","점의 이동은 방향과 거리(칸 수)를 함께 말해야 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#2','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C1',1,'mc','auto','『수학』 133쪽 1 — 바둑돌을 위쪽으로 2칸 이동했던 것을 보고, 이번에는 아래쪽으로 2칸 이동하려고 해요. 바둑돌의 위치는 어떻게 될까요?',ARRAY['M4-2-u6-X02','M4-2-u6-X08']::text[],true,'{"seq":2,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"『수학』 133쪽 1 — 바둑돌을 위쪽으로 2칸 이동했던 것을 보고, 이번에는 아래쪽으로 2칸 이동하려고 해요. 바둑돌의 위치는 어떻게 될까요?","options":[{"t":"아래쪽으로 2칸 이동한 곳으로 바뀌어요","correct":true},{"t":"위쪽으로 2칸 이동한 곳으로 바뀌어요","mis":"M4-2-u6-X02"},{"t":"바둑돌의 모양이 바뀌어요","mis":"M4-2-u6-X08"},{"t":"위치가 그대로예요","mis":"M4-2-u6-X08"}],"explanation":["아래쪽으로 이동하면 바둑돌이 아래쪽으로 옮겨 가요.","바둑돌 자체는 그대로예요.","바둑돌의 위치가 아래쪽으로 2칸 이동한 곳으로 바뀌어요."],"variant_rule":{"alt":[{"stem":"『수학』 133쪽 1 — 바둑돌을 오른쪽으로 2칸 이동했던 것을 보고, 이번에는 왼쪽으로 2칸 이동하려고 해요. 바둑돌의 위치는 어떻게 될까요?","options":[{"t":"왼쪽으로 2칸 이동한 곳으로 바뀌어요","correct":true},{"t":"오른쪽으로 2칸 이동한 곳으로 바뀌어요","mis":"M4-2-u6-X02"},{"t":"바둑돌의 색이 바뀌어요","mis":"M4-2-u6-X08"},{"t":"위치가 그대로예요","mis":"M4-2-u6-X08"}],"explanation":["왼쪽으로 이동하면 바둑돌이 왼쪽으로 옮겨 가요.","바둑돌 자체는 그대로예요.","바둑돌의 위치가 왼쪽으로 2칸 이동한 곳으로 바뀌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#3','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C1',1,'ox','auto','『수학』 133쪽 — 바둑돌을 이동하면 바둑돌의 위치가 변해요.',ARRAY['M4-2-u6-X08']::text[],false,'{"seq":3,"concept":"M4-2-u6-C1","difficulty":1,"kind":"ox","stem":"『수학』 133쪽 — 바둑돌을 이동하면 바둑돌의 위치가 변해요.","answer":"O","reason_options":[{"t":"바둑돌 자체는 그대로이고 놓인 곳만 바뀌어서","correct":true},{"t":"바둑돌을 옮기면 바둑돌의 모양도 함께 바뀌어서","mis":"M4-2-u6-X08"}],"mis":"M4-2-u6-X08","explanation":["바둑돌을 위쪽·아래쪽·왼쪽·오른쪽으로 옮겨 보았어요.","바둑돌의 모양·크기·색은 그대로였어요.","이동하면 위치가 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#4','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C1',1,'mc','auto','『수학익힘』 78쪽 1 — 바둑돌을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03','M4-2-u6-X01']::text[],true,'{"seq":4,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"『수학익힘』 78쪽 1 — 바둑돌을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"왼쪽으로 2칸 이동했어요","correct":true},{"t":"오른쪽으로 2칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 3칸 이동했어요","mis":"M4-2-u6-X03"},{"t":"2칸 이동했어요","mis":"M4-2-u6-X01"}],"explanation":["이동 전 자리에서 이동 후 자리 쪽을 보면 왼쪽이에요.","모눈 선을 넘은 수를 세면 2칸이에요.","방향과 거리를 함께 — 왼쪽으로 2칸 이동했어요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"pts":{"전":[54,18,"e"],"후":[18,18,"w"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 133쪽 1 — 바둑돌을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"아래쪽으로 2칸 이동했어요","correct":true},{"t":"위쪽으로 2칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 3칸 이동했어요","mis":"M4-2-u6-X03"},{"t":"2칸 이동했어요","mis":"M4-2-u6-X01"}],"explanation":["이동 전 자리에서 이동 후 자리 쪽을 보면 아래쪽이에요.","모눈 선을 넘은 수를 세면 2칸이에요.","방향과 거리를 함께 — 아래쪽으로 2칸 이동했어요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"pts":{"전":[18,18,"n"],"후":[18,54,"s"]}}],"tag":false}},{"stem":"지도서 433쪽 확인 문제 1 — 점을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"위쪽으로 3칸 이동했어요","correct":true},{"t":"아래쪽으로 3칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 4칸 이동했어요","mis":"M4-2-u6-X03"},{"t":"3칸 이동했어요","mis":"M4-2-u6-X01"}],"explanation":["이동 전 자리에서 이동 후 자리 쪽을 보면 위쪽이에요.","모눈 선을 넘은 수를 세면 3칸이에요.","방향과 거리를 함께 — 위쪽으로 3칸 이동했어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"pts":{"전":[18,72,"s"],"후":[18,18,"n"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#5','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C1',2,'mc','auto','『수학』 134쪽 2 — 점 ㄱ을 오른쪽으로 3 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03']::text[],true,'{"seq":5,"concept":"M4-2-u6-C1","difficulty":2,"kind":"mc","stem":"『수학』 134쪽 2 — 점 ㄱ을 오른쪽으로 3 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"},{"t":"점 ㅁ","mis":"M4-2-u6-X03"}],"explanation":["모눈 한 칸이 1 cm라서 3 cm는 3칸이에요.","점 ㄱ에서 오른쪽으로 3칸 간 자리를 찾아요.","점 ㄹ이에요"],"asset":{"type":"geo","items":[{"w":162,"h":72,"grid":18,"pts":{"ㄱ":[72,18,"nw"],"ㄴ":[144,18,"e"],"ㄷ":[18,18,"w"],"ㄹ":[126,18,"n"],"ㅁ":[108,18,"sw"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학익힘』 79쪽 3 — 점 ㄱ을 아래쪽으로 2 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X02"},{"t":"점 ㄷ","mis":"M4-2-u6-X03"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"}],"explanation":["모눈 한 칸이 1 cm라서 2 cm는 2칸이에요.","점 ㄱ에서 아래쪽으로 2칸 간 자리를 찾아요.","점 ㅁ이에요"],"asset":{"type":"geo","items":[{"w":90,"h":126,"grid":18,"pts":{"ㄱ":[18,54,"ne"],"ㄴ":[18,72,"e"],"ㄷ":[18,108,"s"],"ㄹ":[18,18,"n"],"ㅁ":[18,90,"w"]}}],"tag":false}},{"stem":"『수학』 150쪽 1 — 점 ㄱ을 왼쪽으로 5 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"},{"t":"점 ㅁ","mis":"M4-2-u6-X03"}],"explanation":["모눈 한 칸이 1 cm라서 5 cm는 5칸이에요.","점 ㄱ에서 왼쪽으로 5칸 간 자리를 찾아요.","점 ㄹ이에요"],"asset":{"type":"geo","items":[{"w":234,"h":72,"grid":18,"pts":{"ㄱ":[126,18,"ne"],"ㄴ":[18,18,"w"],"ㄷ":[216,18,"e"],"ㄹ":[36,18,"n"],"ㅁ":[54,18,"e"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.