INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#6','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C1',2,'sa','auto','『수학』 134쪽 3 — 점 ㄴ을 위쪽으로 몇 cm 이동했나요? 숫자로 쓰세요. (「전」은 이동 전, 「후」는 이동 후의 자리예요. 모눈 한 칸은 1 cm예요.)','{}'::text[],true,'{"seq":6,"concept":"M4-2-u6-C1","difficulty":2,"kind":"sa","stem":"『수학』 134쪽 3 — 점 ㄴ을 위쪽으로 몇 cm 이동했나요? 숫자로 쓰세요. (「전」은 이동 전, 「후」는 이동 후의 자리예요. 모눈 한 칸은 1 cm예요.)","answer":["4"],"explanation":["이동 전 자리는 세지 않아요.","위쪽으로 모눈 선을 하나씩 넘으며 세면 4칸이에요.","한 칸이 1 cm라서 4 cm예요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"pts":{"전":[18,90,"s"],"후":[18,18,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학익힘』 78쪽 2 — 점을 오른쪽으로 몇 칸 이동했나요? 숫자로 쓰세요. (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","answer":["6"],"explanation":["이동 전 자리는 세지 않아요.","오른쪽으로 모눈 선을 하나씩 넘으며 세면 6칸이에요.","6칸 이동했어요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"전":[18,18,"n"],"후":[126,18,"s"]}}],"tag":false}},{"stem":"『수학』 150쪽 정리 — 점 ㄱ을 오른쪽으로 몇 칸 이동했나요? 숫자로 쓰세요. (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","answer":["6"],"explanation":["이동 전 자리는 세지 않아요.","오른쪽으로 모눈 선을 하나씩 넘으며 세면 6칸이에요.","6칸 이동했어요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"전":[18,18,"n"],"후":[126,18,"s"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#7','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',2,'mc','auto','『수학』 135쪽 4 — 점 ㄱ의 이동에 대해 바르게 설명한 사람을 모두 고른 것은 어느 것인가요? (「전」은 이동 전, 「후」는 이동 후의 점 ㄱ이에요.) 소율 「아래쪽으로 5칸 이동하고, 오른쪽으로 4칸 이동했어.」 · 지훈 「오른쪽으로 5칸 이동하고, 아래쪽으로 4칸 이동했어.」 · 은서 「아래쪽으로 4칸 이동하고, 오른쪽으로 5칸 이동했어.」 · 준우 「오른쪽으로 4칸 이동하고, 아래쪽으로 5칸 이동했어.」',ARRAY['M4-2-u6-X06','M4-2-u6-X05']::text[],false,'{"seq":7,"concept":"M4-2-u6-C2","difficulty":2,"kind":"mc","stem":"『수학』 135쪽 4 — 점 ㄱ의 이동에 대해 바르게 설명한 사람을 모두 고른 것은 어느 것인가요? (「전」은 이동 전, 「후」는 이동 후의 점 ㄱ이에요.) 소율 「아래쪽으로 5칸 이동하고, 오른쪽으로 4칸 이동했어.」 · 지훈 「오른쪽으로 5칸 이동하고, 아래쪽으로 4칸 이동했어.」 · 은서 「아래쪽으로 4칸 이동하고, 오른쪽으로 5칸 이동했어.」 · 준우 「오른쪽으로 4칸 이동하고, 아래쪽으로 5칸 이동했어.」","options":[{"t":"지훈, 은서","correct":true},{"t":"소율, 준우","mis":"M4-2-u6-X06"},{"t":"지훈","mis":"M4-2-u6-X05"},{"t":"은서, 준우","mis":"M4-2-u6-X06"}],"explanation":["점 ㄱ은 아래쪽으로 4칸, 오른쪽으로 5칸 옮겨졌어요.","지훈이와 은서는 순서만 다르고 방향마다 칸 수가 맞아요.","소율이와 준우는 칸 수를 서로 바꾸어 붙였어요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"pts":{"전":[18,18,"n"],"후":[108,90,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#8','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',2,'mc','auto','『수학』 135쪽 5 — 집에서 학교까지 어떻게 이동해야 하나요?',ARRAY['M4-2-u6-X06','M4-2-u6-X02']::text[],true,'{"seq":8,"concept":"M4-2-u6-C2","difficulty":2,"kind":"mc","stem":"『수학』 135쪽 5 — 집에서 학교까지 어떻게 이동해야 하나요?","options":[{"t":"위쪽으로 2칸 이동하고 오른쪽으로 6칸 이동해요","correct":true},{"t":"위쪽으로 6칸 이동하고 오른쪽으로 2칸 이동해요","mis":"M4-2-u6-X06"},{"t":"아래쪽으로 2칸 이동하고 오른쪽으로 6칸 이동해요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 2칸 이동하고 왼쪽으로 6칸 이동해요","mis":"M4-2-u6-X02"}],"explanation":["가로로 오른쪽으로 6칸, 세로로 위쪽으로 2칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"집":[18,54,"n"],"학교":[126,18,"n"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학익힘』 78쪽 — 출발점에서 집까지 어떻게 이동해야 하나요?","options":[{"t":"위쪽으로 2칸 이동하고 오른쪽으로 2칸 이동해요","correct":true},{"t":"아래쪽으로 2칸 이동하고 오른쪽으로 2칸 이동해요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 2칸 이동하고 왼쪽으로 2칸 이동해요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 2칸 이동해요","mis":"M4-2-u6-X01"}],"explanation":["가로로 오른쪽으로 2칸, 세로로 위쪽으로 2칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"pts":{"출발":[18,54,"sw"],"집":[54,18,"ne"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#9','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',2,'mc','auto','『수학익힘』 79쪽 5 — 점의 이동에 대해 잘못 설명한 사람은 누구인가요? (「전」은 이동 전, 「후」는 이동 후의 점이에요. 모눈 한 칸은 1 cm예요.) 지아 「점을 왼쪽으로 3 cm 이동하고, 위쪽으로 2 cm 이동했어.」 · 민준 「점을 위쪽으로 3 cm 이동하고, 왼쪽으로 2 cm 이동했어.」 · 서윤 「점을 위쪽으로 2 cm 이동하고, 왼쪽으로 3 cm 이동했어.」',ARRAY['M4-2-u6-X05','M4-2-u6-X06']::text[],false,'{"seq":9,"concept":"M4-2-u6-C2","difficulty":2,"kind":"mc","stem":"『수학익힘』 79쪽 5 — 점의 이동에 대해 잘못 설명한 사람은 누구인가요? (「전」은 이동 전, 「후」는 이동 후의 점이에요. 모눈 한 칸은 1 cm예요.) 지아 「점을 왼쪽으로 3 cm 이동하고, 위쪽으로 2 cm 이동했어.」 · 민준 「점을 위쪽으로 3 cm 이동하고, 왼쪽으로 2 cm 이동했어.」 · 서윤 「점을 위쪽으로 2 cm 이동하고, 왼쪽으로 3 cm 이동했어.」","options":[{"t":"민준","correct":true},{"t":"지아","mis":"M4-2-u6-X05"},{"t":"서윤","mis":"M4-2-u6-X05"},{"t":"잘못 설명한 사람이 없어요","mis":"M4-2-u6-X06"}],"explanation":["점은 왼쪽으로 3칸(3 cm), 위쪽으로 2칸(2 cm) 옮겨졌어요.","지아와 서윤은 순서만 다를 뿐 맞게 설명했어요.","민준이는 위쪽과 왼쪽의 cm를 서로 바꾸었어요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"pts":{"전":[72,54,"se"],"후":[18,18,"nw"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_basic#10','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_basic','lesson_basic','M4-2-u6-C2',3,'mc','auto','『수학익힘』 79쪽 퐁당 — 오래된 상자에서 보물 지도를 발견했어요. 현재 위치(점 ㄱ)에서 오른쪽으로 3칸 이동하고 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸 이동하면 보물이 있어요. 보물이 있는 곳은 어느 점인가요?',ARRAY['M4-2-u6-X07','M4-2-u6-X01','M4-2-u6-X02']::text[],true,'{"seq":10,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"『수학익힘』 79쪽 퐁당 — 오래된 상자에서 보물 지도를 발견했어요. 현재 위치(점 ㄱ)에서 오른쪽으로 3칸 이동하고 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸 이동하면 보물이 있어요. 보물이 있는 곳은 어느 점인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄷ","mis":"M4-2-u6-X07"},{"t":"점 ㄹ","mis":"M4-2-u6-X01"},{"t":"점 ㄴ","mis":"M4-2-u6-X02"}],"explanation":["점 ㄱ에서 먼저 오른쪽으로 3칸 가요.","그 자리에서 위쪽으로 3칸 가요 다음 왼쪽으로 1칸 가요.","도착한 곳은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"pts":{"ㄱ":[90,72,"sw"],"ㄴ":[18,18,"nw"],"ㄷ":[162,18,"e"],"ㄹ":[144,18,"n"],"ㅁ":[126,18,"w"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"지도서 433쪽 확인 문제 2 — 점 ㄱ을 오른쪽으로 3칸 이동하고 위쪽으로 1칸 이동했을 때의 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㅁ","mis":"M4-2-u6-X06"},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄹ","mis":"M4-2-u6-X02"}],"explanation":["점 ㄱ에서 먼저 오른쪽으로 3칸 가요.","그 자리에서 위쪽으로 1칸 가요.","도착한 곳은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":144,"h":108,"grid":18,"pts":{"ㄱ":[72,72,"s"],"ㄴ":[126,54,"ne"],"ㄷ":[18,54,"nw"],"ㄹ":[126,90,"s"],"ㅁ":[90,18,"nw"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
