INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#2','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',2,'ox','auto','지도서 431쪽 — 점 ㄱ을 아래쪽으로 4칸 이동한 다음 오른쪽으로 5칸 이동한 것과, 오른쪽으로 5칸 이동한 다음 아래쪽으로 4칸 이동한 것은 도착하는 곳이 같아요.',ARRAY['M4-2-u6-X05']::text[],false,'{"seq":2,"concept":"M4-2-u6-C2","difficulty":2,"kind":"ox","stem":"지도서 431쪽 — 점 ㄱ을 아래쪽으로 4칸 이동한 다음 오른쪽으로 5칸 이동한 것과, 오른쪽으로 5칸 이동한 다음 아래쪽으로 4칸 이동한 것은 도착하는 곳이 같아요.","answer":"O","reason_options":[{"t":"말하는 순서를 바꾸어도 방향마다 옮긴 칸 수가 같아서","correct":true},{"t":"이동하는 순서가 다르면 도착하는 곳도 달라져서","mis":"M4-2-u6-X05"}],"mis":"M4-2-u6-X05","explanation":["두 설명 모두 아래쪽으로 4칸, 오른쪽으로 5칸 옮겨요.","순서만 다를 뿐이에요.","그래서 지훈이와 은서의 설명이 모두 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#3','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'mc','auto','『수학』 152쪽 6 — 점 ㄴ을 이동한 방법을 「방법 1」에서는 「왼쪽으로 4칸 이동하고 아래쪽으로 2칸 이동했어요.」라고 설명했어요. 순서를 바꾼 「방법 2」로 바르게 설명한 것은 어느 것인가요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X02']::text[],true,'{"seq":3,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"『수학』 152쪽 6 — 점 ㄴ을 이동한 방법을 「방법 1」에서는 「왼쪽으로 4칸 이동하고 아래쪽으로 2칸 이동했어요.」라고 설명했어요. 순서를 바꾼 「방법 2」로 바르게 설명한 것은 어느 것인가요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"아래쪽으로 2칸 이동하고 왼쪽으로 4칸 이동했어요","correct":true},{"t":"아래쪽으로 4칸 이동하고 왼쪽으로 2칸 이동했어요","mis":"M4-2-u6-X06"},{"t":"위쪽으로 2칸 이동하고 왼쪽으로 4칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 2칸 이동하고 오른쪽으로 4칸 이동했어요","mis":"M4-2-u6-X02"}],"explanation":["가로로 왼쪽으로 4칸, 세로로 아래쪽으로 2칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":108,"h":72,"grid":18,"pts":{"전":[90,18,"e"],"후":[18,54,"w"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 135쪽 4 — 점 ㄱ을 이동한 방법을 「방법 1」에서는 「아래쪽으로 4칸 이동하고 오른쪽으로 5칸 이동했어요.」라고 설명했어요. 순서를 바꾼 「방법 2」로 바르게 설명한 것은 어느 것인가요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"오른쪽으로 5칸 이동하고 아래쪽으로 4칸 이동했어요","correct":true},{"t":"오른쪽으로 4칸 이동하고 아래쪽으로 5칸 이동했어요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 5칸 이동하고 아래쪽으로 4칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 5칸 이동하고 위쪽으로 4칸 이동했어요","mis":"M4-2-u6-X02"}],"explanation":["가로로 오른쪽으로 5칸, 세로로 아래쪽으로 4칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"pts":{"전":[18,18,"n"],"후":[108,90,"n"]}}],"tag":false}},{"stem":"『수학익힘』 79쪽 5 — 점을 이동한 방법을 「방법 1」에서는 「왼쪽으로 3 cm 이동하고 위쪽으로 2 cm 이동했어요.」라고 설명했어요. 순서를 바꾼 「방법 2」로 바르게 설명한 것은 어느 것인가요? (「전」은 이동 전, 「후」는 이동 후의 자리예요. 모눈 한 칸은 1 cm예요.)","options":[{"t":"위쪽으로 2 cm 이동하고 왼쪽으로 3 cm 이동했어요","correct":true},{"t":"위쪽으로 3 cm 이동하고 왼쪽으로 2 cm 이동했어요","mis":"M4-2-u6-X06"},{"t":"아래쪽으로 2 cm 이동하고 왼쪽으로 3 cm 이동했어요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 2 cm 이동하고 오른쪽으로 3 cm 이동했어요","mis":"M4-2-u6-X02"}],"explanation":["가로로 왼쪽으로 3 cm, 세로로 위쪽으로 2 cm 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"pts":{"전":[72,54,"se"],"후":[18,18,"nw"]}}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#4','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'mc','auto','『수학익힘』 79쪽 5 — 지아는 「점을 왼쪽으로 3 cm 이동하고, 위쪽으로 2 cm 이동했어.」, 서윤이는 「점을 위쪽으로 2 cm 이동하고, 왼쪽으로 3 cm 이동했어.」라고 했어요. 두 사람의 설명이 모두 맞는 까닭은 무엇인가요?',ARRAY['M4-2-u6-X05','M4-2-u6-X02','M4-2-u6-X04']::text[],false,'{"seq":4,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"『수학익힘』 79쪽 5 — 지아는 「점을 왼쪽으로 3 cm 이동하고, 위쪽으로 2 cm 이동했어.」, 서윤이는 「점을 위쪽으로 2 cm 이동하고, 왼쪽으로 3 cm 이동했어.」라고 했어요. 두 사람의 설명이 모두 맞는 까닭은 무엇인가요?","options":[{"t":"말하는 순서를 바꾸어도 도착하는 곳이 같아서","correct":true},{"t":"두 사람이 같은 순서로 이동해서","mis":"M4-2-u6-X05"},{"t":"왼쪽과 위쪽은 같은 방향이라서","mis":"M4-2-u6-X02"},{"t":"cm는 칸 수와 상관없어서","mis":"M4-2-u6-X04"}],"explanation":["두 설명 모두 왼쪽으로 3 cm, 위쪽으로 2 cm 옮겨요.","이동하는 순서만 달라요.","순서를 바꾸어도 도착하는 곳은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#5','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'sa','auto','『수학익힘』 79쪽 퐁당 — 보물 지도에서 현재 위치에서 오른쪽으로 3칸, 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸 이동하면 보물이 있어요. 보물은 현재 위치보다 오른쪽으로 몇 칸 떨어져 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u6-C2","difficulty":3,"kind":"sa","stem":"『수학익힘』 79쪽 퐁당 — 보물 지도에서 현재 위치에서 오른쪽으로 3칸, 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸 이동하면 보물이 있어요. 보물은 현재 위치보다 오른쪽으로 몇 칸 떨어져 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["오른쪽으로 3칸 갔다가 왼쪽으로 1칸 되돌아왔어요.","반대 방향으로 옮긴 것은 빼요.","3 − 1 = 2칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#6','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'mc','auto','『수학』 135쪽 5 — 로봇 친구 로니가 집에서 위쪽으로 2칸 이동했어요. 이제 학교에 도착하려면 어떻게 이동해야 하나요? (학교는 집보다 위쪽으로 2칸, 오른쪽으로 6칸에 있어요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X02','M4-2-u6-X01']::text[],false,'{"seq":6,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"『수학』 135쪽 5 — 로봇 친구 로니가 집에서 위쪽으로 2칸 이동했어요. 이제 학교에 도착하려면 어떻게 이동해야 하나요? (학교는 집보다 위쪽으로 2칸, 오른쪽으로 6칸에 있어요.)","options":[{"t":"오른쪽으로 6칸 이동해요","correct":true},{"t":"위쪽으로 6칸 이동해요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 6칸 이동해요","mis":"M4-2-u6-X02"},{"t":"오른쪽으로 쭉 이동해요","mis":"M4-2-u6-X01"}],"explanation":["위쪽으로 가야 할 2칸은 이미 이동했어요.","남은 것은 오른쪽으로 6칸이에요.","방향과 칸 수를 함께 말해요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"집":[18,54,"n"],"학교":[126,18,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#7','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',3,'mc','auto','지도서 429쪽 — 로봇 친구에게 지도를 보며 길을 설명할 때 「위쪽」은 어느 쪽인가요?',ARRAY['M4-2-u6-X23']::text[],false,'{"seq":7,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"지도서 429쪽 — 로봇 친구에게 지도를 보며 길을 설명할 때 「위쪽」은 어느 쪽인가요?","options":[{"t":"지도에서 ↑ 쪽","correct":true},{"t":"로봇이 바라보고 있는 앞쪽","mis":"M4-2-u6-X23"},{"t":"로봇의 오른손이 있는 쪽","mis":"M4-2-u6-X23"},{"t":"설명하는 사람이 서 있는 쪽","mis":"M4-2-u6-X23"}],"explanation":["민혜와 로봇 친구는 모두 밖에서 지도를 내려다보고 있어요.","지도에서 ↑가 위쪽, ↓가 아래쪽, ←가 왼쪽, →가 오른쪽이에요.","움직이는 로봇이 바라보는 쪽으로 정하면 헷갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#8','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',4,'error','auto','『수학』 135쪽 4 — 점 ㄱ은 아래쪽으로 4칸, 오른쪽으로 5칸 옮겨졌는데 준우는 「점 ㄱ을 오른쪽으로 4칸 이동하고, 아래쪽으로 5칸 이동했어.」라고 했어요. 준우가 잘못한 것은 무엇인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X05','M4-2-u6-X02','M4-2-u6-X01']::text[],false,'{"seq":8,"concept":"M4-2-u6-C2","difficulty":4,"kind":"error","stem":"『수학』 135쪽 4 — 점 ㄱ은 아래쪽으로 4칸, 오른쪽으로 5칸 옮겨졌는데 준우는 「점 ㄱ을 오른쪽으로 4칸 이동하고, 아래쪽으로 5칸 이동했어.」라고 했어요. 준우가 잘못한 것은 무엇인가요?","options":[{"t":"방향마다 칸 수를 서로 바꾸어 붙였어요","correct":true,"mis_target":"M4-2-u6-X06"},{"t":"오른쪽을 먼저 말한 것이 잘못이에요","mis":"M4-2-u6-X05"},{"t":"아래쪽과 위쪽을 거꾸로 말했어요","mis":"M4-2-u6-X02"},{"t":"칸 수만 말하고 방향을 말하지 않았어요","mis":"M4-2-u6-X01"}],"explanation":["준우는 오른쪽·아래쪽 방향은 맞게 말했어요.","그런데 오른쪽은 5칸, 아래쪽은 4칸인데 칸 수를 바꾸었어요.","바르게: 오른쪽으로 5칸 이동하고, 아래쪽으로 4칸 이동했어요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"pts":{"전":[18,18,"n"],"후":[108,90,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#9','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',4,'mc','auto','『수학익힘』 79쪽 퐁당 — 보물 지도에서 「현재 위치에서 오른쪽으로 3칸, 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸」 간 곳에 보물이 있어요. 보물까지 가는 다른 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u6-X07','M4-2-u6-X06','M4-2-u6-X02']::text[],false,'{"seq":9,"concept":"M4-2-u6-C2","difficulty":4,"kind":"mc","stem":"『수학익힘』 79쪽 퐁당 — 보물 지도에서 「현재 위치에서 오른쪽으로 3칸, 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸」 간 곳에 보물이 있어요. 보물까지 가는 다른 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"위쪽으로 3칸 이동하고 오른쪽으로 2칸 이동해요","correct":true},{"t":"오른쪽으로 4칸 이동하고 위쪽으로 3칸 이동해요","mis":"M4-2-u6-X07"},{"t":"위쪽으로 2칸 이동하고 오른쪽으로 3칸 이동해요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 2칸 이동하고 위쪽으로 3칸 이동해요","mis":"M4-2-u6-X02"}],"explanation":["오른쪽으로 3칸 갔다가 왼쪽으로 1칸 오면 오른쪽으로 2칸이에요.","위쪽으로는 3칸이에요.","순서를 바꾸어도 위쪽으로 3칸, 오른쪽으로 2칸이면 같은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L02_challenge#10','math',4,2,'u6','L02','tb_g4_2_math_u6_L02_challenge','lesson_challenge','M4-2-u6-C2',4,'essay','teacher','『수학』 135쪽 5 — 로봇 친구 로니가 집에서 학교까지 가는 방법을 로니가 이해할 수 있도록 두 가지 방법으로 설명하고, 두 방법이 모두 맞는 까닭을 써 보세요. (학교는 집보다 위쪽으로 2칸, 오른쪽으로 6칸에 있어요.)','{}'::text[],false,'{"seq":10,"concept":"M4-2-u6-C2","difficulty":4,"kind":"essay","stem":"『수학』 135쪽 5 — 로봇 친구 로니가 집에서 학교까지 가는 방법을 로니가 이해할 수 있도록 두 가지 방법으로 설명하고, 두 방법이 모두 맞는 까닭을 써 보세요. (학교는 집보다 위쪽으로 2칸, 오른쪽으로 6칸에 있어요.)","answer_guide":{"answer":"방법 1: 위쪽으로 2칸 이동한 다음, 오른쪽으로 6칸 이동해요. 방법 2: 오른쪽으로 6칸 이동한 다음, 위쪽으로 2칸 이동해요. 이동하는 순서만 다르고 방향마다 옮기는 칸 수가 같아서 도착하는 곳이 같아요.","scoring_points":["두 방법 모두 방향과 칸 수를 함께 씀","위쪽 2칸·오른쪽 6칸을 바르게 붙임","순서를 바꾸어도 도착하는 곳이 같다는 까닭"]},"explanation":["학교는 집보다 위쪽, 오른쪽에 있어요.","위쪽으로 2칸, 오른쪽으로 6칸이에요.","순서를 바꾸어 말해도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"집":[18,54,"n"],"학교":[126,18,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_basic#1','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',1,'mc','auto','『수학』 137쪽 1 — 배 모양을 위쪽, 아래쪽, 왼쪽, 오른쪽으로 밀었어요. 배 모양을 밀면 모양과 위치는 어떻게 되나요?',ARRAY['M4-2-u6-X08']::text[],false,'{"seq":1,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"『수학』 137쪽 1 — 배 모양을 위쪽, 아래쪽, 왼쪽, 오른쪽으로 밀었어요. 배 모양을 밀면 모양과 위치는 어떻게 되나요?","options":[{"t":"모양은 변하지 않지만 위치는 변해요","correct":true},{"t":"모양과 위치가 모두 변해요","mis":"M4-2-u6-X08"},{"t":"모양은 변하고 위치는 그대로예요","mis":"M4-2-u6-X08"},{"t":"배가 민 쪽을 바라보도록 방향이 바뀌어요","mis":"M4-2-u6-X08"}],"explanation":["배 모양을 어느 쪽으로 밀어도 배 모양 자체는 그대로였어요.","민 방향에 따라 놓인 곳이 바뀌었어요.","밀면 모양은 그대로, 위치만 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_basic#2','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',1,'mc','auto','『수학』 138쪽 2 — 점선 도형을 아래쪽으로 7칸 민 도형은 어느 것인가요?',ARRAY['M4-2-u6-X03','M4-2-u6-X02','M4-2-u6-X11']::text[],true,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"『수학』 138쪽 2 — 점선 도형을 아래쪽으로 7칸 민 도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M4-2-u6-X03"},{"t":"㉯","mis":"M4-2-u6-X02"},{"t":"㉱","mis":"M4-2-u6-X11"}],"explanation":["밀면 모양과 방향은 그대로예요 — 뒤집힌 모양은 아니에요.","같은 꼭짓점끼리 아래쪽으로 7칸 떨어져 있어야 해요.","㉮예요"],"asset":{"type":"geo","items":[{"w":108,"h":378,"grid":18,"poly":[[[36.0,270.0],[90.0,342.0],[18.0,342.0]]],"dash":[[[36.0,144.0],[90.0,216.0]],[[90.0,216.0],[18.0,216.0]],[[18.0,216.0],[36.0,144.0]]],"cap":"㉮"},{"w":108,"h":378,"grid":18,"poly":[[[36.0,18.0],[90.0,90.0],[18.0,90.0]]],"dash":[[[36.0,144.0],[90.0,216.0]],[[90.0,216.0],[18.0,216.0]],[[18.0,216.0],[36.0,144.0]]],"cap":"㉯"},{"w":108,"h":378,"grid":18,"poly":[[[36.0,288.0],[90.0,360.0],[18.0,360.0]]],"dash":[[[36.0,144.0],[90.0,216.0]],[[90.0,216.0],[18.0,216.0]],[[18.0,216.0],[36.0,144.0]]],"cap":"㉰"},{"w":108,"h":378,"grid":18,"poly":[[[72.0,270.0],[18.0,342.0],[90.0,342.0]]],"dash":[[[36.0,144.0],[90.0,216.0]],[[90.0,216.0],[18.0,216.0]],[[18.0,216.0],[36.0,144.0]]],"cap":"㉱"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 138쪽 2 — 점선 도형을 왼쪽으로 7칸 민 도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u6-X03"},{"t":"㉱","mis":"M4-2-u6-X02"},{"t":"㉯","mis":"M4-2-u6-X11"}],"explanation":["밀면 모양과 방향은 그대로예요 — 뒤집힌 모양은 아니에요.","같은 꼭짓점끼리 왼쪽으로 7칸 떨어져 있어야 해요.","㉰예요"],"asset":{"type":"geo","items":[{"w":378,"h":108,"grid":18,"poly":[[[36.0,18.0],[90.0,90.0],[18.0,90.0]]],"dash":[[[180.0,18.0],[234.0,90.0]],[[234.0,90.0],[162.0,90.0]],[[162.0,90.0],[180.