INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_basic#3','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',1,'ox','auto','지도서 435쪽 「이런 활동도 있어요」 — 가게에서 카트를 앞으로 밀면 카트의 모양은 그대로이고 위치만 바뀌어요.',ARRAY['M4-2-u6-X08']::text[],false,'{"seq":3,"concept":"M4-2-u6-C3","difficulty":1,"kind":"ox","stem":"지도서 435쪽 「이런 활동도 있어요」 — 가게에서 카트를 앞으로 밀면 카트의 모양은 그대로이고 위치만 바뀌어요.","answer":"O","reason_options":[{"t":"밀기는 놓인 곳만 바꾸어서","correct":true},{"t":"밀면 물건의 모양도 조금씩 바뀌어서","mis":"M4-2-u6-X08"}],"mis":"M4-2-u6-X08","explanation":["문을 열고 닫거나, 걸레로 바닥을 밀거나, 카트를 미는 것도 밀기예요.","물건을 밀면 모양은 그대로예요.","위치만 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
