INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_basic#7','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',2,'mc','auto','『수학』 139쪽 4 — 노란색 자동차를 오른쪽 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X25','M4-2-u6-X02']::text[],false,'{"seq":7,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 139쪽 4 — 노란색 자동차를 오른쪽 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"초록색 자동차를 왼쪽으로 1칸 밀고, 파란색 자동차를 아래쪽으로 3칸 밀어요","correct":true},{"t":"초록색 자동차를 왼쪽으로 1칸 밀고, 파란색 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X25"},{"t":"초록색 자동차를 왼쪽으로 2칸 밀고, 파란색 자동차를 아래쪽으로 3칸 밀어요","mis":"M4-2-u6-X25"},{"t":"파란색 자동차를 위쪽으로 1칸 밀어요","mis":"M4-2-u6-X02"}],"explanation":["파란색 자동차가 출구를 막고 있는데, 위쪽은 벽이라 아래쪽으로만 비킬 수 있어요.","아래를 초록색 자동차가 막아서 먼저 초록색 자동차를 왼쪽으로 1칸 밀어요(2칸은 보라색 자동차에 막혀요).","파란색 자동차를 아래쪽으로 3칸 밀어야 출구 줄이 다 비어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.conc