INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_basic#10','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_basic','lesson_basic','M4-2-u6-C3',3,'mc','auto','『수학익힘』 80쪽 — 하늘색 자동차를 오른쪽 출구로 나가게 하려면 분홍색 자동차와 연두색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X25','M4-2-u6-X03']::text[],false,'{"seq":10,"concept":"M4-2-u6-C3","difficulty":3,"kind":"mc","stem":"『수학익힘』 80쪽 — 하늘색 자동차를 오른쪽 출구로 나가게 하려면 분홍색 자동차와 연두색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"분홍색 자동차를 왼쪽으로 1칸 밀고, 연두색 자동차를 아래쪽으로 1칸 밀어요","correct":true},{"t":"연두색 자동차를 위쪽으로 1칸 밀어요","mis":"M4-2-u6-X02"},{"t":"연두색 자동차만 아래쪽으로 1칸 밀어요","mis":"M4-2-u6-X25"},{"t":"분홍색 자동차를 왼쪽으로 1칸 밀고, 연두색 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X03"}],"explanation":["연두색 자동차가 출구를 막고 있고, 위쪽은 노란색 자동차가 막아요.","아래쪽으로 1칸 밀려면 그 자리의 분홍색 자동차를 먼저 왼쪽으로 1칸 밀어야 해요.","분홍색 왼쪽 1칸, 연두색 아래쪽 1칸이에요."],"asset":{"type":"geo","items":[{"w":201.0,"h":150,"poly":[[[33.0,63.0],[117.0,63.0],[117.0,87.0],[33.0,87.0]],[[3.0,3.0],[87.0,3.0],[87.0,27.0],[3.0,27.0]],[[123.0,3.0],[147.0,3.0],[147.0,57.0],[123.0,57.0]],[[123.0,63.0],[147.0,63.0],[147.0,117.0],[123.0,117.0]],[[33.0,123.0],[147.0,123.0],[147.0,147.0],[33.0,147.0]]],"lab":[[[75.0,74.0],"하늘"],[[45.0,14.0],"보라"],[[135.0,29.0],"노랑"],[[135.0,89.0],"연두"],[[90.0,134.0],"분홍"],[[175.5,74.0],"출구"]],"seg":[[[0,0],[150,0]],[[0,150],[150,150]],[[0,0],[0,150]],[[150,0],[150,60]],[[150,90],[150,150]]],"dash":[[[30,0],[30,150]],[[60,0],[60,150]],[[90,0],[90,150]],[[120,0],[120,150]],[[0,30],[150,30]],[[0,60],[150,60]],[[0,90],[150,90]],[[0,120],[150,120]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#1','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',2,'ox','auto','『수학』 139쪽 3 — 사각형을 오른쪽으로 4칸 밀고 위쪽으로 4칸 민 것과, 위쪽으로 4칸 밀고 오른쪽으로 4칸 민 것은 위치가 같아요.',ARRAY['M4-2-u6-X05']::text[],false,'{"seq":1,"concept":"M4-2-u6-C4","difficulty":2,"kind":"ox","stem":"『수학』 139쪽 3 — 사각형을 오른쪽으로 4칸 밀고 위쪽으로 4칸 민 것과, 위쪽으로 4칸 밀고 오른쪽으로 4칸 민 것은 위치가 같아요.","answer":"O","reason_options":[{"t":"미는 순서만 다르고 방향마다 민 칸 수가 같아서","correct":true},{"t":"미는 순서가 바뀌면 도착하는 곳도 바뀌어서","mis":"M4-2-u6-X05"}],"mis":"M4-2-u6-X05","explanation":["두 방법 모두 오른쪽으로 4칸, 위쪽으로 4칸 밀어요.","순서만 달라요.","그래서 「위쪽으로 4칸, 오른쪽으로 4칸」도 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#2','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C3',2,'mc','auto','『수학』 153쪽 만화 — 로니에게 「액자를 오른쪽으로 3칸 밀어 줘!」라고 했어요. 액자를 밀면 어떻게 되나요?',ARRAY['M4-2-u6-X11','M4-2-u6-X08']::text[],false,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 153쪽 만화 — 로니에게 「액자를 오른쪽으로 3칸 밀어 줘!」라고 했어요. 액자를 밀면 어떻게 되나요?","options":[{"t":"위치는 변해도 모양은 그대로예요","correct":true},{"t":"액자가 뒤집혀서 왼쪽과 오른쪽이 바뀌어요","mis":"M4-2-u6-X11"},{"t":"액자의 모양이 오른쪽으로 기울어져요","mis":"M4-2-u6-X08"},{"t":"액자의 위치도 모양도 그대로예요","mis":"M4-2-u6-X08"}],"explanation":["밀기는 정한 방향으로 정한 칸 수만큼 옮기는 거예요.","액자의 모양과 방향은 그대로예요.","놓인 위치만 오른쪽으로 3칸 옮겨져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#3','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'error','auto','『수학』 139쪽 4 — 친구는 「초록색 자동차를 왼쪽으로 1칸 밀고, 파란색 자동차를 아래쪽으로 2칸 밀면 돼.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X25','M4-2-u6-X02','M4-2-u6-X08']::text[],false,'{"seq":3,"concept":"M4-2-u6-C4","difficulty":3,"kind":"error","stem":"『수학』 139쪽 4 — 친구는 「초록색 자동차를 왼쪽으로 1칸 밀고, 파란색 자동차를 아래쪽으로 2칸 밀면 돼.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"파란색 자동차를 2칸만 밀면 아직 출구를 막고 있어요","correct":true,"mis_target":"M4-2-u6-X25"},{"t":"초록색 자동차를 오른쪽으로 밀어야 해요","mis":"M4-2-u6-X02"},{"t":"파란색 자동차를 먼저 밀어야 해요","mis":"M4-2-u6-X25"},{"t":"자동차는 밀 수 없어요","mis":"M4-2-u6-X08"}],"explanation":["파란색 자동차는 세로로 3칸 길이예요.","아래쪽으로 2칸 밀면 맨 위 칸이 아직 출구 줄에 남아요.","아래쪽으로 3칸 밀어야 노란색 자동차가 나갈 수 있어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#4','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'sa','auto','『수학』 139쪽 4 — 초록색 자동차를 왼쪽으로 1칸 민 다음, 노란색 자동차가 출구로 나가려면 파란색 자동차를 아래쪽으로 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)','{}'::text[],true,'{"seq":4,"concept":"M4-2-u6-C4","difficulty":3,"kind":"sa","stem":"『수학』 139쪽 4 — 초록색 자동차를 왼쪽으로 1칸 민 다음, 노란색 자동차가 출구로 나가려면 파란색 자동차를 아래쪽으로 적어도 몇 칸 밀어야 하나요? 숫자로 쓰세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","answer":["3"],"explanation":["파란색 자동차는 출구 줄과 그 위 두 칸에 걸쳐 있어요.","아래쪽으로 한 칸씩 밀며 출구 줄이 비었는지 봐요.","3칸 밀어야 출구 줄이 다 비어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학익힘』 80쪽 — 분홍색 자동차를 왼쪽으로 1칸 민 다음, 하늘색 자동차가 출구로 나가려면 연두색 자동차를 아래쪽으로 몇 칸 밀어야 하나요? 숫자로 쓰세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","answer":["1"],"explanation":["연두색 자동차는 출구 줄과 그 아래 칸에 걸쳐 있어요.","아래쪽으로 1칸 밀면 출구 줄이 비어요.","1칸이에요."],"asset":{"type":"geo","items":[{"w":201.0,"h":150,"poly":[[[33.0,63.0],[117.0,63.0],[117.0,87.0],[33.0,87.0]],[[3.0,3.0],[87.0,3.0],[87.0,27.0],[3.0,27.0]],[[123.0,3.0],[147.0,3.0],[147.0,57.0],[123.0,57.0]],[[123.0,63.0],[147.0,63.0],[147.0,117.0],[123.0,117.0]],[[33.0,123.0],[147.0,123.0],[147.0,147.0],[33.0,147.0]]],"lab":[[[75.0,74.0],"하늘"],[[45.0,14.0],"보라"],[[135.0,29.0],"노랑"],[[135.0,89.0],"연두"],[[90.0,134.0],"분홍"],[[175.5,74.0],"출구"]],"seg":[[[0,0],[150,0]],[[0,150],[150,150]],[[0,0],[0,150]],[[150,0],[150,60]],[[150,90],[150,150]]],"dash":[[[30,0],[30,150]],[[60,0],[60,150]],[[90,0],[90,150]],[[120,0],[120,150]],[[0,30],[150,30]],[[0,60],[150,60]],[[0,90],[150,90]],[[0,120],[150,120]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#5','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C3',3,'mc','auto','『수학익힘』 81쪽 퐁당 — 알지오매스 키즈에서 삼각형 ㄱㄴㄷ을 그리고, 밀기 기능에서 거리를 5 cm, 방향을 「오른쪽으로 이동」으로 정했어요. 민 후의 삼각형에서 꼭짓점 ㄱ이 옮겨 간 점은 어느 것인가요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X09','M4-2-u6-X03','M4-2-u6-X02']::text[],false,'{"seq":5,"concept":"M4-2-u6-C3","difficulty":3,"kind":"mc","stem":"『수학익힘』 81쪽 퐁당 — 알지오매스 키즈에서 삼각형 ㄱㄴㄷ을 그리고, 밀기 기능에서 거리를 5 cm, 방향을 「오른쪽으로 이동」으로 정했어요. 민 후의 삼각형에서 꼭짓점 ㄱ이 옮겨 간 점은 어느 것인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㅁ","mis":"M4-2-u6-X09"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"},{"t":"점 ㅂ","mis":"M4-2-u6-X02"}],"explanation":["밀면 모든 꼭짓점이 오른쪽으로 똑같이 5칸(5 cm) 옮겨 가요.","점 ㄱ에서 오른쪽으로 5칸 간 곳은 점 ㄹ이에요.","점 ㄴ은 점 ㅁ으로, 점 ㄷ은 점 ㅂ으로 옮겨 가요."],"asset":{"type":"geo","items":[{"w":216,"h":108,"grid":18,"poly":[[[18,72],[90,72],[54,18]],[[108,72],[180,72],[144,18]]],"pts":{"ㄱ":[18,72,"sw"],"ㄴ":[90,72,"sw"],"ㄷ":[54,18,"n"],"ㄹ":[108,72,"se"],"ㅁ":[180,72,"e"],"ㅂ":[144,18,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#6','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'mc','auto','『수학익힘』 80쪽 3 — 사각형을 왼쪽으로 밀었어요. 몇 칸 밀었나요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)',ARRAY['M4-2-u6-X09','M4-2-u6-X03']::text[],true,'{"seq":6,"concept":"M4-2-u6-C4","difficulty":3,"kind":"mc","stem":"『수학익힘』 80쪽 3 — 사각형을 왼쪽으로 밀었어요. 몇 칸 밀었나요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"4칸","correct":true},{"t":"1칸","mis":"M4-2-u6-X09"},{"t":"3칸","mis":"M4-2-u6-X03"},{"t":"5칸","mis":"M4-2-u6-X03"}],"explanation":["두 도형 사이의 빈칸(1칸)을 세면 안 돼요.","같은 꼭짓점끼리 견주면 왼쪽으로 4칸 옮겨졌어요.","4칸 밀었어요."],"asset":{"type":"geo","items":[{"w":162,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[36.0,72.0],[18.0,72.0]]],"dash":[[[90.0,18.0],[144.0,18.0]],[[144.0,18.0],[108.0,72.0]],[[108.0,72.0],[90.0,72.0]],[[90.0,72.0],[90.0,18.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 151쪽 2 — 평행사변형을 오른쪽으로 밀었어요. 몇 칸 밀었나요? (점선은 밀기 전, 색칠한 도형은 민 후예요.)","options":[{"t":"3칸","correct":true},{"t":"1칸","mis":"M4-2-u6-X09"},{"t":"2칸","mis":"M4-2-u6-X03"},{"t":"4칸","mis":"M4-2-u6-X03"}],"explanation":["두 도형 사이의 빈칸을 세면 안 돼요.","같은 꼭짓점끼리 견주면 오른쪽으로 3칸 옮겨졌어요.","3칸 밀었어요."],"asset":{"type":"geo","items":[{"w":126,"h":90,"grid":18,"poly":[[[72.0,72.0],[90.0,18.0],[108.0,18.0],[90.0,72.0]]],"dash":[[[18.0,72.0],[36.0,18.0]],[[36.0,18.0],[54.0,18.0]],[[54.0,18.0],[36.0,72.0]],[[36.0,72.0],[18.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#7','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',3,'mc','auto','『수학익힘』 81쪽 5 — 사각형을 오른쪽으로 4칸 밀고, 위쪽으로 3칸 밀었어요. 민 후의 사각형을 밀기 전 자리로 되돌리려면 어떻게 밀어야 하나요?',ARRAY['M4-2-u6-X07','M4-2-u6-X06','M4-2-u6-X02']::text[],false,'{"seq":7,"concept":"M4-2-u6-C4","difficulty":3,"kind":"mc","stem":"『수학익힘』 81쪽 5 — 사각형을 오른쪽으로 4칸 밀고, 위쪽으로 3칸 밀었어요. 민 후의 사각형을 밀기 전 자리로 되돌리려면 어떻게 밀어야 하나요?","options":[{"t":"왼쪽으로 4칸 밀고, 아래쪽으로 3칸 밀어요","correct":true},{"t":"오른쪽으로 4칸 밀고, 위쪽으로 3칸 밀어요","mis":"M4-2-u6-X07"},{"t":"왼쪽으로 3칸 밀고, 아래쪽으로 4칸 밀어요","mis":"M4-2-u6-X06"},{"t":"왼쪽으로 4칸 밀고, 위쪽으로 3칸 밀어요","mis":"M4-2-u6-X02"}],"explanation":["되돌릴 때는 반대 방향으로 같은 칸 수만큼 밀어요.","오른쪽의 반대는 왼쪽, 위쪽의 반대는 아래쪽이에요.","왼쪽으로 4칸, 아래쪽으로 3칸이에요."],"asset":{"type":"geo","items":[{"w":162,"h":108,"grid":18,"poly":[[[90.0,36.0],[108.0,18.0],[144.0,18.0],[126.0,36.0]]],"dash":[[[18.0,90.0],[36.0,72.0]],[[36.0,72.0],[72.0,72.0]],[[72.0,72.0],[54.0,90.0]],[[54.0,90.0],[18.0,90.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#8','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C4',4,'essay','teacher','『수학』 139쪽 4 — 노란색 자동차를 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 어떤 차례로, 어느 쪽으로 몇 칸씩 밀어야 하는지 쓰고, 파란색 자동차를 2칸이 아니라 3칸 밀어야 하는 까닭을 써 보세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)','{}'::text[],false,'{"seq":8,"concept":"M4-2-u6-C4","difficulty":4,"kind":"essay","stem":"『수학』 139쪽 4 — 노란색 자동차를 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 어떤 차례로, 어느 쪽으로 몇 칸씩 밀어야 하는지 쓰고, 파란색 자동차를 2칸이 아니라 3칸 밀어야 하는 까닭을 써 보세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","answer_guide":{"answer":"초록색 자동차를 왼쪽으로 1칸 먼저 밀고, 파란색 자동차를 아래쪽으로 3칸 밀어요. 파란색 자동차는 위쪽이 벽이라 아래쪽으로만 밀 수 있는데, 2칸만 밀면 맨 위 칸이 아직 출구 줄에 있어 노란색 자동차가 나갈 수 없어요.","scoring_points":["초록색 자동차를 먼저 왼쪽으로 1칸","파란색 자동차를 아래쪽으로 3칸","2칸이면 아직 출구를 막는다는 까닭"]},"explanation":["파란색 자동차를 밀려면 아래를 막은 초록색 자동차를 먼저 비켜야 해요.","초록색은 왼쪽으로 1칸만 밀 수 있어요.","파란색은 3칸 밀어야 출구 줄이 다 비어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L03_challenge#9','math',4,2,'u6','L03','tb_g4_2_math_u6_L03_challenge','lesson_challenge','M4-2-u6-C3',4,'mc','auto','지도서 437쪽 — 노란색 자동차를 꺼낼 때 초록색 자동차를 먼저 밀어야 하는 까닭은 무엇인가요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X25','M4-2-u6-X02','M4-2-u6-X21']::text[],false,'{"seq":9,"concept":"M4-2-u6-C3","difficulty":4,"kind":"mc","stem":"지도서 437쪽 — 노란색 자동차를 꺼낼 때 초록색 자동차를 먼저 밀어야 하는 까닭은 무엇인가요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"파란색 자동차가 아래쪽으로 가는 길을 초록색 자동차가 막고 있어서","correct":true},{"t":"초록색 자동차가 출구를 막고 있어서","mis":"M4-2-u6-X25"},{"t":"파란색 자동차는 위쪽으로도 밀 수 있어서","mis":"M4-2-u6-X02"},{"t":"초록색 자동차가 가장 작아서","mis":"M4-2-u6-X21"}],"explanation":["출구를 막은 것은 파란색 자동차예요.","파란색 자동차는 위쪽이 벽이라 아래쪽으로만 비킬 수 있어요.","그 아래를 초록색 자동차가 막고 있어서 초록색 자동차를 먼저 왼쪽으로 1칸 밀어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED