INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#1','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',1,'mc','auto','『수학』 141쪽 1 — 깃발 모양을 위쪽, 아래쪽, 왼쪽, 오른쪽으로 뒤집어 보았어요. 깃발 모양을 뒤집으면 모양과 방향은 어떻게 되나요?',ARRAY['M4-2-u6-X11']::text[],false,'{"seq":1,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"『수학』 141쪽 1 — 깃발 모양을 위쪽, 아래쪽, 왼쪽, 오른쪽으로 뒤집어 보았어요. 깃발 모양을 뒤집으면 모양과 방향은 어떻게 되나요?","options":[{"t":"모양은 변하지 않지만 방향은 변해요","correct":true},{"t":"모양과 방향이 모두 그대로예요","mis":"M4-2-u6-X11"},{"t":"모양은 변하고 방향은 그대로예요","mis":"M4-2-u6-X11"},{"t":"위치만 바뀌어요","mis":"M4-2-u6-X11"}],"explanation":["깃발 모양 자체는 그대로였어요.","삼각형 부분이 가리키는 쪽이 뒤집은 방향에 따라 바뀌었어요.","뒤집으면 모양은 그대로, 방향이 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#2','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',1,'mc','auto','『수학』 141쪽 1 — 깃발 모양을 위쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],true,'{"seq":2,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"『수학』 141쪽 1 — 깃발 모양을 위쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"위쪽과 아래쪽","correct":true},{"t":"왼쪽과 오른쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["위쪽이나 아래쪽으로 뒤집으면 깃발의 위쪽과 아래쪽이 서로 바뀌어요.","왼쪽과 오른쪽은 그대로예요.","위쪽과 아래쪽이 바뀌어요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"깃발 모양"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 141쪽 1 — 깃발 모양을 오른쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"왼쪽과 오른쪽","correct":true},{"t":"위쪽과 아래쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["왼쪽이나 오른쪽으로 뒤집으면 깃발의 왼쪽과 오른쪽이 서로 바뀌어요.","위쪽과 아래쪽은 그대로예요.","왼쪽과 오른쪽이 바뀌어요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"깃발 모양"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#3','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',1,'mc','auto','『수학익힘』 82쪽 — 교실 밖에서 「4-1」로 보이려면 교실 안에서는 「4-1」을 어떻게 써야 하나요?',ARRAY['M4-2-u6-X11','M4-2-u6-X18','M4-2-u6-X14']::text[],true,'{"seq":3,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학익힘』 82쪽 — 교실 밖에서 「4-1」로 보이려면 교실 안에서는 「4-1」을 어떻게 써야 하나요?","options":[{"t":"뒤집어서 써요","correct":true},{"t":"밀어서 써요","mis":"M4-2-u6-X11"},{"t":"시계 방향으로 90°만큼 돌려서 써요","mis":"M4-2-u6-X18"},{"t":"보이는 그대로 써요","mis":"M4-2-u6-X14"}],"explanation":["창문 안쪽에 쓴 글씨를 밖에서 보면 왼쪽과 오른쪽이 바뀌어 보여요.","그래서 안에서 미리 뒤집어 써야 해요.","「4-1」을 왼쪽이나 오른쪽으로 뒤집어 써요."],"variant_rule":{"alt":[{"stem":"『수학』 140쪽 — 교실 밖에서 「4-3」으로 보이려면 교실 안에서는 「4-3」을 어떻게 써야 하나요?","options":[{"t":"뒤집어서 써요","correct":true},{"t":"밀어서 써요","mis":"M4-2-u6-X11"},{"t":"시계 방향으로 180°만큼 돌려서 써요","mis":"M4-2-u6-X18"},{"t":"보이는 그대로 써요","mis":"M4-2-u6-X14"}],"explanation":["교실 안에서 「4-3」이라고 썼더니 밖에서는 「4-3」으로 보이지 않았어요.","밖에서 보면 왼쪽과 오른쪽이 바뀌어 보이기 때문이에요.","「4-3」을 왼쪽이나 오른쪽으로 뒤집어 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#4','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',1,'mc','auto','『수학익힘』 82쪽 1 — 처음 도형을 아래쪽으로 뒤집은 도형은 어느 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X18']::text[],false,'{"seq":4,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"『수학익힘』 82쪽 1 — 처음 도형을 아래쪽으로 뒤집은 도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M4-2-u6-X10"},{"t":"㉮","mis":"M4-2-u6-X18"},{"t":"㉯","mis":"M4-2-u6-X18"}],"explanation":["아래쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀌어요.","모양과 크기는 그대로이고 방향만 바뀌어요.","㉰예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[45.0,45.0],[72.0,18.0],[72.0,45.0],[45.0,72.0],[18.0,45.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[45.0,45.0],[72.0,72.0],[45.0,72.0],[18.0,45.0],[45.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[45.0,45.0],[18.0,18.0],[45.0,18.0],[72.0,45.0],[45.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[45.0,45.0],[72.0,72.0],[72.0,45.0],[45.0,18.0],[18.0,45.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[45.0,45.0],[18.0,18.0],[18.0,45.0],[45.0,72.0],[72.0,45.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#5','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',2,'match','auto','『수학』 141~143쪽 — 사각형을 왼쪽에 적힌 대로 움직였을 때 결과가 같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"M4-2-u6-C6","difficulty":2,"kind":"match","stem":"『수학』 141~143쪽 — 사각형을 왼쪽에 적힌 대로 움직였을 때 결과가 같은 것끼리 이어 보세요.","pairs":[{"l":"위쪽으로 뒤집기","r":"아래쪽으로 뒤집기"},{"l":"오른쪽으로 뒤집기","r":"왼쪽으로 뒤집기"},{"l":"위쪽으로 2번 뒤집기","r":"처음 사각형 그대로"},{"l":"오른쪽으로 3번 뒤집기","r":"오른쪽으로 1번 뒤집기"}],"mis":"M4-2-u6-X12","explanation":["위쪽과 아래쪽 뒤집기, 왼쪽과 오른쪽 뒤집기는 결과가 같아요.","같은 쪽으로 2번 뒤집으면 처음과 같아요.","3번은 2번(처음) + 1번이라 1번 뒤집은 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
