INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#9','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C5',2,'mc','auto','『수학익힘』 83쪽 4 — 뒤집기 전과 뒤집은 후의 도형을 보고, 어느 쪽으로 뒤집었는지 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X12']::text[],false,'{"seq":9,"concept":"M4-2-u6-C5","difficulty":2,"kind":"mc","stem":"『수학익힘』 83쪽 4 — 뒤집기 전과 뒤집은 후의 도형을 보고, 어느 쪽으로 뒤집었는지 모두 고른 것은 어느 것인가요?","options":[{"t":"왼쪽, 오른쪽","correct":true},{"t":"위쪽, 아래쪽","mis":"M4-2-u6-X10"},{"t":"왼쪽","mis":"M4-2-u6-X12"},{"t":"위쪽, 아래쪽, 왼쪽, 오른쪽","mis":"M4-2-u6-X10"}],"explanation":["뒤집은 후에는 왼쪽과 오른쪽이 서로 바뀌었어요.","왼쪽으로 뒤집어도, 오른쪽으로 뒤집어도 결과가 같아요.","왼쪽, 오른쪽 모두 답이에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[36.0,18.0],[36.0,54.0],[72.0,54.0],[72.0,72.0],[18.0,72.0]]],"cap":"뒤집기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[54.0,18.0],[54.0,54.0],[18.0,54.0],[18.0,72.0],[72.0,72.0]]],"cap":"뒤집은 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_basic#10','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_basic','lesson_basic','M4-2-u6-C6',3,'mc','auto','『수학익힘』 83쪽 6 — 처음 도형을 한 번 뒤집었을 때 나올 수 없는 도형은 어느 것인가요?',ARRAY['M4-2-u6-X21','M4-2-u6-X13']::text[],false,'{"seq":10,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"『수학익힘』 83쪽 6 — 처음 도형을 한 번 뒤집었을 때 나올 수 없는 도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M4-2-u6-X21"},{"t":"㉯","mis":"M4-2-u6-X21"},{"t":"모두 나올 수 있어요","mis":"M4-2-u6-X13"}],"explanation":["한 번 뒤집으면 위아래나 좌우 가운데 한쪽이 꼭 바뀌어요.","처음 도형과 똑같은 도형은 한 번 뒤집어서는 나올 수 없어요.","㉮예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,36.0],[54.0,72.0],[72.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[54.0,72.0],[72.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#1','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',2,'ox','auto','『수학익힘』 83쪽 3 — 도형을 위쪽으로 2번 뒤집으면 처음 도형과 같아요.',ARRAY['M4-2-u6-X13']::text[],false,'{"seq":1,"concept":"M4-2-u6-C6","difficulty":2,"kind":"ox","stem":"『수학익힘』 83쪽 3 — 도형을 위쪽으로 2번 뒤집으면 처음 도형과 같아요.","answer":"O","reason_options":[{"t":"한 번 뒤집어 바뀐 위쪽과 아래쪽이 한 번 더 뒤집으면 제자리로 돌아와서","correct":true},{"t":"뒤집을 때마다 방향이 새로 바뀌어서","mis":"M4-2-u6-X13"}],"mis":"M4-2-u6-X13","explanation":["위쪽으로 한 번 뒤집으면 위쪽과 아래쪽이 바뀌어요.","한 번 더 뒤집으면 다시 바뀌어 처음과 같아져요.","같은 쪽으로 2번 뒤집으면 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[36.0,36.0],[72.0,72.0],[18.0,72.0]]],"cap":"뒤집기 전"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[36.0,36.0],[72.0,72.0],[18.0,72.0]]],"cap":"2번 뒤집은 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#2','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',2,'mc','auto','『수학익힘』 83쪽 5 — 조각을 오른쪽으로 한 번 뒤집었을 때 조각의 방향이 처음과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],false,'{"seq":2,"concept":"M4-2-u6-C6","difficulty":2,"kind":"mc","stem":"『수학익힘』 83쪽 5 — 조각을 오른쪽으로 한 번 뒤집었을 때 조각의 방향이 처음과 같은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X10"},{"t":"㉰","mis":"M4-2-u6-X10"},{"t":"모두 처음과 달라져요","mis":"M4-2-u6-X11"}],"explanation":["오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어요.","왼쪽과 오른쪽이 똑같은 조각(곧게 이어진 4칸 조각)은 뒤집어도 처음과 같아요.","㉮예요"],"asset":{"type":"geo","items":[{"w":108,"h":90,"grid":18,"poly":[[[18.0,36.0],[90.0,36.0],[90.0,54.0],[18.0,54.0]]],"cap":"㉮"},{"w":108,"h":90,"grid":18,"poly":[[[36.0,36.0],[54.0,36.0],[54.0,18.0],[72.0,18.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[36.0,72.0]]],"cap":"㉯"},{"w":108,"h":90,"grid":18,"poly":[[[36.0,54.0],[54.0,54.0],[54.0,18.0],[72.0,18.0],[72.0,72.0],[36.0,72.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#3','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C5',3,'error','auto','『수학』 143쪽 3 — 뒤집기 전과 뒤집은 후의 삼각형을 보고 친구가 「삼각형을 오른쪽으로 뒤집었어.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요?',ARRAY['M4-2-u6-X24','M4-2-u6-X12','M4-2-u6-X11']::text[],false,'{"seq":3,"concept":"M4-2-u6-C5","difficulty":3,"kind":"error","stem":"『수학』 143쪽 3 — 뒤집기 전과 뒤집은 후의 삼각형을 보고 친구가 「삼각형을 오른쪽으로 뒤집었어.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요?","options":[{"t":"오른쪽으로만 뒤집으면 왼쪽과 오른쪽만 바뀌어서 위쪽(아래쪽)으로도 뒤집어야 해요","correct":true,"mis_target":"M4-2-u6-X24"},{"t":"오른쪽이 아니라 왼쪽으로 뒤집어야 해요","mis":"M4-2-u6-X12"},{"t":"삼각형은 뒤집을 수 없어요","mis":"M4-2-u6-X11"},{"t":"뒤집은 것이 아니라 밀었어요","mis":"M4-2-u6-X11"}],"explanation":["뒤집은 후에는 위쪽과 아래쪽, 왼쪽과 오른쪽이 모두 바뀌었어요.","오른쪽으로 한 번 뒤집으면 왼쪽과 오른쪽만 바뀌어요.","오른쪽으로 뒤집은 후 위쪽이나 아래쪽으로도 뒤집어야 해요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[72.0,72.0],[72.0,18.0]]],"cap":"뒤집기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[18.0,18.0],[18.0,72.0]]],"cap":"뒤집은 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#4','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',3,'mc','auto','지도서 443쪽 — 「4-3」을 왼쪽이나 오른쪽으로 뒤집어 쓸 때 가장 왼쪽에 쓰는 것은 무엇인가요?',ARRAY['M4-2-u6-X14']::text[],false,'{"seq":4,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 443쪽 — 「4-3」을 왼쪽이나 오른쪽으로 뒤집어 쓸 때 가장 왼쪽에 쓰는 것은 무엇인가요?","options":[{"t":"뒤집은 3","correct":true},{"t":"뒤집은 4","mis":"M4-2-u6-X14"},{"t":"그대로 쓴 4","mis":"M4-2-u6-X14"},{"t":"그대로 쓴 3","mis":"M4-2-u6-X14"}],"explanation":["왼쪽이나 오른쪽으로 뒤집으면 4, -, 3의 순서도 뒤집혀요.","가장 오른쪽에 있던 3이 가장 왼쪽으로 와요.","3도 왼쪽과 오른쪽이 바뀐 모양으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#5','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C5',3,'mc','auto','『수학』 152쪽 5 — 처음 도형을 뒤집었을 때 나올 수 있는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u6-X12','M4-2-u6-X18','M4-2-u6-X11']::text[],false,'{"seq":5,"concept":"M4-2-u6-C5","difficulty":3,"kind":"mc","stem":"『수학』 152쪽 5 — 처음 도형을 뒤집었을 때 나올 수 있는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉮","mis":"M4-2-u6-X12"},{"t":"㉯, ㉱","mis":"M4-2-u6-X18"},{"t":"㉮, ㉯, ㉰, ㉱","mis":"M4-2-u6-X11"}],"explanation":["위쪽이나 아래쪽으로 뒤집으면 위아래가 바뀐 ㉮가 나와요.","왼쪽이나 오른쪽으로 뒤집으면 좌우가 바뀐 ㉰가 나와요.","㉯와 ㉱는 돌린 도형이에요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[18.0,90.0],[54.0,18.0],[90.0,18.0],[90.0,90.0]]],"cap":"처음 도형"},{"w":108,"h":108,"grid":18,"poly":[[[18.0,18.0],[54.0,90.0],[90.0,90.0],[90.0,18.0]]],"cap":"㉮"},{"w":108,"h":108,"grid":18,"poly":[[[90.0,90.0],[18.0,54.0],[18.0,18.0],[90.0,18.0]]],"cap":"㉯"},{"w":108,"h":108,"grid":18,"poly":[[[90.0,90.0],[54.0,18.0],[18.0,18.0],[18.0,90.0]]],"cap":"㉰"},{"w":108,"h":108,"grid":18,"poly":[[[18.0,18.0],[90.0,54.0],[90.0,90.0],[18.0,90.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#6','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',3,'mc','auto','『수학』 151쪽 3 — 도장을 찍었을 때 「오이」가 찍히는 도장을 들고 있는 사람은 누구인가요? 준우의 도장에는 「오이」를 위쪽으로 뒤집은 모양, 은서의 도장에는 「오이」를 왼쪽으로 뒤집은 모양(순서도 바뀐 모양), 소율이의 도장에는 「오이」가 그대로 새겨져 있어요.',ARRAY['M4-2-u6-X14','M4-2-u6-X10']::text[],false,'{"seq":6,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"『수학』 151쪽 3 — 도장을 찍었을 때 「오이」가 찍히는 도장을 들고 있는 사람은 누구인가요? 준우의 도장에는 「오이」를 위쪽으로 뒤집은 모양, 은서의 도장에는 「오이」를 왼쪽으로 뒤집은 모양(순서도 바뀐 모양), 소율이의 도장에는 「오이」가 그대로 새겨져 있어요.","options":[{"t":"은서","correct":true},{"t":"소율","mis":"M4-2-u6-X14"},{"t":"준우","mis":"M4-2-u6-X10"},{"t":"세 사람 모두","mis":"M4-2-u6-X14"}],"explanation":["도장은 새긴 모양을 왼쪽이나 오른쪽으로 뒤집은 모양으로 찍혀요.","그래서 「오이」를 왼쪽이나 오른쪽으로 뒤집어 새겨야 해요.","은서의 도장이에요 — 글자 하나하나만이 아니라 순서까지 뒤집어 새겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#7','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',3,'mc','auto','지도서 425쪽 오류 2 — 「곰」을 왼쪽이나 오른쪽으로 뒤집으면 어떻게 보이나요?',ARRAY['M4-2-u6-X14','M4-2-u6-X18']::text[],false,'{"seq":7,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 425쪽 오류 2 — 「곰」을 왼쪽이나 오른쪽으로 뒤집으면 어떻게 보이나요?","options":[{"t":"글자처럼 보이지 않아요","correct":true},{"t":"「곰」 그대로 보여요","mis":"M4-2-u6-X14"},{"t":"「문」으로 보여요","mis":"M4-2-u6-X18"},{"t":"「몸」으로 보여요","mis":"M4-2-u6-X14"}],"explanation":["「곰」의 ㄱ은 왼쪽과 오른쪽이 같지 않아요.","뒤집으면 ㄱ의 꺾인 쪽이 바뀌어 글자가 아닌 모양이 돼요.","글자를 뒤집으면 언제나 글자처럼 보이는 것은 아니에요(「응」은 그대로 보여요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#8','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C6',4,'mc','auto','『수학』 152쪽 7 — 동연이는 「도형을 아래쪽으로 3번 뒤집었어.」라고 했어요(이동 후는 위아래가 바뀐 모양). 이동 후와 같은 도형이 되도록 아래쪽으로 뒤집을 수 있는 횟수를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u6-X13']::text[],false,'{"seq":8,"concept":"M4-2-u6-C6","difficulty":4,"kind":"mc","stem":"『수학』 152쪽 7 — 동연이는 「도형을 아래쪽으로 3번 뒤집었어.」라고 했어요(이동 후는 위아래가 바뀐 모양). 이동 후와 같은 도형이 되도록 아래쪽으로 뒤집을 수 있는 횟수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1번, 3번, 5번","correct":true},{"t":"2번, 4번","mis":"M4-2-u6-X13"},{"t":"3번","mis":"M4-2-u6-X13"},{"t":"1번, 2번, 3번","mis":"M4-2-u6-X13"}],"explanation":["아래쪽으로 한 번 뒤집으면 위아래가 바뀌고, 두 번이면 처음으로 돌아와요.","그래서 1번, 3번, 5번처럼 홀수 번 뒤집으면 위아래가 바뀐 모양이에요.","동연이의 설명은 맞아요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[90.0,90.0],[18.0,90.0],[36.0,54.0]]],"cap":"이동 전"},{"w":108,"h":108,"grid":18,"poly":[[[36.0,90.0],[72.0,90.0],[72.0,54.0],[90.0,18.0],[18.0,18.0],[36.0,54.0]]],"cap":"이동 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#9','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C5',4,'mc','auto','『수학』 143쪽 2 — 사각형(왼쪽 변이 짧고 윗변이 비스듬한 사각형)을 위쪽으로 뒤집으면 비스듬한 변은 어디로 가나요?',ARRAY['M4-2-u6-X11','M4-2-u6-X10']::text[],true,'{"seq":9,"concept":"M4-2-u6-C5","difficulty":4,"kind":"mc","stem":"『수학』 143쪽 2 — 사각형(왼쪽 변이 짧고 윗변이 비스듬한 사각형)을 위쪽으로 뒤집으면 비스듬한 변은 어디로 가나요?","options":[{"t":"아래쪽","correct":true},{"t":"위쪽에 그대로 있어요","mis":"M4-2-u6-X11"},{"t":"오른쪽","mis":"M4-2-u6-X10"},{"t":"왼쪽","mis":"M4-2-u6-X10"}],"explanation":["위쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀌어요.","위에 있던 비스듬한 변은 아래쪽으로 가요.","짧은 변은 그대로 왼쪽에 있어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[72.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"처음 도형"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 143쪽 2 — 사각형(왼쪽 변이 짧고 윗변이 비스듬한 사각형)을 오른쪽으로 뒤집으면 짧은 변은 어디로 가나요?","options":[{"t":"오른쪽","correct":true},{"t":"왼쪽에 그대로 있어요","mis":"M4-2-u6-X11"},{"t":"아래쪽","mis":"M4-2-u6-X10"},{"t":"위쪽","mis":"M4-2-u6-X10"}],"explanation":["오른쪽으로 뒤집으면 왼쪽과 오른쪽이 서로 바뀌어요.","왼쪽에 있던 짧은 변은 오른쪽으로 가요.","비스듬한 변은 그대로 위쪽에 있어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[72.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"처음 도형"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L04_challenge#10','math',4,2,'u6','L04','tb_g4_2_math_u6_L04_challenge','lesson_challenge','M4-2-u6-C5',4,'mc','auto','지도서 416쪽 유의 ② — 뒤집은 도형을 모눈종이에 그릴 때 바르게 그리는 방법은 어느 것인가요?',ARRAY['M4-2-u6-X22','M4-2-u6-X11']::text[],false,'{"seq":10,"concept":"M4-2-u6-C5","difficulty":4,"kind":"mc","stem":"지도서 416쪽 유의 ② — 뒤집은 도형을 모눈종이에 그릴 때 바르게 그리는 방법은 어느 것인가요?","options":[{"t":"모눈은 그대로 두고 도형만 뒤집어 그려요","correct":true},{"t":"모눈종이까지 함께 뒤집어 그려요","mis":"M4-2-u6-X22"},{"t":"도형을 뒤집지 않고 옆으로 옮겨 그려요","mis":"M4-2-u6-X11"},{"t":"도형의 크기를 조금 바꾸어 그려요","mis":"M4-2-u6-X11"}],"explanation":["움직이는 것은 도형이고, 배경의 모눈은 움직이지 않아요.","도형의 한 꼭짓점이나 변이 어디로 가는지 먼저 표시해요.","모양과 크기는 그대로, 방향만 바꾸어 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#1','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',1,'mc','auto','『수학』 145쪽 — 시곗바늘이 돌아가는 방향과 반대인 방향을 무엇이라고 하나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X01']::text[],false,'{"seq":1,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"『수학』 145쪽 — 시곗바늘이 돌아가는 방향과 반대인 방향을 무엇이라고 하나요?","options":[{"t":"시계 반대 방향","correct":true},{"t":"시계 방향","mis":"M4-2-u6-X15"},{"t":"오른쪽 방향","mis":"M4-2-u6-X01"},{"t":"위쪽 방향","mis":"M4-2-u6-X01"}],"explanation":["시곗바늘이 돌아가는 방향은 시계 방향이에요.","그 반대로 도는 방향은 시계 반대 방향이에요.","돌리기를 말할 때는 방향과 각도를 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#2','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',1,'mc','auto','『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 반대 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],true,'{"seq":2,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 반대 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?","options":[{"t":"왼쪽","correct":true},{"t":"오른쪽","mis":"M4-2-u6-X15"},{"t":"아래쪽","mis":"M4-2-u6-X16"},{"t":"위쪽 그대로","mis":"M4-2-u6-X16"}],"explanation":["시계 반대 방향은 시곗바늘이 도는 쪽의 반대쪽이에요.","위쪽에 있던 지붕이 90°만큼 돌아간 자리를 따라가요.","파란색 지붕은 왼쪽으로 가요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[90.0,45.0],[81.0,45.0],[81.0,90.0],[27.0,90.0],[27.0,45.0],[18.0,45.0]]],"cap":"집 모양"}],"tag":false},"variant_rule":{"alt":[{"stem":"『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?","options":[{"t":"오른쪽","correct":true},{"t":"왼쪽","mis":"M4-2-u6-X15"},{"t":"아래쪽","mis":"M4-2-u6-X16"},{"t":"위쪽 그대로","mis":"M4-2-u6-X16"}],"explanation":["시계 방향은 시곗바늘이 도는 쪽이에요.","위쪽에 있던 지붕이 90°만큼 돌아간 자리를 따라가요.","파란색 지붕은 오른쪽으로 가요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[90.0,45.0],[81.0,45.0],[81.0,90.0],[27.0,90.0],[27.0,45.0],[18.0,45.0]]],"cap":"집 모양"}],"tag":false}},{"stem":"『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 방향으로 180°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?","options":[{"t":"아래쪽","correct":true},{"t":"왼쪽","mis":"M4-2-u6-X16"},{"t":"오른쪽","mis":"M4-2-u6-X16"},{"t":"위쪽 그대로","mis":"M4-2-u6-X16"}],"explanation":["시계 방향은 시곗바늘이 도는 쪽이에요.","위쪽에 있던 지붕이 180°만큼 돌아간 자리를 따라가요.","파란색 지붕은 아래쪽으로 가요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[90.0,45.0],[81.0,45.0],[81.0,90.0],[27.0,90.0],[27.0,45.0],[18.0,45.0]]],"cap":"집 모양"}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#3','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',1,'mc','auto','『수학』 147쪽 2 — 도형을 돌리면 모양과 방향은 어떻게 되나요?',ARRAY['M4-2-u6-X11']::text[],false,'{"seq":3,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"『수학』 147쪽 2 — 도형을 돌리면 모양과 방향은 어떻게 되나요?","options":[{"t":"모양은 변하지 않고 방향은 변해요","correct":true},{"t":"모양도 방향도 그대로예요","mis":"M4-2-u6-X11"},{"t":"모양이 변하고 방향은 그대로예요","mis":"M4-2-u6-X11"},{"t":"크기가 변해요","mis":"M4-2-u6-X11"}],"explanation":["집 모양과 삼각형을 여러 방향과 각도로 돌려 보았어요.","모양과 크기는 그대로였어요.","돌린 방향과 각도에 따라 방향이 변했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
