INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#6','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',2,'match','auto','『수학』 147쪽 2 — 삼각형을 돌린 결과가 같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"M4-2-u6-C8","difficulty":2,"kind":"match","stem":"『수학』 147쪽 2 — 삼각형을 돌린 결과가 같은 것끼리 이어 보세요.","pairs":[{"l":"시계 반대 방향으로 90°","r":"시계 방향으로 270°"},{"l":"시계 반대 방향으로 270°","r":"시계 방향으로 90°"},{"l":"시계 반대 방향으로 180°","r":"시계 방향으로 180°"},{"l":"시계 반대 방향으로 360°","r":"돌리기 전 처음 도형"}],"mis":"M4-2-u6-X17","explanation":["한 바퀴는 360°예요.","시계 반대 방향으로 ○°는 시계 방향으로 360° − ○°와 같아요.","180°는 어느 쪽이든 같고, 360°는 처음과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#7','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',2,'mc','auto','『수학』 147쪽 3 — 사각형을 어떻게 돌렸나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":7,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학』 147쪽 3 — 사각형을 어떻게 돌렸나요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"왼쪽이나 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,36.0],[72.0,54.0],[18.0,72.0],[18.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#8','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C7',2,'mc','auto','『수학』 147쪽 4 — 마지막 퍼즐 조각을 빈 곳에 알맞게 넣으려면 조각을 어떻게 돌려야 하나요? (빈 곳은 튀어나온 부분이 위쪽에, 조각은 튀어나온 부분이 오른쪽에 있어요.)',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":8,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학』 147쪽 4 — 마지막 퍼즐 조각을 빈 곳에 알맞게 넣으려면 조각을 어떻게 돌려야 하나요? (빈 곳은 튀어나온 부분이 위쪽에, 조각은 튀어나온 부분이 오른쪽에 있어요.)","options":[{"t":"시계 반대 방향으로 90°만큼 돌려요","correct":true},{"t":"시계 방향으로 90°만큼 돌려요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌려요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 뒤집어요","mis":"M4-2-u6-X18"}],"explanation":["조각의 튀어나온 부분을 오른쪽에서 위쪽으로 옮겨야 해요.","오른쪽 → 위쪽은 시곗바늘이 도는 쪽의 반대로 90°예요.","시계 반대 방향으로 90°(또는 시계 방향으로 270°)만큼 돌려요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"dash":[[[21.6,68.4],[21.6,32.4]],[[21.6,32.4],[34.2,32.4]],[[34.2,32.4],[32.4,21.6]],[[32.4,21.6],[46.8,21.6]],[[46.8,21.6],[45.0,32.4]],[[45.0,32.4],[57.6,32.4]],[[57.6,32.4],[57.6,68.4]],[[57.6,68.4],[21.6,68.4]]],"cap":"빈 곳(점선)"},{"w":90,"h":90,"grid":18,"poly":[[[21.6,27.0],[57.6,27.0],[57.6,39.6],[68.4,37.8],[68.4,52.2],[57.6,50.4],[57.6,63.0],[21.6,63.0]]],"cap":"퍼즐 조각"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#9','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',2,'ox','auto','『수학익힘』 84쪽 — 빈 곳과 퍼즐 조각을 비교하니 조각이 빈 곳과 위아래·좌우가 모두 거꾸로 놓여 있었어요. 이 조각은 시계 방향으로 180°만큼 돌려도, 시계 반대 방향으로 180°만큼 돌려도 빈 곳에 알맞게 들어가요.',ARRAY['M4-2-u6-X15']::text[],false,'{"seq":9,"concept":"M4-2-u6-C8","difficulty":2,"kind":"ox","stem":"『수학익힘』 84쪽 — 빈 곳과 퍼즐 조각을 비교하니 조각이 빈 곳과 위아래·좌우가 모두 거꾸로 놓여 있었어요. 이 조각은 시계 방향으로 180°만큼 돌려도, 시계 반대 방향으로 180°만큼 돌려도 빈 곳에 알맞게 들어가요.","answer":"O","reason_options":[{"t":"180°는 반 바퀴라 어느 쪽으로 돌려도 같은 자리에 와서","correct":true},{"t":"돌리는 방향이 다르면 언제나 결과가 달라서","mis":"M4-2-u6-X15"}],"mis":"M4-2-u6-X15","explanation":["180°는 한 바퀴 360°의 절반이에요.","시계 방향으로 반 바퀴와 시계 반대 방향으로 반 바퀴는 같은 곳에 멈춰요.","그래서 두 방향 모두 180°가 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_basic#10','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_basic','lesson_basic','M4-2-u6-C8',3,'mc','auto','『수학익힘』 85쪽 4 — 처음 조각을 시계 방향이나 시계 반대 방향으로 돌렸을 때 나올 수 없는 조각은 어느 것인가요?',ARRAY['M4-2-u6-X21']::text[],false,'{"seq":10,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"『수학익힘』 85쪽 4 — 처음 조각을 시계 방향이나 시계 반대 방향으로 돌렸을 때 나올 수 없는 조각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X21"},{"t":"㉰","mis":"M4-2-u6-X21"},{"t":"㉱","mis":"M4-2-u6-X21"}],"explanation":["돌리면 모양은 그대로이고 방향만 바뀌어요.","㉯는 처음 조각을 뒤집은 모양이라 아무리 돌려도 나올 수 없어요.","㉮는 180°, ㉰는 시계 방향으로 270°, ㉱는 360°만큼 돌린 조각이에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[54.0,36.0],[36.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"처음 조각"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,72.0],[18.0,72.0],[18.0,54.0],[36.0,54.0],[36.0,18.0],[54.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,18.0],[18.0,18.0],[18.0,36.0],[36.0,36.0],[36.0,72.0],[54.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[18.0,18.0],[36.0,18.0],[36.0,36.0],[72.0,36.0],[72.0,54.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[54.0,36.0],[36.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#1','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C8',2,'ox','auto','『수학』 147쪽 2 — 도형을 시계 방향으로 180°만큼 돌린 것과 시계 반대 방향으로 180°만큼 돌린 것은 서로 같아요.',ARRAY['M4-2-u6-X15']::text[],false,'{"seq":1,"concept":"M4-2-u6-C8","difficulty":2,"kind":"ox","stem":"『수학』 147쪽 2 — 도형을 시계 방향으로 180°만큼 돌린 것과 시계 반대 방향으로 180°만큼 돌린 것은 서로 같아요.","answer":"O","reason_options":[{"t":"180°는 반 바퀴라 어느 쪽으로 돌려도 같은 자리에 와서","correct":true},{"t":"시계 방향과 시계 반대 방향은 언제나 결과가 달라서","mis":"M4-2-u6-X15"}],"mis":"M4-2-u6-X15","explanation":["삼각형을 시계 방향과 시계 반대 방향으로 180°만큼 돌려 비교했어요.","두 도형의 방향이 같았어요.","180°는 어느 쪽으로 돌려도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#2','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C7',2,'mc','auto','『수학익힘』 84쪽 3 — 도형을 시계 방향으로 몇 도만큼 돌렸나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":2,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학익힘』 84쪽 3 — 도형을 시계 방향으로 몇 도만큼 돌렸나요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 270°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"위쪽이나 아래쪽으로 뒤집었어요","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[72.0,72.0],[18.0,72.0],[18.0,54.0],[36.0,54.0],[36.0,36.0],[18.0,36.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[72.0,72.0],[18.0,72.0],[18.0,18.0],[36.0,18.0],[36.0,36.0],[54.0,36.0],[54.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#3','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C7',3,'error','auto','『수학』 147쪽 3 — 돌리기 전과 돌린 후의 사각형을 보고 친구가 「사각형을 시계 반대 방향으로 90°만큼 돌렸어.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":3,"concept":"M4-2-u6-C7","difficulty":3,"kind":"error","stem":"『수학』 147쪽 3 — 돌리기 전과 돌린 후의 사각형을 보고 친구가 「사각형을 시계 반대 방향으로 90°만큼 돌렸어.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요?","options":[{"t":"위쪽에 있던 짧은 변이 오른쪽으로 갔으니 시계 방향으로 90°만큼 돌린 거예요","correct":true,"mis_target":"M4-2-u6-X15"},{"t":"90°가 아니라 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"돌린 것이 아니라 뒤집은 거예요","mis":"M4-2-u6-X18"},{"t":"잘못된 점이 없어요","mis":"M4-2-u6-X15"}],"explanation":["사각형의 위쪽에 있던 짧은 변이 오른쪽으로 갔어요.","위쪽 → 오른쪽은 시곗바늘이 도는 쪽으로 90°예요.","시계 방향으로 90°(또는 시계 반대 방향으로 270°)만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,36.0],[72.0,54.0],[18.0,72.0],[18.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#4','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C8',3,'mc','auto','『수학』 151쪽 4 — 돌리기 전과 돌린 후의 도형을 보고 알맞은 것을 고르세요.',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X17']::text[],false,'{"seq":4,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"『수학』 151쪽 4 — 돌리기 전과 돌린 후의 도형을 보고 알맞은 것을 고르세요.","options":[{"t":"시계 방향으로 270°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 270°만큼 돌렸어요","mis":"M4-2-u6-X17"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 270°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[36.0,54.0],[36.0,72.0],[18.0,72.0],[18.0,36.0],[36.0,36.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[18.0,18.0],[54.0,18.0],[54.0,54.0],[72.0,54.0],[72.0,72.0],[36.0,72.0],[36.0,54.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#5','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C7',3,'mc','auto','『수학익힘』 85쪽 5 — 삼각형을 어떻게 돌렸나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":5,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"『수학익힘』 85쪽 5 — 삼각형을 어떻게 돌렸나요?","options":[{"t":"시계 방향으로 180°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"왼쪽이나 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 180°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[18.0,54.0],[54.0,18.0],[90.0,90.0]]],"cap":"돌리기 전"},{"w":108,"h":108,"grid":18,"poly":[[[90.0,54.0],[54.0,90.0],[18.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#6','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C8',3,'ox','auto','지도서 424쪽 오류 1 — 도형을 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것은 언제나 서로 같아요.',ARRAY['M4-2-u6-X18']::text[],false,'{"seq":6,"concept":"M4-2-u6-C8","difficulty":3,"kind":"ox","stem":"지도서 424쪽 오류 1 — 도형을 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것은 언제나 서로 같아요.","answer":"X","reason_options":[{"t":"뒤집기와 돌리기는 다른 방법이라 도형에 따라 결과가 달라서","correct":true},{"t":"아래쪽 뒤집기와 180° 돌리기는 둘 다 위아래를 바꾸어서","mis":"M4-2-u6-X18"}],"mis":"M4-2-u6-X18","explanation":["T처럼 왼쪽과 오른쪽이 똑같은 도형은 두 결과가 같아요.","하지만 깃발 모양처럼 왼쪽과 오른쪽이 다른 도형은 결과가 달라요.","그래서 「언제나」 같지는 않아요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"깃발 모양"},{"w":90,"h":108,"grid":18,"poly":[[[18.0,90.0],[72.0,72.0],[36.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"아래쪽으로 뒤집기"},{"w":90,"h":108,"grid":18,"poly":[[[72.0,90.0],[18.0,72.0],[54.0,54.0],[54.0,18.0],[72.0,18.0]]],"cap":"시계 방향으로 180°"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#7','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C8',3,'mc','auto','지도서 425쪽 오류 2 — 「곰」을 시계 방향으로 180°만큼 돌리면 어떤 글자로 보이나요?',ARRAY['M4-2-u6-X26','M4-2-u6-X16']::text[],true,'{"seq":7,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"지도서 425쪽 오류 2 — 「곰」을 시계 방향으로 180°만큼 돌리면 어떤 글자로 보이나요?","options":[{"t":"문","correct":true},{"t":"곰","mis":"M4-2-u6-X26"},{"t":"글자처럼 보이지 않아요","mis":"M4-2-u6-X26"},{"t":"몸","mis":"M4-2-u6-X16"}],"explanation":["「곰」을 반 바퀴 돌리면 위아래와 좌우가 모두 바뀌어요.","ㄱ은 ㄴ처럼, ㅗ는 ㅜ처럼, 아래의 ㅁ은 위로 가요.","그래서 「문」으로 보여요."],"variant_rule":{"alt":[{"stem":"지도서 425쪽 오류 2 — 「응」을 시계 방향으로 90°만큼 돌리면 어떻게 보이나요?","options":[{"t":"글자처럼 보이지 않아요","correct":true},{"t":"「응」 그대로 보여요","mis":"M4-2-u6-X26"},{"t":"「문」으로 보여요","mis":"M4-2-u6-X16"},{"t":"「을」로 보여요","mis":"M4-2-u6-X16"}],"explanation":["「응」은 180°나 360°만큼 돌리면 「응」으로 보여요.","하지만 90°나 270°만큼 돌리면 가로줄이 세로줄이 돼요.","그래서 글자처럼 보이지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#8','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C7',4,'mc','auto','『수학익힘』 84쪽 2 — 처음 도형을 시계 반대 방향으로 270°만큼 돌린 도형은 어느 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":8,"concept":"M4-2-u6-C7","difficulty":4,"kind":"mc","stem":"『수학익힘』 84쪽 2 — 처음 도형을 시계 반대 방향으로 270°만큼 돌린 도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M4-2-u6-X15"},{"t":"㉯","mis":"M4-2-u6-X16"},{"t":"㉰","mis":"M4-2-u6-X18"}],"explanation":["시계 반대 방향은 시곗바늘이 도는 쪽의 반대쪽이에요.","처음 도형의 위쪽 부분이 270°만큼 돌아간 자리를 따라가요.","㉱예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[18.0,36.0],[72.0,18.0],[72.0,72.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,72.0],[72.0,72.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[72.0,54.0],[18.0,72.0],[18.0,18.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#9','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C8',4,'essay','teacher','『수학』 147쪽 4 — 마지막 퍼즐 조각을 빈 곳에 넣으려면 조각을 어떻게 돌려야 하는지 두 가지 방법으로 설명하고, 두 방법의 결과가 같은 까닭을 써 보세요. (빈 곳은 튀어나온 부분이 위쪽에, 조각은 튀어나온 부분이 오른쪽에 있어요.)','{}'::text[],false,'{"seq":9,"concept":"M4-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 147쪽 4 — 마지막 퍼즐 조각을 빈 곳에 넣으려면 조각을 어떻게 돌려야 하는지 두 가지 방법으로 설명하고, 두 방법의 결과가 같은 까닭을 써 보세요. (빈 곳은 튀어나온 부분이 위쪽에, 조각은 튀어나온 부분이 오른쪽에 있어요.)","answer_guide":{"answer":"방법 1: 시계 반대 방향으로 90°만큼 돌려요. 방법 2: 시계 방향으로 270°만큼 돌려요. 한 바퀴는 360°라서 시계 반대 방향으로 90°는 시계 방향으로 360° − 90° = 270°와 같은 자리예요.","scoring_points":["시계 반대 방향 90°","시계 방향 270°","360°에서 빼어 같은 까닭"]},"explanation":["튀어나온 부분을 오른쪽에서 위쪽으로 옮겨요.","시계 반대 방향으로 90°예요.","시계 방향으로는 270°예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"dash":[[[21.6,68.4],[21.6,32.4]],[[21.6,32.4],[34.2,32.4]],[[34.2,32.4],[32.4,21.6]],[[32.4,21.6],[46.8,21.6]],[[46.8,21.6],[45.0,32.4]],[[45.0,32.4],[57.6,32.4]],[[57.6,32.4],[57.6,68.4]],[[57.6,68.4],[21.6,68.4]]],"cap":"빈 곳(점선)"},{"w":90,"h":90,"grid":18,"poly":[[[21.6,27.0],[57.6,27.0],[57.6,39.6],[68.4,37.8],[68.4,52.2],[57.6,50.4],[57.6,63.0],[21.6,63.0]]],"cap":"퍼즐 조각"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L05_challenge#10','math',4,2,'u6','L05','tb_g4_2_math_u6_L05_challenge','lesson_challenge','M4-2-u6-C7',4,'error','auto','『수학익힘』 85쪽 퐁당 — 초록 조각을 돌려서 빈 곳을 채우려고 해요. 친구는 「조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳을 채울 수 있어.」라고 풀었어요. 잘못된 부분을 바르게 고친 것은 어느 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":10,"concept":"M4-2-u6-C7","difficulty":4,"kind":"error","stem":"『수학익힘』 85쪽 퐁당 — 초록 조각을 돌려서 빈 곳을 채우려고 해요. 친구는 「조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳을 채울 수 있어.」라고 풀었어요. 잘못된 부분을 바르게 고친 것은 어느 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌려야 빈 곳을 채울 수 있어요","correct":true,"mis_target":"M4-2-u6-X15"},{"t":"시계 반대 방향으로 180°만큼 돌려야 해요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 뒤집어야 해요","mis":"M4-2-u6-X18"},{"t":"시계 반대 방향으로 90°가 맞아요","mis":"M4-2-u6-X15"}],"explanation":["조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳과 모양이 맞지 않아요.","빈 곳은 조각을 시곗바늘이 도는 쪽으로 90°만큼 돌린 모양이에요.","시계 방향으로 90°(또는 시계 반대 방향으로 270°)만큼 돌려요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[36.0,36.0],[36.0,18.0],[54.0,18.0],[54.0,36.0],[72.0,36.0],[72.0,54.0],[36.0,54.0],[36.0,72.0],[18.0,72.0]]],"cap":"조각"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,18.0],[54.0,36.0],[72.0,36.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[36.0,72.0],[36.0,36.0],[18.0,36.0],[18.0,18.0]]],"cap":"빈 곳의 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#1','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',1,'mc','auto','『수학』 148쪽 1 — 점과 띠가 그려진 모양 하나로 뒤집기를 이용하여 무늬를 만들었어요. 첫째 줄은 모양을 어느 쪽으로 뒤집기를 반복하여 만들었나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X19']::text[],false,'{"seq":1,"concept":"M4-2-u6-C9","difficulty":1,"kind":"mc","stem":"『수학』 148쪽 1 — 점과 띠가 그려진 모양 하나로 뒤집기를 이용하여 무늬를 만들었어요. 첫째 줄은 모양을 어느 쪽으로 뒤집기를 반복하여 만들었나요?","options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"M4-2-u6-X10"},{"t":"위쪽","mis":"M4-2-u6-X10"},{"t":"뒤집지 않고 오른쪽으로 밀었어요","mis":"M4-2-u6-X19"}],"explanation":["첫째 줄에서 이웃한 두 칸을 견주어요.","오른쪽 칸은 왼쪽 칸의 왼쪽과 오른쪽이 바뀐 모양이에요.","모양을 오른쪽으로 뒤집기를 반복했어요."],"asset":{"type":"geo","items":[{"w":240,"h":30,"grid":30,"poly":[[[10.25,8.46],[8.46,10.25],[5.94,10.25],[4.15,8.46],[4.15,5.94],[5.94,4.15],[8.46,4.15],[10.25,5.94]],[[11.4,30.0],[11.76,26.37],[12.82,22.88],[14.53,19.67],[16.85,16.85],[19.67,14.53],[22.88,12.82],[26.37,11.76],[30.0,11.4],[30.0,18.0],[27.66,18.23],[25.41,18.91],[23.33,20.02],[21.51,21.51],[20.02,23.33],[18.91,25.41],[18.23,27.66],[18.0,30.0]],[[49.75,8.46],[51.54,10.25],[54.06,10.25],[55.85,8.46],[55.85,5.94],[54.06,4.15],[51.54,4.15],[49.75,5.94]],[[48.6,30.0],[48.24,26.37],[47.18,22.88],[45.47,19.67],[43.15,16.85],[40.33,14.53],[37.12,12.82],[33.63,11.76],[30.0,11.4],[30.0,18.0],[32.34,18.23],[34.59,18.91],[36.67,20.02],[38.49,21.51],[39.98,23.33],[41.09,25.41],[41.77,27.66],[42.0,30.0]],[[70.25,8.46],[68.46,10.25],[65.94,10.25],[64.15,8.46],[64.15,5.94],[65.94,4.15],[68.46,4.15],[70.25,5.94]],[[71.4,30.0],[71.76,26.37],[72.82,22.88],[74.53,19.67],[76.85,16.85],[79.67,14.53],[82.88,12.82],[86.37,11.76],[90.0,11.4],[90.0,18.0],[87.66,18.23],[85.41,18.91],[83.33,20.02],[81.51,21.51],[80.02,23.33],[78.91,25.41],[78.23,27.66],[78.0,30.0]],[[109.75,8.46],[111.54,10.