INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#3','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',1,'ox','auto','『수학』 149쪽 2 — 나만의 무늬를 만드는 방법을 쓸 때, 한 번에 한 가지 이동 방법만 사용해요.',ARRAY['M4-2-u6-X19']::text[],false,'{"seq":3,"concept":"M4-2-u6-C10","difficulty":1,"kind":"ox","stem":"『수학』 149쪽 2 — 나만의 무늬를 만드는 방법을 쓸 때, 한 번에 한 가지 이동 방법만 사용해요.","answer":"O","reason_options":[{"t":"한 번에 밀기·뒤집기·돌리기 가운데 하나씩 써야 친구가 똑같이 만들 수 있어서","correct":true},{"t":"한 번에 여러 이동을 섞어 써야 무늬가 되어서","mis":"M4-2-u6-X19"}],"mis":"M4-2-u6-X19","explanation":["「보기」는 돌리기로 첫 줄을 만들고, 밀기로 무늬를 만들었어요.","한 번에 한 가지 이동 방법만 써요.","그래야 만든 방법을 정확하게 설명할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#4','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',1,'mc','auto','『수학』 149쪽 2 「보기」 — 「반원 모양을 시계 방향으로 180° 돌리기를 반복하여 첫 줄의 모양을 만들고, 이 모양을 아래쪽으로 밀기를 반복하여 무늬를 만들었습니다.」 이렇게 만든 무늬는 어느 것인가요?',ARRAY['M4-2-u6-X19','M4-2-u6-X16']::text[],false,'{"seq":4,"concept":"M4-2-u6-C9","difficulty":1,"kind":"mc","stem":"『수학』 149쪽 2 「보기」 — 「반원 모양을 시계 방향으로 180° 돌리기를 반복하여 첫 줄의 모양을 만들고, 이 모양을 아래쪽으로 밀기를 반복하여 무늬를 만들었습니다.」 이렇게 만든 무늬는 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X19"},{"t":"㉰","mis":"M4-2-u6-X19"},{"t":"㉱","mis":"M4-2-u6-X16"}],"explanation":["첫 줄은 반원이 아래·위·아래·위로 번갈아 나와요(180°씩 돌리기).","줄은 아래쪽으로 밀어서 늘리니 모든 줄이 첫 줄과 같아요.","㉮예요"],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":30,"poly":[[[3.6,30.0],[4.47,25.64],[6.94,21.94],[10.64,19.47],[15.0,18.6],[19.36,19.47],[23.06,21.94],[25.53,25.64],[26.4,30.0]],[[56.4,0.0],[55.53,4.36],[53.06,8.06],[49.36,10.53],[45.0,11.4],[40.64,10.53],[36.94,8.06],[34.47,4.36],[33.6,0.0]],[[63.6,30.0],[64.47,25.64],[66.94,21.94],[70.64,19.47],[75.0,18.6],[79.36,19.47],[83.06,21.94],[85.53,25.64],[86.4,30.0]],[[116.4,0.0],[115.53,4.36],[113.06,8.06],[109.36,10.53],[105.0,11.4],[100.64,10.53],[96.94,8.06],[94.47,4.36],[93.6,0.0]],[[3.6,60.0],[4.47,55.64],[6.94,51.94],[10.64,49.47],[15.0,48.6],[19.36,49.47],[23.06,51.94],[25.53,55.64],[26.4,60.0]],[[56.4,30.0],[55.53,34.36],[53.06,38.06],[49.36,40.53],[45.0,41.4],[40.64,40.53],[36.94,38.06],[34.47,34.36],[33.6,30.0]],[[63.6,60.0],[64.47,55.64],[66.94,51.94],[70.64,49.47],[75.0,48.6],[79.36,49.47],[83.06,51.94],[85.53,55.64],[86.4,60.0]],[[116.4,30.0],[115.53,34.36],[113.06,38.06],[109.36,40.53],[105.0,41.4],[100.64,40.53],[96.94,38.06],[94.47,34.36],[93.6,30.0]],[[3.6,90.0],[4.47,85.64],[6.94,81.94],[10.64,79.47],[15.0,78.6],[19.