INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#6','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C9',2,'mc','auto','『수학익힘』 86쪽 — 대각선 조각 모양으로 무늬를 만들었어요. 첫째 줄은 어떻게 만들었나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18','M4-2-u6-X19']::text[],false,'{"seq":6,"concept":"M4-2-u6-C9","difficulty":2,"kind":"mc","stem":"『수학익힘』 86쪽 — 대각선 조각 모양으로 무늬를 만들었어요. 첫째 줄은 어떻게 만들었나요?","options":[{"t":"모양을 시계 방향으로 180°만큼 돌리기를 반복했어요","correct":true},{"t":"모양을 시계 방향으로 90°만큼 돌리기를 반복했어요","mis":"M4-2-u6-X16"},{"t":"모양을 오른쪽으로 뒤집기를 반복했어요","mis":"M4-2-u6-X18"},{"t":"모양을 오른쪽으로 밀기를 반복했어요","mis":"M4-2-u6-X19"}],"explanation":["첫째 줄의 이웃한 두 칸을 견주면 위아래와 좌우가 모두 바뀌었어요.","오른쪽으로 뒤집으면 좌우만 바뀌어 이 모양이 나오지 않아요.","시계 방향(또는 시계 반대 방향)으로 180°만큼 돌리기를 반복했어요."],"asset":{"type":"geo","items":[{"w":240,"h":30,"grid":30,"poly":[[[16.5,0],[30,0],[30,30]],[[43.5,30.0],[30.0,30.0],[30.0,0.0]],[[76.5,0.0],[90.0,0.0],[90.0,30.0]],[[103.5,30.0],[90.0,30.0],[90.0,0.0]],[[136.5,0.0],[150.0,0.0],[150.0,30.0]],[[163.5,30.0],[150.0,30.0],[150.0,0.0]],[[196.5,0.0],[210.0,0.0],[210.0,30.0]],[[223.5,30.0],[210.0,30.0],[210.0,0.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#7','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',2,'mc','auto','『수학익힘』 86쪽 — 모양을 시계 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들고, 이 줄을 아래쪽으로 밀기 하여 무늬를 만들었어요. 빈칸(?)에 알맞은 모양은 어느 것인가요?',ARRAY['M4-2-u6-X19']::text[],false,'{"seq":7,"concept":"M4-2-u6-C10","difficulty":2,"kind":"mc","stem":"『수학익힘』 86쪽 — 모양을 시계 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들고, 이 줄을 아래쪽으로 밀기 하여 무늬를 만들었어요. 빈칸(?)에 알맞은 모양은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"M4-2-u6-X19"},{"t":"㉮","mis":"M4-2-u6-X19"},{"t":"㉱","mis":"M4-2-u6-X19"}],"explanation":["줄을 아래쪽으로 밀었으니 빈칸은 바로 위 칸과 같은 모양이에요.","빈칸의 줄에서 바로 왼쪽 칸을 180°만큼 돌린 모양과도 같아요.","㉰예요"],"asset":{"type":"geo","items":[{"w":240,"h":150,"grid":30,"poly":[[[16.5,0],[30,0],[30,30]],[[43.5,30.0],[30.0,30.0],[30.0,0.0]],[[76.5,0.0],[90.0,0.0],[90.0,30.0]],[[103.5,30.0],[90.0,30.0],[90.0,0.0]],[[136.5,0.0],[150.0,0.0],[150.0,30.0]],[[163.5,30.0],[150.0,30.0],[150.0,0.0]],[[196.5,0.0],[210.0,0.0],[210.0,30.0]],[[223.5,30.0],[210.0,30.0],[210.0,0.0]],[[16.5,30],[30,30],[30,60]],[[43.5,60.0],[30.0,60.0],[30.0,30.0]],[[76.5,30.0],[90.0,30.0],[90.0,60.0]],[[103.5,60.0],[90.0,60.0],[90.0,30.0]],[[136.5,30.0],[150.0,30.0],[150.0,60.0]],[[163.5,60.0],[150.0,60.0],[150.0,30.0]],[[196.5,30.0],[210.0,30.0],[210.0,60.0]],[[16.5,60],[30,60],[30,90]],[[43.5,90.0],[30.0,90.0],[30.0,60.0]],[[76.5,60.0],[90.0,60.0],[90.0,90.0]],[[103.5,90.0],[90.0,90.0],[90.0,60.0]],[[136.5,60.0],[150.0,60.0],[150.0,90.0]],[[163.5,90.0],[150.0,90.0],[150.0,60.0]],[[196.5,60.0],[210.0,60.0],[210.0,90.0]],[[223.5,90.0],[210.0,90.0],[210.0,60.0]],[[16.5,90],[30,90],[30,120]],[[43.5,120.0],[30.0,120.0],[30.0,90.0]],[[76.5,90.0],[90.0,90.0],[90.0,120.0]],[[103.5,120.0],[90.0,120.0],[90.0,90.0]],[[136.5,90.0],[150.0,90.0],[150.0,120.0]],[[163.5,120.0],[