INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#8','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',2,'ox','auto','『수학익힘』 86쪽 — 「모양을 시계 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들었어요.」와 「모양을 시계 반대 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들었어요.」는 같은 무늬를 설명해요.',ARRAY['M4-2-u6-X20']::text[],false,'{"seq":8,"concept":"M4-2-u6-C10","difficulty":2,"kind":"ox","stem":"『수학익힘』 86쪽 — 「모양을 시계 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들었어요.」와 「모양을 시계 반대 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들었어요.」는 같은 무늬를 설명해요.","answer":"O","reason_options":[{"t":"180°는 어느 쪽으로 돌려도 같아서 같은 무늬도 여러 방법으로 설명할 수 있어서","correct":true},{"t":"무늬를 설명하는 방법은 한 가지뿐이라서","mis":"M4-2-u6-X20"}],"mis":"M4-2-u6-X20","explanation":["시계 방향으로 180°와 시계 반대 방향으로 180°는 같은 결과예요.","그래서 두 설명 모두 같은 무늬를 만들어요.","같은 무늬도 여러 방법으로 설명할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#9','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',2,'mc','auto','『수학』 149쪽 2 예 — 왼쪽과 오른쪽이 똑같은 삼각형 모양을 오른쪽으로 뒤집기를 반복하여 첫 줄을 만들었어요. 첫 줄은 어떻게 되나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11','M4-2-u6-X18']::text[],false,'{"seq":9,"concept":"M4-2-u6-C10","difficulty":2,"kind":"mc","stem":"『수학』 149쪽 2 예 — 왼쪽과 오른쪽이 똑같은 삼각형 모양을 오른쪽으로 뒤집기를 반복하여 첫 줄을 만들었어요. 첫 줄은 어떻게 되나요?","options":[{"t":"같은 삼각형 모양이 그대로 되풀이돼요","correct":true},{"t":"삼각형이 위아래로 번갈아 나와요","mis":"M4-2-u6-X10"},{"t":"삼각형이 오른쪽으로 기울어져요","mis":"M4-2-u6-X11"},{"t":"삼각형이 90°씩 돌아가며 나와요","mis":"M4-2-u6-X18"}],"explanation":["오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어요.","이 삼각형은 왼쪽과 오른쪽이 똑같아서 뒤집어도 같은 모양이에요.","그래서 같은 모양이 그대로 되풀이돼요."],"asset":{"type":"geo","items":[{"w":60,"h":60,"grid":60,"poly":[[[30.0,7.2],[52.8,52.8],[7.2,52.8]]],"cap":"삼각형 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_basic#10','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_basic','lesson_basic','M4-2-u6-C10',3,'mc','auto','『수학익힘』 86쪽 — 180° 돌리기를 반복한 첫째 줄을 아래쪽으로 밀기 하여 만든 무늬예요. 넷째 줄 첫째 칸의 빈칸(?)에 알맞은 모양은 어느 것인가요?',ARRAY['M4-2-u6-X19']::text[],false,'{"seq":10,"concept":"M4-2-u6-C10","difficulty":3,"kind":"mc","stem":"『수학익힘』 86쪽 — 180° 돌리기를 반복한 첫째 줄을 아래쪽으로 밀기 하여 만든 무늬예요. 넷째 줄 첫째 칸의 빈칸(?)에 알맞은 모양은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉱","mis":"M4-2-u6-X19"},{"t":"㉯","mis":"M4-2-u6-X19"},{"t":"㉰","mis":"M4-2-u6-X19"}],"explanation":["첫째 줄을 아래쪽으로 밀었으니 넷째 줄은 첫째 줄과 같아요.","첫째 줄 첫째 칸은 처음 모양 그대로예요.","㉮예요"],"asset":{"type":"geo","items":[{"w":240,"h":150,"grid":30,"poly":[[[16.5,0],[30,0],[30,30]],[[43.5,30.0],[30.0,30.0],[30.0,0.0]],[[76.5,0.0],[90.0,0.0],[90.0,30.0]],[[103.5,30.0],[90.0,30.0],[90.0,0.0]],[[136.5,0.0],[150.0,0.0],[150.0,30.0]],[[163.5,30.0],[150.0,30.0],[150.0,0.0]],[[196.5,0.0],[210.0,0.0],[210.0,30.0]],[[223.5,30.0],[210.0,30.0],[210.0,0.0]],[[16.5,30],[30,30],[30,60]],[[43.5,60.0],[30.0,60.0],[30.0,30.0]],[[76.5,30.0],[90.0,30.0],[90.0,60.0]],[[103.5,60.0],[90.0,60.0],[90.0,30.0]],[[136.5,30.0],[150.0,30.0],[150.0,60.0]],[[163.5,60.0],[150.0,60.0],[150.0,30.0]],[[196.5,30.0],[210.0,30.0],[210.0,60.0]],[[223.5,60.0],[210.0,60.0],[210.0,30.0]],[[16.5,60],[30,60],[30,90]],[[43.5,90.0],[30.0,90.0],[30.0,60.0]],[[76.5,60.0],[90.0,60.0],[90.0,90.0]],[[103.5,90.0],[90.0,90.0],[90.0,60.0]],[[136.5,60.0],[150.0,60.0],[150.0,90.0]],[[163.5,90.0],[150.0,90.0],[150.0,60.0]],[[196.5,60.0],[210.0,60.0],[210.0,90.0]],[[223.5,90.0],[210.0,90.0],[210.0,60.0]],[[43.5,120.0],[30.0,120.0],[30.0,90.0]],[[76.5,90.0],[90.0,90.0],[90.0,120.0]],[[103.5,120.0],[90.0,120.0],[90.0,90.0]],[[136.5,90.0],[150.0,90.0],[150.0,120.0]],[[163.5,120.0],[150.0,120.0],[150.0,90.0]],[[196.