INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#1','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C9',2,'mc','auto','『수학』 148쪽 1 — 무늬를 만든 방법을 설명할 때 빠짐없이 말해야 하는 것은 무엇인가요?',ARRAY['M4-2-u6-X19','M4-2-u6-X21']::text[],false,'{"seq":1,"concept":"M4-2-u6-C9","difficulty":2,"kind":"mc","stem":"『수학』 148쪽 1 — 무늬를 만든 방법을 설명할 때 빠짐없이 말해야 하는 것은 무엇인가요?","options":[{"t":"첫째 줄을 만든 방법과 그 줄로 무늬를 만든 방법","correct":true},{"t":"첫째 줄을 만든 방법만","mis":"M4-2-u6-X19"},{"t":"무늬에 쓴 색깔","mis":"M4-2-u6-X21"},{"t":"모양이 모두 몇 개인지","mis":"M4-2-u6-X21"}],"explanation":["무늬는 한 모양으로 첫째 줄을 만들고, 그 줄을 움직여 늘려 가요.","두 가지를 모두 말해야 친구가 똑같이 만들 수 있어요.","예: 오른쪽으로 뒤집기를 반복해 첫째 줄, 아래쪽으로 뒤집기 하여 무늬."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#2','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C9',2,'mc','auto','『수학익힘』 86쪽 — 첫째 줄의 첫째 칸과 둘째 칸, 두 칸을 한 묶음으로 보면 첫째 줄을 어떻게 설명할 수 있나요?',ARRAY['M4-2-u6-X18','M4-2-u6-X10','M4-2-u6-X19']::text[],false,'{"seq":2,"concept":"M4-2-u6-C9","difficulty":2,"kind":"mc","stem":"『수학익힘』 86쪽 — 첫째 줄의 첫째 칸과 둘째 칸, 두 칸을 한 묶음으로 보면 첫째 줄을 어떻게 설명할 수 있나요?","options":[{"t":"두 칸 묶음을 오른쪽으로 밀기를 반복했어요","correct":true},{"t":"두 칸 묶음을 오른쪽으로 뒤집기를 반복했어요","mis":"M4-2-u6-X18"},{"t":"두 칸 묶음을 아래쪽으로 뒤집기를 반복했어요","mis":"M4-2-u6-X10"},{"t":"첫째 칸만 오른쪽으로 밀기를 반복했어요","mis":"M4-2-u6-X19"}],"explanation":["첫째 줄은 「처음 모양, 180° 돌린 모양」이 짝지어 되풀이돼요.","그 두 칸 묶음이 그대로 오른쪽으로 옮겨 가요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"asset":{"type":"geo","items":[{"w":240,"h":30,"grid":30,"poly":[[[16.5,0],[30,0],[30,30]],[[43.5,30.0],[30.0,30.0],[30.0,0.0]],[[76.5,0.0],[90.0,0.0],[90.0,30.0]],[[103.5,30.0],[90.0,30.0],[90.0,0.0]],[[136.5,0.0],[150.0,0.0],[150.0,30.0]],[[163.5,30.0],[150.0,30.0],[150.0,0.0]],[[196.5,0.0],[210.0,0.0],[210.0,30.0]],[[223.5,30.0],[210.0,30.0],[210.0,0.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
