INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#4','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C10',3,'mc','auto','『수학』 149쪽 2 — 무늬를 만들 모양 세 가지(삼각형 모양 · 평행사변형 모양 · 반원 모양) 가운데 시계 방향으로 180°만큼 돌려도 처음 모양과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X16']::text[],false,'{"seq":4,"concept":"M4-2-u6-C10","difficulty":3,"kind":"mc","stem":"『수학』 149쪽 2 — 무늬를 만들 모양 세 가지(삼각형 모양 · 평행사변형 모양 · 반원 모양) 가운데 시계 방향으로 180°만큼 돌려도 처음 모양과 같은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X16"},{"t":"㉰","mis":"M4-2-u6-X16"},{"t":"세 모양 모두","mis":"M4-2-u6-X16"}],"explanation":["180°만큼 돌리면 위아래와 좌우가 모두 바뀌어요.","㉯ 평행사변형 모양은 반 바퀴 돌려도 처음과 겹쳐요.","㉮ 삼각형과 ㉰ 반원은 거꾸로 뒤집힌 모양이 돼요."],"asset":{"type":"geo","items":[{"w":60,"h":60,"grid":60,"poly":[[[30.0,7.2],[52.8,52.8],[7.2,52.8]]],"cap":"㉮"},{"w":60,"h":60,"grid":60,"poly":[[[15.0,60],[30.0,0],[45.0,0],[30.0,60]]],"cap":"㉯"},{"w":60,"h":60,"grid":60,"poly":[[[7.2,60.0],[8.94,51.27],[13.88,43.88],[21.27,38.94],[30.0,37.2],[38.73,38.94],[46.12,43.88],[51.06,51.27],[52.8,60.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#5','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C9',3,'mc','auto','『수학』 148쪽 1 — 점과 띠가 그려진 모양 하나로 뒤집기를 이용하여 무늬를 만들었어요. 오른쪽 뒤집기로 첫째 줄을 만들고 아래쪽으로 뒤집기를 반복하여 줄을 늘렸어요. 셋째 줄은 어떤 줄과 같나요?',ARRAY['M4-2-u6-X13','M4-2-u6-X10']::text[],false,'{"seq":5,"concept":"M4-2-u6-C9","difficulty":3,"kind":"mc","stem":"『수학』 148쪽 1 — 점과 띠가 그려진 모양 하나로 뒤집기를 이용하여 무늬를 만들었어요. 오른쪽 뒤집기로 첫째 줄을 만들고 아래쪽으로 뒤집기를 반복하여 줄을 늘렸어요. 셋째 줄은 어떤 줄과 같나요?","options":[{"t":"첫째 줄","correct":true},{"t":"둘째 줄","mis":"M4-2-u6-X13"},{"t":"어느 줄과도 같지 않아요","mis":"M4-2-u6-X13"},{"t":"첫째 줄을 오른쪽으로 뒤집은 줄","mis":"M4-2-u6-X10"}],"explanation":["둘째 줄은 첫째 줄을 아래쪽으로 한 번 뒤집은 줄이에요.","셋째 줄은 첫째 줄을 아래쪽으로 두 번 뒤집은 줄이에요.","두 번 뒤집으면 처음과 같아 셋째 줄은 첫째 줄과 같아요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":30,"poly":[[[10.25,8.46],[8.46,10.25],[5.94,10.25],[4.15,8.46],[4.15,5.94],[5.94,4.15],[8.46,4.15],[10.25,5.94]],[[11.4,30.0],[11.76,26.37],[12.82,22.88],[14.53,19.67],[16.85,16.85],[19.67,14.53],[22.88,12.82],[26.37,11.76],[30.0,11.4],[30.0,18.0],[27.66,18.23],[25.41,18.91],[23.33,20.02],[21.51,21.51],[20.02,23.33],[18.91,25.41],[18.23,27.66],[18.0,30.0]],[[49.75,8.46],[51.54,10.25],[54.06,10.25],[55.85,8.46],[55.85,5.94],[54.06,4.15],[51.54,4.15],[49.75,5.94]],[[48.6,30.0],[48.24,26.37],[47.18,22.88],[45.47,19.67],[43.15,16.85],[40.33,14.53],[37.12,12.82],[33.63,11.76],[30.0,11.4],[30.0,18.0],[32.34,18.23],[34.59,18.91],[36.67,20.02],[38.49,21.51],[39.98,23.33],[41.09,25.41],[41.77,27.66],[42.0,30.0]],[[70.25,8.46],[68.46,10.25],[65.94,10.25],[64.15,8.46],[64.15,5.94],[65.94,4.15],[68.46,4.15],[70.25,5.94]],[[71.4,30.0],[71.76,26.37],[72.82,22.88],[74.53,19.67],[76.85,16.85],[79.67,14.53],[82.88,12.82],[86.37,11.76],[90.0,11.4],[90.0,18.0],[87.66,18.23],[85.41,18.91],[83.33,2