INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#7','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C10',4,'essay','teacher','『수학』 149쪽 2 — 삼각형 모양 · 평행사변형 모양 · 반원 모양 가운데 한 가지를 골라, 밀기·뒤집기·돌리기를 이용하여 나만의 무늬를 만드는 방법을 「보기」처럼 써 보세요. 그 방법대로 만들면 첫 줄이 어떻게 될지도 써 보세요.','{}'::text[],false,'{"seq":7,"concept":"M4-2-u6-C10","difficulty":4,"kind":"essay","stem":"『수학』 149쪽 2 — 삼각형 모양 · 평행사변형 모양 · 반원 모양 가운데 한 가지를 골라, 밀기·뒤집기·돌리기를 이용하여 나만의 무늬를 만드는 방법을 「보기」처럼 써 보세요. 그 방법대로 만들면 첫 줄이 어떻게 될지도 써 보세요.","answer_guide":{"answer":"예: 반원 모양을 오른쪽으로 뒤집기를 반복하여 첫 줄의 모양을 만들고, 이 모양을 아래쪽으로 뒤집기 하여 무늬를 만들어요. 반원 모양은 왼쪽과 오른쪽이 같아서 첫 줄에는 같은 반원이 되풀이되고, 둘째 줄은 반원이 위쪽에 붙은 모양이 돼요.","scoring_points":["모양 하나를 고름","첫 줄을 만드는 이동 방법(방향·각도 포함)","무늬로 늘리는 이동 방법","결과를 미리 추측함"]},"explanation":["먼저 모양과 이동 방법을 정해요.","한 번에 한 가지 이동 방법만 써요.","만들기 전에 어떤 무늬가 될지 추측하고 만들어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
