INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#9','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C10',4,'mc','auto','지도서 453쪽 — 148쪽 무늬의 조각(왼쪽 위에 점, 오른쪽 아래 모서리를 두른 띠)은 오른쪽으로 뒤집은 모양과 시계 방향으로 90°만큼 돌린 모양이 같아요. 이 조각을 시계 방향으로 90°만큼 돌린 모양을 오른쪽으로 뒤집으면 어떻게 되나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X10','M4-2-u6-X20']::text[],false,'{"seq":9,"concept":"M4-2-u6-C10","difficulty":4,"kind":"mc","stem":"지도서 453쪽 — 148쪽 무늬의 조각(왼쪽 위에 점, 오른쪽 아래 모서리를 두른 띠)은 오른쪽으로 뒤집은 모양과 시계 방향으로 90°만큼 돌린 모양이 같아요. 이 조각을 시계 방향으로 90°만큼 돌린 모양을 오른쪽으로 뒤집으면 어떻게 되나요?","options":[{"t":"처음 모양과 같아요","correct":true},{"t":"시계 방향으로 180°만큼 돌린 모양이 돼요","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 뒤집은 모양이 돼요","mis":"M4-2-u6-X10"},{"t":"알 수 없어요","mis":"M4-2-u6-X20"}],"explanation":["이 조각은 오른쪽 뒤집기 = 시계 방향 90° 돌리기예요.","90°만큼 돌린 모양을 오른쪽으로 뒤집는 것은 오른쪽으로 두 번 뒤집는 것과 같아요.","같은 쪽으로 두 번 뒤집으면 처음 모양이에요."],"asset":{"type":"geo","items":[{"w":60,"h":60,"grid":60,"poly":[[[20.5,16.93],[16.93,20.5],[11.87,20.5],[8.3,16.93],[8.3,11.87],[11.87,8.3],[16.93,8.3],[20.5,11.87]],[[22.8,60.0],[23.51,52.74],[25.63,45.76],[29.07,39.33],[33.7,33.7],[39.33,29.07],[45.76,25.63],[52.74,23.51],[60.0,22.8],[60.0,36.0],[55.32,36.46],[50.82,37.83],[46.67,40.04],[43.03,43.03],[40.04,46.67],[37.83,50.82],[36.46,55.32],[36.0,60.0]]],"cap":"조각"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_L06_challenge#10','math',4,2,'u6','L06','tb_g4_2_math_u6_L06_challenge','lesson_challenge','M4-2-u6-C9',3,'mc','auto','『수학』 148쪽 1 — 무늬를 만든 방법을 다르게 설명한 것으로 알맞은 것은 어느 것인가요? (첫째 줄은 오른쪽 뒤집기 반복, 무늬는 아래쪽 뒤집기)',ARRAY['M4-2-u6-X10','M4-2-u6-X19','M4-2-u6-X20']::text[],false,'{"seq":10,"concept":"M4-2-u6-C9","difficulty":3,"kind":"mc","stem":"『수학』 148쪽 1 — 무늬를 만든 방법을 다르게 설명한 것으로 알맞은 것은 어느 것인가요? (첫째 줄은 오른쪽 뒤집기 반복, 무늬는 아래쪽 뒤집기)","options":[{"t":"모양을 왼쪽으로 뒤집기를 반복하여 첫째 줄을 만들고, 이 줄을 위쪽으로 뒤집기 하여 무늬를 만들었어요","correct":true},{"t":"모양을 아래쪽으로 뒤집기를 반복하여 첫째 줄을 만들었어요","mis":"M4-2-u6-X10"},{"t":"모양을 오른쪽으로 밀기를 반복하여 첫째 줄을 만들었어요","mis":"M4-2-u6-X19"},{"t":"무늬를 만든 방법은 한 가지로만 설명할 수 있어요","mis":"M4-2-u6-X20"}],"explanation":["왼쪽 뒤집기는 오른쪽 뒤집기와 결과가 같아요.","위쪽 뒤집기는 아래쪽 뒤집기와 결과가 같아요.","같은 무늬도 여러 방법으로 설명할 수 있어요."],"asset":{"type":"geo","items":[{"w":240,"h":120,"grid":30,"poly":[[[10.25,8.46],[8.46,10.25],[5.94,10.25],[4.15,8.46],[4.15,5.94],[5.94,4.15],[8.46,4.15],[10.25,5.94]],[[11.4,30.0],[11.76,26.37],[12.82,22.88],[14.53,19.67],[16.85,16.85],[19.67,14.53],[22.88,12.82],[26.37,11.76],[30.0,11.4],[30.0,18.0],[27.66,18.23],[25.41,18.91],[23.33,20.02],[21.51,21.51],[20.02,23.33],[18.91,25.41],[18.23,27.66],[18.0,30.0]],[[49.75,8.46],[51.54,10.25],[54.06,10.25],[55.85,8.46],[55.85,5.94],[54.06,4.15],[51.54,4.15],[49.75,5.94]],[[48.6,30.0],[48.24,26.37],[47.18,22.88],[45.47,19.67],[43.15,16.85],[40.33,14.53],[37.12,12.82],[33.63,11.76],[30.0,11.4],[30.0,18.0],[32.34,18.23],[34.59,18.91],[36.67,20.02],[38.49,21.51],[39.98,23.33],[41.09,25.41],[41.77,27.66],[42.0,30.0]],[[70.25,8.46],[68.46,10.25],[65.94,10.25],[64.15,8.46],[64.15,5.94],[65.94,4.15],[68.46,4.15],[70.25,5.94]],[[71.4,30.0],[71.76,26.37],[72.82,22.88],[74.53,19.67],[76.85,16.85],[79.67,14.53],[82.88,12.82],[86.37,11.76],[90.0,11.4],[