INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#2','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C3',1,'mc','auto','『수학』 151쪽 2 — 점선 도형을 오른쪽으로 3칸 민 도형은 어느 것인가요?',ARRAY['M4-2-u6-X03','M4-2-u6-X02','M4-2-u6-X11']::text[],false,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"『수학』 151쪽 2 — 점선 도형을 오른쪽으로 3칸 민 도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M4-2-u6-X03"},{"t":"㉯","mis":"M4-2-u6-X02"},{"t":"㉮","mis":"M4-2-u6-X11"}],"explanation":["밀면 모양과 방향은 그대로예요 — 뒤집힌 모양은 아니에요.","같은 꼭짓점끼리 오른쪽으로 3칸 떨어져 있어야 해요.","㉰예요"],"asset":{"type":"geo","items":[{"w":198,"h":90,"grid":18,"poly":[[[162.0,72.0],[144.0,18.0],[126.0,18.0],[144.0,72.0]]],"dash":[[[72.0,72.0],[90.0,18.0]],[[90.0,18.0],[108.0,18.0]],[[108.0,18.0],[90.0,72.0]],[[90.0,72.0],[72.0,72.0]]],"cap":"㉮"},{"w":198,"h":90,"grid":18,"poly":[[[18.0,72.0],[36.0,18.0],[54.0,18.0],[36.0,72.0]]],"dash":[[[72.0,72.0],[90.0,18.0]],[[90.0,18.0],[108.0,18.0]],[[108.0,18.0],[90.0,72.0]],[[90.0,72.0],[72.0,72.0]]],"cap":"㉯"},{"w":198,"h":90,"grid":18,"poly":[[[126.0,72.0],[144.0,18.0],[162.0,18.0],[144.0,72.0]]],"dash":[[[72.0,72.0],[90.0,18.0]],[[90.0,18.0],[108.0,18.0]],[[108.0,18.0],[90.0,72.0]],[[90.0,72.0],[72.0,72.0]]],"cap":"㉰"},{"w":198,"h":90,"grid":18,"poly":[[[144.0,72.0],[162.0,18.0],[180.0,18.0],[162.0,72.0]]],"dash":[[[72.0,72.0],[90.0,18.0]],[[90.0,18.0],[108.0,18.0]],[[108.0,18.0],[90.0,72.0]],[[90.0,72.0],[72.0,72.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#3','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C6',1,'mc','auto','『수학』 151쪽 3 — 도장을 찍었을 때 「오이」가 찍히는 도장은 어느 것인가요?',ARRAY['M4-2-u6-X14','M4-2-u6-X10']::text[],false,'{"seq":3,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학』 151쪽 3 — 도장을 찍었을 때 「오이」가 찍히는 도장은 어느 것인가요?","options":[{"t":"「오이」를 왼쪽(오른쪽)으로 뒤집어 새긴 도장","correct":true},{"t":"「오이」를 그대로 새긴 도장","mis":"M4-2-u6-X14"},{"t":"「오이」를 위쪽(아래쪽)으로 뒤집어 새긴 도장","mis":"M4-2-u6-X10"},{"t":"「오」와 「이」를 하나씩 뒤집고 순서는 그대로 새긴 도장","mis":"M4-2-u6-X14"}],"explanation":["도장은 새긴 모양이 왼쪽이나 오른쪽으로 뒤집혀 찍혀요.","그래서 「오이」를 통째로 왼쪽이나 오른쪽으로 뒤집어 새겨요.","글자 하나하나만 뒤집으면 순서가 바뀌지 않아 「이오」처럼 찍혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#4','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C8',1,'mc','auto','『수학』 151쪽 4 — 돌리기 전과 돌린 후의 도형을 보고 알맞은 것을 고르세요.',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X17']::text[],false,'{"seq":4,"concept":"M4-2-u6-C8","difficulty":1,"kind":"mc","stem":"『수학』 151쪽 4 — 돌리기 전과 돌린 후의 도형을 보고 알맞은 것을 고르세요.","options":[{"t":"시계 방향으로 270°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 270°만큼 돌렸어요","mis":"M4-2-u6-X17"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 270°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[36.0,54.0],[36.0,72.0],[18.0,72.0],[18.0,36.0],[36.0,36.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[18.0,18.0],[54.0,18.0],[54.0,54.0],[72.0,54.0],[72.0,72.0],[36.0,72.0],[36.0,54.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#5','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C5',1,'mc','auto','『수학』 152쪽 5 — 처음 도형을 뒤집었을 때 나올 수 있는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u6-X12','M4-2-u6-X18','M4-2-u6-X11']::text[],false,'{"seq":5,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"『수학』 152쪽 5 — 처음 도형을 뒤집었을 때 나올 수 있는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉮","mis":"M4-2-u6-X12"},{"t":"㉯, ㉱","mis":"M4-2-u6-X18"},{"t":"㉮, ㉯, ㉰, ㉱","mis":"M4-2-u6-X11"}],"explanation":["위쪽이나 아래쪽으로 뒤집으면 위아래가 바뀐 ㉮가 나와요.","왼쪽이나 오른쪽으로 뒤집으면 좌우가 바뀐 ㉰가 나와요.","㉯와 ㉱는 돌린 도형이에요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[18.0,90.0],[54.0,18.0],[90.0,18.0],[90.0,90.0]]],"cap":"처음 도형"},{"w":108,"h":108,"grid":18,"poly":[[[18.0,18.0],[54.0,90.0],[90.0,90.0],[90.0,18.0]]],"cap":"㉮"},{"w":108,"h":108,"grid":18,"poly":[[[90.0,90.0],[18.0,54.0],[18.0,18.0],[90.0,18.0]]],"cap":"㉯"},{"w":108,"h":108,"grid":18,"poly":[[[90.0,90.0],[54.0,18.0],[18.0,18.0],[18.0,90.0]]],"cap":"㉰"},{"w":108,"h":108,"grid":18,"poly":[[[18.0,18.0],[90.0,54.0],[90.0,90.0],[18.0,90.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#6','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C2',1,'mc','auto','『수학』 152쪽 6 — 점 ㄴ을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X02']::text[],false,'{"seq":6,"concept":"M4-2-u6-C2","difficulty":1,"kind":"mc","stem":"『수학』 152쪽 6 — 점 ㄴ을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"왼쪽으로 4칸 이동하고 아래쪽으로 2칸 이동했어요","correct":true},{"t":"왼쪽으로 2칸 이동하고 아래쪽으로 4칸 이동했어요","mis":"M4-2-u6-X06"},{"t":"오른쪽으로 4칸 이동하고 아래쪽으로 2칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"왼쪽으로 4칸 이동하고 위쪽으로 2칸 이동했어요","mis":"M4-2-u6-X02"}],"explanation":["가로로 왼쪽으로 4칸, 세로로 아래쪽으로 2칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":108,"h":72,"grid":18,"pts":{"전":[90,18,"e"],"후":[18,54,"w"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#7','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C8',1,'error','auto','『수학』 152쪽 7 — 집 모양 도형(위에 정사각형, 아래에 사다리꼴)이 이동 후 위아래가 바뀌었어요. 하윤이는 「도형을 시계 방향으로 90°만큼 돌렸어.」라고 했어요. 하윤이의 설명을 바르게 고친 것은 어느 것인가요?',ARRAY['M4-2-u6-X16','M4-2-u6-X15','M4-2-u6-X10']::text[],false,'{"seq":7,"concept":"M4-2-u6-C8","difficulty":1,"kind":"error","stem":"『수학』 152쪽 7 — 집 모양 도형(위에 정사각형, 아래에 사다리꼴)이 이동 후 위아래가 바뀌었어요. 하윤이는 「도형을 시계 방향으로 90°만큼 돌렸어.」라고 했어요. 하윤이의 설명을 바르게 고친 것은 어느 것인가요?","options":[{"t":"도형을 시계 방향으로 180°만큼 돌렸어요","correct":true,"mis_target":"M4-2-u6-X16"},{"t":"도형을 시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"도형을 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X10"},{"t":"하윤이의 설명이 맞아요","mis":"M4-2-u6-X16"}],"explanation":["시계 방향으로 90°만큼 돌리면 위쪽의 정사각형이 오른쪽으로 가요.","이동 후는 정사각형이 아래쪽으로 갔어요.","시계 방향(또는 시계 반대 방향)으로 180°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[90.0,90.0],[18.0,90.0],[36.0,54.0]]],"cap":"이동 전"},{"w":108,"h":108,"grid":18,"poly":[[[72.0,90.0],[36.0,90.0],[36.0,54.0],[18.0,18.0],[90.0,18.0],[72.0,54.0]]],"cap":"이동 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#8','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C1',1,'sa','auto','『수학』 150쪽 정리 — 점 ㄱ을 오른쪽으로 몇 칸 이동했나요? 숫자로 쓰세요. (「전」은 이동 전, 「후」는 이동 후의 자리예요.)','{}'::text[],false,'{"seq":8,"concept":"M4-2-u6-C1","difficulty":1,"kind":"sa","stem":"『수학』 150쪽 정리 — 점 ㄱ을 오른쪽으로 몇 칸 이동했나요? 숫자로 쓰세요. (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","answer":["6"],"explanation":["이동 전 자리는 세지 않아요.","오른쪽으로 모눈 선을 넘은 수를 세요.","6칸 이동했어요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"전":[18,18,"n"],"후":[126,18,"s"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#9','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C3',2,'mc','auto','『수학』 137쪽 1 — 배 모양을 위쪽, 아래쪽, 왼쪽, 오른쪽으로 밀었어요. 배 모양을 밀면 모양과 위치는 어떻게 되나요?',ARRAY['M4-2-u6-X08']::text[],false,'{"seq":9,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 137쪽 1 — 배 모양을 위쪽, 아래쪽, 왼쪽, 오른쪽으로 밀었어요. 배 모양을 밀면 모양과 위치는 어떻게 되나요?","options":[{"t":"모양은 변하지 않지만 위치는 변해요","correct":true},{"t":"모양과 위치가 모두 변해요","mis":"M4-2-u6-X08"},{"t":"모양은 변하고 위치는 그대로예요","mis":"M4-2-u6-X08"},{"t":"배가 민 쪽을 바라보도록 방향이 바뀌어요","mis":"M4-2-u6-X08"}],"explanation":["배 모양을 어느 쪽으로 밀어도 배 모양 자체는 그대로였어요.","민 방향에 따라 놓인 곳이 바뀌었어요.","밀면 모양은 그대로, 위치만 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#10','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C6',2,'mc','auto','『수학』 153쪽 만화 — 사진을 오른쪽으로 뒤집으면 어떻게 되나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],false,'{"seq":10,"concept":"M4-2-u6-C6","difficulty":2,"kind":"mc","stem":"『수학』 153쪽 만화 — 사진을 오른쪽으로 뒤집으면 어떻게 되나요?","options":[{"t":"모양은 변하지 않지만 왼쪽과 오른쪽이 서로 바뀌어요","correct":true},{"t":"위쪽과 아래쪽이 서로 바뀌어요","mis":"M4-2-u6-X10"},{"t":"사진의 모양이 바뀌어요","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["휴대 전화로 찍은 사진에서는 제일 왼쪽에 있던 사람이 제일 오른쪽에 있었어요.","사진을 오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어요.","모양은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#11','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C7',2,'mc','auto','『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 반대 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],false,'{"seq":11,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 반대 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?","options":[{"t":"왼쪽","correct":true},{"t":"오른쪽","mis":"M4-2-u6-X15"},{"t":"아래쪽","mis":"M4-2-u6-X16"},{"t":"위쪽 그대로","mis":"M4-2-u6-X16"}],"explanation":["시계 반대 방향은 시곗바늘이 도는 쪽의 반대쪽이에요.","위쪽에 있던 지붕이 90°만큼 돌아간 자리를 따라가요.","파란색 지붕은 왼쪽으로 가요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[90.0,45.0],[81.0,45.0],[81.0,90.0],[27.0,90.0],[27.0,45.0],[18.0,45.0]]],"cap":"집 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#12','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C8',2,'mc','auto','『수학』 147쪽 2 — 도형을 시계 반대 방향으로 90°만큼 돌린 것과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X17','M4-2-u6-X16','M4-2-u6-X15']::text[],false,'{"seq":12,"concept":"M4-2-u6-C8","difficulty":2,"kind":"mc","stem":"『수학』 147쪽 2 — 도형을 시계 반대 방향으로 90°만큼 돌린 것과 같은 것은 어느 것인가요?","options":[{"t":"시계 방향으로 270°만큼 돌린 것","correct":true},{"t":"시계 방향으로 90°만큼 돌린 것","mis":"M4-2-u6-X17"},{"t":"시계 방향으로 180°만큼 돌린 것","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 270°만큼 돌린 것","mis":"M4-2-u6-X15"}],"explanation":["한 바퀴는 360°예요.","시계 방향과 시계 반대 방향은 360°에서 빼어 견주어요.","360° − 90° = 270°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#13','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C3',2,'mc','auto','『수학』 139쪽 4 — 노란색 자동차를 오른쪽 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X25','M4-2-u6-X02']::text[],false,'{"seq":13,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 139쪽 4 — 노란색 자동차를 오른쪽 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"초록색 자동차를 왼쪽으로 1칸 밀고, 파란색 자동차를 아래쪽으로 3칸 밀어요","correct":true},{"t":"초록색 자동차를 왼쪽으로 1칸 밀고, 파란색 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X25"},{"t":"초록색 자동차를 왼쪽으로 2칸 밀고, 파란색 자동차를 아래쪽으로 3칸 밀어요","mis":"M4-2-u6-X25"},{"t":"파란색 자동차를 위쪽으로 1칸 밀어요","mis":"M4-2-u6-X02"}],"explanation":["파란색 자동차가 출구를 막고 있는데, 위쪽은 벽이라 아래쪽으로만 비킬 수 있어요.","아래를 초록색 자동차가 막아서 먼저 초록색 자동차를 왼쪽으로 1칸 밀어요(2칸은 보라색 자동차에 막혀요).","파란색 자동차를 아래쪽으로 3칸 밀어야 출구 줄이 다 비어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#14','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C5',2,'mc','auto','『수학』 142쪽 2 — 처음 도형을 아래쪽으로 뒤집은 도형은 어느 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X18','M4-2-u6-X11']::text[],false,'{"seq":14,"concept":"M4-2-u6-C5","difficulty":2,"kind":"mc","stem":"『수학』 142쪽 2 — 처음 도형을 아래쪽으로 뒤집은 도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M4-2-u6-X10"},{"t":"㉮","mis":"M4-2-u6-X18"},{"t":"㉯","mis":"M4-2-u6-X11"}],"explanation":["아래쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀌어요.","모양과 크기는 그대로이고 방향만 바뀌어요.","㉰예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[72.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,54.0],[18.0,72.0],[18.0,18.0],[72.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[72.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[72.0,72.0],[72.0,18.0],[18.0,18.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,36.0],[18.0,18.0],[18.0,72.0],[72.0,72.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
