INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#17','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C2',3,'mc','auto','『수학익힘』 79쪽 퐁당 — 오래된 상자에서 보물 지도를 발견했어요. 현재 위치(점 ㄱ)에서 오른쪽으로 3칸 이동하고 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸 이동하면 보물이 있어요. 보물이 있는 곳은 어느 점인가요?',ARRAY['M4-2-u6-X07','M4-2-u6-X01','M4-2-u6-X02']::text[],false,'{"seq":17,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"『수학익힘』 79쪽 퐁당 — 오래된 상자에서 보물 지도를 발견했어요. 현재 위치(점 ㄱ)에서 오른쪽으로 3칸 이동하고 위쪽으로 3칸 이동한 다음, 왼쪽으로 1칸 이동하면 보물이 있어요. 보물이 있는 곳은 어느 점인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄷ","mis":"M4-2-u6-X07"},{"t":"점 ㄹ","mis":"M4-2-u6-X01"},{"t":"점 ㄴ","mis":"M4-2-u6-X02"}],"explanation":["점 ㄱ에서 먼저 오른쪽으로 3칸 가요.","그 자리에서 위쪽으로 3칸 가요 다음 왼쪽으로 1칸 가요.","도착한 곳은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":180,"h":90,"grid":18,"pts":{"ㄱ":[90,72,"sw"],"ㄴ":[18,18,"nw"],"ㄷ":[162,18,"e"],"ㄹ":[144,18,"n"],"ㅁ":[126,18,"w"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#18','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C8',3,'ox','auto','지도서 424쪽 오류 1 — 도형을 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것은 언제나 서로 같아요.',ARRAY['M4-2-u6-X18']::text[],false,'{"seq":18,"concept":"M4-2-u6-C8","difficulty":3,"kind":"ox","stem":"지도서 424쪽 오류 1 — 도형을 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것은 언제나 서로 같아요.","answer":"X","reason_options":[{"t":"뒤집기와 돌리기는 다른 방법이라 도형에 따라 결과가 달라서","correct":true},{"t":"아래쪽 뒤집기와 180° 돌리기는 둘 다 위아래를 바꾸어서","mis":"M4-2-u6-X18"}],"mis":"M4-2-u6-X18","explanation":["T처럼 왼쪽과 오른쪽이 똑같은 도형은 두 결과가 같아요.","하지만 깃발 모양처럼 왼쪽과 오른쪽이 다른 도형은 결과가 달라요.","그래서 「언제나」 같지는 않아요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"깃발 모양"},{"w":90,"h":108,"grid":18,"poly":[[[18.0,90.0],[72.0,72.0],[36.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"아래쪽으로 뒤집기"},{"w":90,"h":108,"grid":18,"poly":[[[72.0,90.0],[18.0,72.0],[54.0,54.0],[54.0,18.0],[72.0,18.0]]],"cap":"시계 방향으로 180°"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#19','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C8',3,'mc','auto','지도서 425쪽 오류 2 — 「곰」을 시계 방향으로 180°만큼 돌리면 어떤 글자로 보이나요?',ARRAY['M4-2-u6-X26','M4-2-u6-X16']::text[],false,'{"seq":19,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"지도서 425쪽 오류 2 — 「곰」을 시계 방향으로 180°만큼 돌리면 어떤 글자로 보이나요?","options":[{"t":"문","correct":true},{"t":"곰","mis":"M4-2-u6-X26"},{"t":"글자처럼 보이지 않아요","mis":"M4-2-u6-X26"},{"t":"몸","mis":"M4-2-u6-X16"}],"explanation":["반 바퀴 돌리면 위아래와 좌우가 모두 바뀌어요.","ㄱ은 ㄴ처럼, ㅗ는 ㅜ처럼 보이고 받침 ㅁ은 위로 가요.","「문」으로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#20','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C7',3,'mc','auto','『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 홈에 서서 1루를 바라보는 선수가 홈 → 1루 → 2루 → 3루 → 홈으로 돌아오는 과정을 차례대로 나타낸 것은 어느 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X01','M4-2-u6-X16']::text[],false,'{"seq":20,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 홈에 서서 1루를 바라보는 선수가 홈 → 1루 → 2루 → 3루 → 홈으로 돌아오는 과정을 차례대로 나타낸 것은 어느 것인가요?","options":[{"t":"㉠ ㉡ ㉠ ㉡ ㉠ ㉡ ㉠","correct":true},{"t":"㉠ ㉢ ㉠ ㉢ ㉠ ㉢ ㉠","mis":"M4-2-u6-X15"},{"t":"㉠ ㉠ ㉠ ㉠","mis":"M4-2-u6-X01"},{"t":"㉡ ㉠ ㉡ ㉠ ㉡ ㉠ ㉡","mis":"M4-2-u6-X16"}],"explanation":["홈에서 1루까지는 앞으로 곧장 가요(㉠).","루에 닿을 때마다 시계 반대 방향으로 90°만큼 돌아(㉡) 다음 루를 바라봐요.","㉠ ㉡ ㉠ ㉡ ㉠ ㉡ ㉠이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#21','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C9',3,'mc','auto','『수학』 148쪽 1 — 점과 띠가 그려진 모양 하나로 뒤집기를 이용하여 무늬를 만들었어요. 첫째 줄은 모양을 어느 쪽으로 뒤집기를 반복하여 만들었나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X19']::text[],false,'{"seq":21,"concept":"M4-2-u6-C9","difficulty":3,"kind":"mc","stem":"『수학』 148쪽 1 — 점과 띠가 그려진 모양 하나로 뒤집기를 이용하여 무늬를 만들었어요. 첫째 줄은 모양을 어느 쪽으로 뒤집기를 반복하여 만들었나요?","options":[{"t":"오른쪽","correct":true},{"t":"아래쪽","mis":"M4-2-u6-X10"},{"t":"위쪽","mis":"M4-2-u6-X10"},{"t":"뒤집지 않고 오른쪽으로 밀었어요","mis":"M4-2-u6-X19"}],"explanation":["첫째 줄에서 이웃한 두 칸을 견주어요.","오른쪽 칸은 왼쪽 칸의 왼쪽과 오른쪽이 바뀐 모양이에요.","모양을 오른쪽으로 뒤집기를 반복했어요."],"asset":{"type":"geo","items":[{"w":240,"h":30,"grid":30,"poly":[[[10.25,8.46],[8.46,10.25],[5.94,10.25],[4.15,8.46],[4.15,5.94],[5.94,4.15],[8.46,4.15],[10.25,5.94]],[[11.4,30.0],[11.76,26.37],[12.82,22.88],[14.53,19.67],[16.85,16.85],[19.67,14.53],[22.88,12.82],[26.37,11.76],[30.0,11.4],[30.0,18.0],[27.66,18.23],[25.41,18.91],[23.33,20.02],[21.51,21.51],[20.02,23.33],[18.91,25.41],[18.23,27.66],[18.0,30.0]],[[49.75,8.46],[51.54,10.25],[54.06,10.25],[55.85,8.46],[55.85,5.94],[54.06,4.15],[51.54,4.15],[49.75,5.94]],[[48.6,30.0],[48.24,26.37],[47.18,22.88],[45.47,19.67],[43.15,16.85],[40.33,14.53],[37.12,12.82],[33.63,11.76],[30.0,11.4],[30.0,18.0],[32.34,18.23],[34.59,18.91],[36.67,20.02],[38.49,21.51],[39.98,23.33],[41.09,25.41],[41.77,27.66],[42.0,30.0]],[[70.25,8.46],[68.46,10.25],[65.94,10.25],[64.15,8.46],[64.15,5.94],[65.94,4.15],[68.46,4.15],[70.25,5.94]],[[71.4,30.0],[71.76,26.37],[72.82,22.88],[74.53,19.67],[76.85,16.85],[79.67,14.53],[82.88,12.82],[86.37,11.76],[90.0,11.4],[90.0,18.0],[87.66,18.23],[85.41,18.91],[83.33,20.02],[81.51,21.51],[80.02,23.33],[78.91,25.41],[78.23,27.66],[78.0,30.0]],[[109.75,8.46],[111.54,10.25],