INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#22','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C6',3,'ox','auto','『수학익힘』 83쪽 3 — 도형을 위쪽으로 2번 뒤집은 도형은 처음 도형과 같아요.',ARRAY['M4-2-u6-X13']::text[],false,'{"seq":22,"concept":"M4-2-u6-C6","difficulty":3,"kind":"ox","stem":"『수학익힘』 83쪽 3 — 도형을 위쪽으로 2번 뒤집은 도형은 처음 도형과 같아요.","answer":"O","reason_options":[{"t":"한 번 더 뒤집으면 바뀐 위아래가 제자리로 돌아와서","correct":true},{"t":"뒤집을수록 방향이 점점 더 바뀌어서","mis":"M4-2-u6-X13"}],"mis":"M4-2-u6-X13","explanation":["위쪽으로 한 번 뒤집으면 위아래가 바뀌어요.","두 번째로 뒤집으면 다시 처음으로 돌아와요.","그래서 처음 도형과 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[36.0,36.0],[72.0,72.0],[18.0,72.0]]],"cap":"뒤집기 전"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[36.0,36.0],[72.0,72.0],[18.0,72.0]]],"cap":"2번 뒤집은 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#23','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C4',4,'essay','teacher','『수학』 139쪽 4 — 노란색 자동차를 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 어떤 차례로, 어느 쪽으로 몇 칸씩 밀어야 하는지 쓰고, 파란색 자동차를 2칸이 아니라 3칸 밀어야 하는 까닭을 써 보세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)','{}'::text[],false,'{"seq":23,"concept":"M4-2-u6-C4","difficulty":4,"kind":"essay","stem":"『수학』 139쪽 4 — 노란색 자동차를 출구로 나가게 하려면 초록색 자동차와 파란색 자동차를 어떤 차례로, 어느 쪽으로 몇 칸씩 밀어야 하는지 쓰고, 파란색 자동차를 2칸이 아니라 3칸 밀어야 하는 까닭을 써 보세요. (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","answer_guide":{"answer":"초록색 자동차를 왼쪽으로 1칸 먼저 밀고, 파란색 자동차를 아래쪽으로 3칸 밀어요. 파란색 자동차는 위쪽이 벽이라 아래쪽으로만 밀 수 있는데, 2칸만 밀면 맨 위 칸이 아직 출구 줄에 있어 노란색 자동차가 나갈 수 없어요.","scoring_points":["초록색 자동차를 먼저 왼쪽으로 1칸","파란색 자동차를 아래쪽으로 3칸","2칸이면 아직 출구를 막는다는 까닭"]},"explanation":["파란색 자동차를 밀려면 아래를 막은 초록색 자동차를 먼저 비켜야 해요.","초록색은 왼쪽으로 1칸만 밀 수 있어요.","파란색은 3칸 밀어야 출구 줄이 다 비어요."],"asset":{"type":"geo","items":[{"w":231.0,"h":180,"poly":[[[93.0,63.0],[147.0,63.0],[147.0,87.0],[93.0,87.0]],[[63.0,3.0],[87.0,3.0],[87.0,87.0],[63.0,87.0]],[[153.0,3.0],[177.0,3.0],[177.0,87.0],[153.0,87.0]],[[3.0,93.0],[87.0,93.0],[87.0,117.0],[3.0,117.0]],[[123.0,93.0],[177.0,93.0],[177.0,117.0],[123.0,117.0]]],"lab":[[[120.0,74.0],"노랑"],[[75.0,44.0],"분홍"],[[165.0,44.0],"파랑"],[[45.0,104.0],"보라"],[[150.0,104.0],"초록"],[[205.5,74.0],"출구"]],"seg":[[[0,0],[180,0]],[[0,180],[180,180]],[[0,0],[0,180]],[[180,0],[180,60]],[[180,90],[180,180]]],"dash":[[[30,0],[30,180]],[[60,0],[60,180]],[[90,0],[90,180]],[[120,0],[120,180]],[[150,0],[150,180]],[[0,30],[180,30]],[[0,60],[180,60]],[[0,90],[180,90]],[[0,120],[180,120]],[[0,150],[180,150]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#24','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C6',4,'mc','auto','『수학』 143쪽 4 — 교실 밖에서 「4-3」으로 보이도록 창문에 쓰려고 해요. 교실 안에서는 어떻게 써야 하나요?',ARRAY['M4-2-u6-X14','M4-2-u6-X10']::text[],false,'{"seq":24,"concept":"M4-2-u6-C6","difficulty":4,"kind":"mc","stem":"『수학』 143쪽 4 — 교실 밖에서 「4-3」으로 보이도록 창문에 쓰려고 해요. 교실 안에서는 어떻게 써야 하나요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X14"},{"t":"㉰","mis":"M4-2-u6-X14"},{"t":"㉱","mis":"M4-2-u6-X10"}],"explanation":["교실 밖에서 보면 안에서 쓴 글씨가 왼쪽이나 오른쪽으로 뒤집혀 보여요.","그래서 「4-3」을 통째로 왼쪽이나 오른쪽으로 뒤집어 써요 — 순서도 바뀌어요.","맨 왼쪽에는 뒤집은 3, 맨 오른쪽에는 뒤집은 4가 와요 — ㉯예요."],"asset":{"type":"geo","items":[{"w":116.0,"h":64,"poly":[[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[29.4,34.4],[34.6,34.4],[34.6,49.6],[29.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[86.4,9.4],[101.6,9.4],[101.6,14.6],[86.4,14.6]],[[101.4,14.4],[106.6,14.4],[106.6,29.6],[101.4,29.6]],[[86.4,29.4],[101.6,29.4],[101.6,34.6],[86.4,34.6]],[[101.4,34.4],[106.6,34.4],[106.6,49.6],[101.4,49.6]],[[86.4,49.4],[101.6,49.4],[101.6,54.6],[86.4,54.6]]],"cap":"교실 밖에서 보일 모양"},{"w":116.0,"h":64,"poly":[[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[9.4,34.4],[14.6,34.4],[14.6,49.6],[9.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[86.4,9.4],[101.6,9.4],[101.6,14.6],[86.4,14.6]],[[81.4,14.4],[86.6,14.4],[86.6,29.6],[81.4,29.6]],[[86.4,29.4],[101.6,29.4],[101.6,34.6],[86.4,34.6]],[[81.4,34.4],[86.6,34.4],[86.6,49.6],[81.4,49.6]],[[86.4,49.4],[101.6,49.4],[101.6,54.6],[86.4,54.6]]],"cap":"㉮"},{"w":116.0,"h":64,"poly":[[[14.4,9.4