INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_a#25','math',4,2,'u6','','tb_g4_2_math_u6_review_a','unit_review','M4-2-u6-C9',4,'essay','teacher','『수학익힘』 86쪽 — 대각선 조각 모양으로 만든 무늬를 두 가지 방법으로 설명하고, 두 설명이 같은 무늬를 만드는 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u6-C9","difficulty":4,"kind":"essay","stem":"『수학익힘』 86쪽 — 대각선 조각 모양으로 만든 무늬를 두 가지 방법으로 설명하고, 두 설명이 같은 무늬를 만드는 까닭을 써 보세요.","answer_guide":{"answer":"방법 1: 모양을 시계 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들고, 이 줄을 아래쪽으로 밀기 하여 무늬를 만들었어요. 방법 2: 모양을 시계 반대 방향으로 180°만큼 돌리기를 반복하여 첫째 줄을 만들고, 아래쪽으로 밀기 하였어요. 180°는 어느 쪽으로 돌려도 같은 결과라서 같은 무늬가 돼요.","scoring_points":["첫째 줄 만든 방법(180° 돌리기 반복)","무늬로 늘린 방법(아래쪽 밀기)","두 설명이 같은 까닭(180°는 방향과 상관없음)"]},"explanation":["첫째 줄은 180° 돌리기를 반복했어요.","줄은 아래쪽으로 밀어 늘렸어요.","시계 방향과 시계 반대 방향 180°는 같아요."],"asset":{"type":"geo","items":[{"w":240,"h":60,"grid":30,"poly":[[[16.5,0],[30,0],[30,30]],[[43.5,30.0],[30.0,30.0],[30.0,0.0]],[[76.5,0.0],[90.0,0.0],[90.0,30.0]],[[103.5,30.0],[90.0,30.0],[90.0,0.0]],[[136.5,0.0],[150.0,0.0],[150.0,30.0]],[[163.5,30.0],[150.0,30.0],[150.0,0.0]],[[196.5,0.0],[210.0,0.0],[210.0,30.0]],[[223.5,30.0],[210.0,30.0],[210.0,0.0]],[[16.5,30],[30,30],[30,60]],[[43.5,60.0],[30.0,60.0],[30.0,30.0]],[[76.5,30.0],[90.0,30.0],[90.0,60.0]],[[103.5,60.0],[90.0,60.0],[90.0,30.0]],[[136.5,30.0],[150.0,30.0],[150.0,60.0]],[[163.5,60.0],[150.0,60.0],[150.0,30.0]],[[196.5,30.0],[210.0,30.0],[210.0,60.0]],[[223.5,60.0],[210.0,60.0],[210.0,30.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#1','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C1',1,'mc','auto','『수학익힘』 78쪽 2 — 점 ㄱ을 오른쪽으로 6칸 이동했을 때의 자리는 어느 점인가요?',ARRAY['M4-2-u6-X02','M4-2-u6-X03']::text[],false,'{"seq":1,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"『수학익힘』 78쪽 2 — 점 ㄱ을 오른쪽으로 6칸 이동했을 때의 자리는 어느 점인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X02"},{"t":"점 ㅁ","mis":"M4-2-u6-X03"},{"t":"점 ㄷ","mis":"M4-2-u6-X03"}],"explanation":["점 ㄱ이 있는 자리는 세지 않고, 모눈 선을 넘을 때마다 하나씩 세요.","점 ㄱ에서 오른쪽으로 6칸 간 자리를 찾아요.","점 ㄴ이에요"],"asset":{"type":"geo","items":[{"w":270,"h":72,"grid":18,"pts":{"ㄱ":[126,18,"nw"],"ㄴ":[234,18,"n"],"ㄷ":[216,18,"w"],"ㄹ":[18,18,"w"],"ㅁ":[252,18,"e"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#2','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C3',1,'mc','auto','『수학』 138쪽 2 — 점선 도형을 위쪽으로 7칸 민 도형은 어느 것인가요?',ARRAY['M4-2-u6-X03','M4-2-u6-X02','M4-2-u6-X11']::text[],false,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"『수학』 138쪽 2 — 점선 도형을 위쪽으로 7칸 민 도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M4-2-u6-X03"},{"t":"㉱","mis":"M4-2-u6-X02"},{"t":"㉯","mis":"M4-2-u6-X11"}],"explanation":["밀면 모양과 방향은 그대로예요 — 뒤집힌 모양은 아니에요.","같은 꼭짓점끼리 위쪽으로 7칸 떨어져 있어야 해요.","㉮예요"],"asset":{"type":"geo","items":[{"w":108,"h":378,"grid":18,"poly":[[[36.0,36.0],[90.0,108.0],[18.0,108.0]]],"dash":[[[36.0,162.0],[90.0,234.0]],[[90.0,234.0],[18.0,234.0]],[[18.0,234.0],[36.0,162.0]]],"cap":"㉮"},{"w":108,"h":378,"grid":18,"poly":[[[72.0,36.0],[18.0,108.0],[90.0,108.0]]],"dash":[[[36.0,162.0],[90.0,234.0]],[[90.0,234.0],[18.0,234.0]],[[18.0,234.0],[36.0,162.0]]],"cap":"㉯"},{"w":108,"h":378,"grid":18,"poly":[[[36.0,18.0],[90.0,90.0],[18.0,90.0]]],"dash":[[[36.0,162.0],[90.0,234.0]],[[90.0,234.0],[18.0,234.0]],[[18.0,234.0],[36.0,162.0]]],"cap":"㉰"},{"w":108,"h":378,"grid":18,"poly":[[[36.0,288.0],[90.0,360.0],[18.0,360.0]]],"dash":[[[36.0,162.0],[90.0,234.0]],[[90.0,234.0],[18.0,234.0]],[[18.0,234.0],[36.0,162.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#3','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C6',1,'mc','auto','『수학익힘』 82쪽 — 교실 밖에서 「4-1」로 보이도록 창문에 쓰려고 해요. 교실 안에서는 어떻게 써야 하나요?',ARRAY['M4-2-u6-X14','M4-2-u6-X10']::text[],false,'{"seq":3,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학익힘』 82쪽 — 교실 밖에서 「4-1」로 보이도록 창문에 쓰려고 해요. 교실 안에서는 어떻게 써야 하나요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M4-2-u6-X14"},{"t":"㉯","mis":"M4-2-u6-X14"},{"t":"㉮","mis":"M4-2-u6-X10"}],"explanation":["교실 밖에서 보면 안에서 쓴 글씨가 왼쪽이나 오른쪽으로 뒤집혀 보여요.","그래서 「4-1」을 통째로 왼쪽이나 오른쪽으로 뒤집어 써요 — 순서도 바뀌어요.","맨 왼쪽에는 뒤집은 1, 맨 오른쪽에는 뒤집은 4가 와요 — ㉰예요."],"asset":{"type":"geo","items":[{"w":116.0,"h":64,"poly":[[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[29.4,34.4],[34.6,34.4],[34.6,49.6],[29.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[101.4,14.4],[106.6,14.4],[106.6,29.6],[101.4,29.6]],[[101.4,34.4],[106.6,34.4],[106.6,49.6],[101.4,49.6]]],"cap":"교실 밖에서 보일 모양"},{"w":116.0,"h":64,"poly":[[[9.4,34.4],[14.6,34.4],[14.6,49.6],[9.4,49.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[29.4,34.4],[34.6,34.4],[34.6,49.6],[29.4,49.6]],[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[101.4,34.4],[106.6,34.4],[106.6,49.6],[101.4,49.6]],[[101.4,14.4],[106.6,14.4],[106.6,29.6],[101.4,29.6]]],"cap":"㉮"},{"w":116.0,"h":64,"poly":[[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[29.4,34.4],[34.6,34.4],[34.6,49.6],[29.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[81.4,14.4],[86.6,14.4],[86.6,29.6],[81.4,29.6]],[[86.4,29.4],[101.6,29.4],[101.6,34.6],[86.4,34.6]],[[101.4,14.4],[106.6,14.4],[106.6,29.6],[101.4,29.6]],[[101.4,34.4],[106.6,34.4],[106.6,49.6],[101.4,49.6]]],"cap":"㉯"},{"w":116.0,"h":64,"poly":[[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[9.4,34.4],[14.6,34.4],[14.6,49.6],[9.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[101.4,14.4],[106.6,14.4],[106.6,29.6],[101.4,29.6]],[[86.4,29.4],[101.6,29.4],[101.6,34.6],[86.4,34.6]],[[81.4,14.4],[86.6,14.4],[86.6,29.6],[81.4,29.6]],[[81.4,34.4],[86.6,34.4],[86.6,49.6],[81.4,49.6]]],"cap":"㉰"},{"w":116.0,"h":64,"poly":[[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[9.4,34.4],[14.6,34.4],[14.6,49.6],[9.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[81.4,14.4],[86.6,14.4],[86.6,29.6],[81.4,29.6]],[[81.4,34.4],[86.6,34.4],[86.6,49.6],[81.4,49.6]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#4','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C7',1,'mc','auto','『수학』 147쪽 3 — 사각형을 어떻게 돌렸나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":4,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"『수학』 147쪽 3 — 사각형을 어떻게 돌렸나요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 반대 방향으로 90°만큼 돌렸어요","mis":"M4-2-u6-X15"},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"왼쪽이나 오른쪽으로 뒤집었어요","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,36.0],[72.0,54.0],[18.0,72.0],[18.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#5','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C6',1,'mc','auto','『수학익힘』 83쪽 6 — 처음 도형을 한 번 뒤집었을 때 나올 수 있는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u6-X21','M4-2-u6-X13','M4-2-u6-X12']::text[],false,'{"seq":5,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학익힘』 83쪽 6 — 처음 도형을 한 번 뒤집었을 때 나올 수 있는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉰","correct":true},{"t":"㉮, ㉯, ㉰","mis":"M4-2-u6-X21"},{"t":"㉯","mis":"M4-2-u6-X13"},{"t":"㉰","mis":"M4-2-u6-X12"}],"explanation":["위쪽이나 아래쪽으로 뒤집은 ㉮, 왼쪽이나 오른쪽으로 뒤집은 ㉰는 나올 수 있어요.","㉯는 처음 도형과 똑같아 한 번 뒤집어서는 나올 수 없어요.","㉮, ㉰예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[54.0,72.0],[72.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,36.0],[54.0,72.0],[72.0,72.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#6','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C2',1,'mc','auto','『수학』 135쪽 4 — 점 ㄱ을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)',ARRAY['M4-2-u6-X06','M4-2-u6-X02']::text[],false,'{"seq":6,"concept":"M4-2-u6-C2","difficulty":1,"kind":"mc","stem":"『수학』 135쪽 4 — 점 ㄱ을 어떻게 이동했나요? (「전」은 이동 전, 「후」는 이동 후의 자리예요.)","options":[{"t":"아래쪽으로 4칸 이동하고 오른쪽으로 5칸 이동했어요","correct":true},{"t":"아래쪽으로 5칸 이동하고 오른쪽으로 4칸 이동했어요","mis":"M4-2-u6-X06"},{"t":"위쪽으로 4칸 이동하고 오른쪽으로 5칸 이동했어요","mis":"M4-2-u6-X02"},{"t":"아래쪽으로 4칸 이동하고 왼쪽으로 5칸 이동했어요","mis":"M4-2-u6-X02"}],"explanation":["가로로 오른쪽으로 5칸, 세로로 아래쪽으로 4칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"pts":{"전":[18,18,"n"],"후":[108,90,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#7','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C7',1,'error','auto','『수학』 147쪽 3 — 돌리기 전과 돌린 후의 사각형을 보고 친구가 「사각형을 시계 반대 방향으로 90°만큼 돌렸어.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":7,"concept":"M4-2-u6-C7","difficulty":1,"kind":"error","stem":"『수학』 147쪽 3 — 돌리기 전과 돌린 후의 사각형을 보고 친구가 「사각형을 시계 반대 방향으로 90°만큼 돌렸어.」라고 했어요. 친구의 설명에서 잘못된 점은 무엇인가요?","options":[{"t":"위쪽에 있던 짧은 변이 오른쪽으로 갔으니 시계 방향으로 90°만큼 돌린 거예요","correct":true,"mis_target":"M4-2-u6-X15"},{"t":"90°가 아니라 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"돌린 것이 아니라 뒤집은 거예요","mis":"M4-2-u6-X18"},{"t":"잘못된 점이 없어요","mis":"M4-2-u6-X15"}],"explanation":["사각형의 위쪽에 있던 짧은 변이 오른쪽으로 갔어요.","위쪽 → 오른쪽은 시곗바늘이 도는 쪽으로 90°예요.","시계 방향으로 90°(또는 시계 반대 방향으로 270°)만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[36.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,36.0],[72.0,54.0],[18.0,72.0],[18.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#8','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C4',1,'sa','auto','『수학』 138쪽 2 — 도형을 왼쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)','{}'::text[],false,'{"seq":8,"concept":"M4-2-u6-C4","difficulty":1,"kind":"sa","stem":"『수학』 138쪽 2 — 도형을 왼쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","answer":["7"],"explanation":["같은 꼭짓점끼리 견주어요.","왼쪽으로 모눈 선을 넘은 수를 세요.","7칸이에요."],"asset":{"type":"geo","items":[{"w":234,"h":108,"grid":18,"poly":[[[36.0,18.0],[90.0,90.0],[18.0,90.0]]],"dash":[[[162.0,18.0],[216.0,90.0]],[[216.0,90.0],[144.0,90.0]],[[144.0,90.0],[162.0,18.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#9','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C3',2,'mc','auto','『수학』 153쪽 만화 — 로니에게 「액자를 오른쪽으로 3칸 밀어 줘!」라고 했어요. 액자를 밀면 어떻게 되나요?',ARRAY['M4-2-u6-X11','M4-2-u6-X08']::text[],false,'{"seq":9,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학』 153쪽 만화 — 로니에게 「액자를 오른쪽으로 3칸 밀어 줘!」라고 했어요. 액자를 밀면 어떻게 되나요?","options":[{"t":"위치는 변해도 모양은 그대로예요","correct":true},{"t":"액자가 뒤집혀서 왼쪽과 오른쪽이 바뀌어요","mis":"M4-2-u6-X11"},{"t":"액자의 모양이 오른쪽으로 기울어져요","mis":"M4-2-u6-X08"},{"t":"액자의 위치도 모양도 그대로예요","mis":"M4-2-u6-X08"}],"explanation":["밀기는 정한 방향으로 정한 칸 수만큼 옮기는 거예요.","액자의 모양과 방향은 그대로예요.","놓인 위치만 오른쪽으로 3칸 옮겨져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#10','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C5',2,'mc','auto','『수학』 141쪽 1 — 깃발 모양을 아래쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],false,'{"seq":10,"concept":"M4-2-u6-C5","difficulty":2,"kind":"mc","stem":"『수학』 141쪽 1 — 깃발 모양을 아래쪽으로 뒤집으면 무엇과 무엇이 서로 바뀌나요?","options":[{"t":"위쪽과 아래쪽","correct":true},{"t":"왼쪽과 오른쪽","mis":"M4-2-u6-X10"},{"t":"모양과 크기","mis":"M4-2-u6-X11"},{"t":"아무것도 바뀌지 않아요","mis":"M4-2-u6-X11"}],"explanation":["위쪽이나 아래쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀌어요.","왼쪽과 오른쪽은 그대로예요.","위쪽과 아래쪽이 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#11','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C7',2,'mc','auto','『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],false,'{"seq":11,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 방향으로 90°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?","options":[{"t":"오른쪽","correct":true},{"t":"왼쪽","mis":"M4-2-u6-X15"},{"t":"아래쪽","mis":"M4-2-u6-X16"},{"t":"위쪽 그대로","mis":"M4-2-u6-X16"}],"explanation":["시계 방향은 시곗바늘이 도는 쪽이에요.","위쪽에 있던 지붕이 90°만큼 돌아간 자리를 따라가요.","파란색 지붕은 오른쪽으로 가요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[90.0,45.0],[81.0,45.0],[81.0,90.0],[27.0,90.0],[27.0,45.0],[18.0,45.0]]],"cap":"집 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#12','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',2,'mc','auto','『수학』 147쪽 2 — 도형을 시계 반대 방향으로 270°만큼 돌린 것과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X17','M4-2-u6-X16','M4-2-u6-X15']::text[],false,'{"seq":12,"concept":"M4-2-u6-C8","difficulty":2,"kind":"mc","stem":"『수학』 147쪽 2 — 도형을 시계 반대 방향으로 270°만큼 돌린 것과 같은 것은 어느 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌린 것","correct":true},{"t":"시계 방향으로 270°만큼 돌린 것","mis":"M4-2-u6-X17"},{"t":"시계 방향으로 180°만큼 돌린 것","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌린 것","mis":"M4-2-u6-X15"}],"explanation":["한 바퀴는 360°예요.","시계 방향과 시계 반대 방향은 360°에서 빼어 견주어요.","360° − 270° = 90°예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#13','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C3',2,'mc','auto','『수학익힘』 80쪽 — 하늘색 자동차를 오른쪽 출구로 나가게 하려면 분홍색 자동차와 연두색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X25','M4-2-u6-X03']::text[],false,'{"seq":13,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학익힘』 80쪽 — 하늘색 자동차를 오른쪽 출구로 나가게 하려면 분홍색 자동차와 연두색 자동차를 각각 어떻게 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"분홍색 자동차를 왼쪽으로 1칸 밀고, 연두색 자동차를 아래쪽으로 1칸 밀어요","correct":true},{"t":"연두색 자동차를 위쪽으로 1칸 밀어요","mis":"M4-2-u6-X02"},{"t":"연두색 자동차만 아래쪽으로 1칸 밀어요","mis":"M4-2-u6-X25"},{"t":"분홍색 자동차를 왼쪽으로 1칸 밀고, 연두색 자동차를 아래쪽으로 2칸 밀어요","mis":"M4-2-u6-X03"}],"explanation":["연두색 자동차가 출구를 막고 있고, 위쪽은 노란색 자동차가 막아요.","아래쪽으로 1칸 밀려면 그 자리의 분홍색 자동차를 먼저 왼쪽으로 1칸 밀어야 해요.","분홍색 왼쪽 1칸, 연두색 아래쪽 1칸이에요."],"asset":{"type":"geo","items":[{"w":201.0,"h":150,"poly":[[[33.0,63.0],[117.0,63.0],[117.0,87.0],[33.0,87.0]],[[3.0,3.0],[87.0,3.0],[87.0,27.0],[3.0,27.0]],[[123.0,3.0],[147.0,3.0],[147.0,57.0],[123.0,57.0]],[[123.0,63.0],[147.0,63.0],[147.0,117.0],[123.0,117.0]],[[33.0,123.0],[147.0,123.0],[147.0,147.0],[33.0,147.0]]],"lab":[[[75.0,74.0],"하늘"],[[45.0,14.0],"보라"],[[135.0,29.0],"노랑"],[[135.0,89.0],"연두"],[[90.0,134.0],"분홍"],[[175.5,74.0],"출구"]],"seg":[[[0,0],[150,0]],[[0,150],[150,150]],[[0,0],[0,150]],[[150,0],[150,60]],[[150,90],[150,150]]],"dash":[[[30,0],[30,150]],[[60,0],[60,150]],[[90,0],[90,150]],[[120,0],[120,150]],[[0,30],[150,30]],[[0,60],[150,60]],[[0,90],[150,90]],[[0,120],[150,120]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.