INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#17','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C2',3,'mc','auto','지도서 433쪽 확인 문제 2 — 점 ㄱ을 오른쪽으로 3칸 이동하고 위쪽으로 1칸 이동했을 때의 점은 어느 것인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X02']::text[],false,'{"seq":17,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"지도서 433쪽 확인 문제 2 — 점 ㄱ을 오른쪽으로 3칸 이동하고 위쪽으로 1칸 이동했을 때의 점은 어느 것인가요?","options":[{"t":"점 ㄴ","correct":true},{"t":"점 ㅁ","mis":"M4-2-u6-X06"},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄹ","mis":"M4-2-u6-X02"}],"explanation":["점 ㄱ에서 먼저 오른쪽으로 3칸 가요.","그 자리에서 위쪽으로 1칸 가요.","도착한 곳은 점 ㄴ이에요."],"asset":{"type":"geo","items":[{"w":144,"h":108,"grid":18,"pts":{"ㄱ":[72,72,"s"],"ㄴ":[126,54,"ne"],"ㄷ":[18,54,"nw"],"ㄹ":[126,90,"s"],"ㅁ":[90,18,"nw"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#18','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',3,'mc','auto','『수학』 152쪽 7 — 집 모양 도형(위에 정사각형, 아래에 사다리꼴)을 아래쪽으로 3번 뒤집은 것과 결과가 같은 돌리기는 어느 것인가요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":18,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"『수학』 152쪽 7 — 집 모양 도형(위에 정사각형, 아래에 사다리꼴)을 아래쪽으로 3번 뒤집은 것과 결과가 같은 돌리기는 어느 것인가요?","options":[{"t":"시계 방향으로 180°만큼 돌리기","correct":true},{"t":"시계 방향으로 90°만큼 돌리기","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌리기","mis":"M4-2-u6-X16"},{"t":"같은 결과의 돌리기는 없어요","mis":"M4-2-u6-X18"}],"explanation":["아래쪽으로 3번 뒤집으면 1번 뒤집은 것과 같아 위아래가 바뀌어요.","이 도형은 왼쪽과 오른쪽이 똑같아서 180°만큼 돌린 것과도 같아요.","왼쪽과 오른쪽이 다른 도형이라면 결과가 달라요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[90.0,90.0],[18.0,90.0],[36.0,54.0]]],"cap":"이동 전"},{"w":108,"h":108,"grid":18,"poly":[[[36.0,90.0],[72.0,90.0],[72.0,54.0],[90.0,18.0],[18.0,18.0],[36.0,54.0]]],"cap":"이동 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#19','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',3,'mc','auto','지도서 425쪽 오류 2 — 「응」을 시계 반대 방향으로 90°만큼 돌리면 어떻게 보이나요?',ARRAY['M4-2-u6-X26','M4-2-u6-X16']::text[],false,'{"seq":19,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"지도서 425쪽 오류 2 — 「응」을 시계 반대 방향으로 90°만큼 돌리면 어떻게 보이나요?","options":[{"t":"글자처럼 보이지 않아요","correct":true},{"t":"「응」 그대로 보여요","mis":"M4-2-u6-X26"},{"t":"「문」으로 보여요","mis":"M4-2-u6-X16"},{"t":"「을」로 보여요","mis":"M4-2-u6-X16"}],"explanation":["90°만큼 돌리면 가로줄 ㅡ가 세로줄이 돼요.","그래서 「응」으로 보이지 않아요.","180°나 360°만큼 돌릴 때만 「응」으로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#20','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C7',3,'mc','auto','『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 선수가 1루에 도착해 2루로 가려면 먼저 어떤 명령 카드를 써야 하나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X01']::text[],false,'{"seq":20,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 선수가 1루에 도착해 2루로 가려면 먼저 어떤 명령 카드를 써야 하나요?","options":[{"t":"㉡","correct":true},{"t":"㉢","mis":"M4-2-u6-X15"},{"t":"㉠","mis":"M4-2-u6-X01"},{"t":"카드가 필요 없어요","mis":"M4-2-u6-X01"}],"explanation":["1루에서는 2루 쪽으로 방향을 바꾸어야 해요.","2루는 시계 반대 방향으로 90°만큼 돈 쪽에 있어요.","㉡을 쓴 다음 ㉠으로 앞으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#21','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C9',3,'mc','auto','『수학익힘』 86쪽 — 대각선 조각 모양으로 무늬를 만들었어요. 첫째 줄은 어떻게 만들었나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18','M4-2-u6-X19']::text[],false,'{"seq":21,"concept":"M4-2-u6-C9","difficulty":3,"kind":"mc","stem":"『수학익힘』 86쪽 — 대각선 조각 모양으로 무늬를 만들었어요. 첫째 줄은 어떻게 만들었나요?","options":[{"t":"모양을 시계 방향으로 180°만큼 돌리기를 반복했어요","correct":true},{"t":"모양을 시계 방향으로 90°만큼 돌리기를 반복했어요","mis":"M4-2-u6-X16"},{"t":"모양을 오른쪽으로 뒤집기를 반복했어요","mis":"M4-2-u6-X18"},{"t":"모양을 오른쪽으로 밀기를 반복했어요","mis":"M4-2-u6-X19"}],"explanation":["첫째 줄의 이웃한 두 칸을 견주면 위아래와 좌우가 모두 바뀌었어요.","오른쪽으로 뒤집으면 좌우만 바뀌어 이 모양이 나오지 않아요.","시계 방향(또는 시계 반대 방향)으로 180°만큼 돌리기를 반복했어요."],"asset":{"type":"geo","items":[{"w":240,"h":30,"grid":30,"poly":[[[16.5,0],[30,0],[30,30]],[[43.5,30.0],[30.0,30.0],[30.0,0.0]],[[76.5,0.0],[90.0,0.0],[90.0,30.0]],[[103.5,30.0],[90.0,30.0],[90.0,0.0]],[[136.5,0.0],[150.0,0.0],[150.0,30.0]],[[163.5,30.0],[150.0,30.0],[150.0,0.0]],[[196.5,0.0],[210.0,0.0],[210.0,30.0]],[[223.5,30.0],[210.0,30.0],[210.0,0.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#22','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C6',3,'mc','auto','『수학』 152쪽 7 — 동연이는 「도형을 아래쪽으로 3번 뒤집었어.」라고 했어요(이동 후는 위아래가 바뀐 모양). 이동 후와 같은 도형이 되도록 아래쪽으로 뒤집을 수 있는 횟수를 모두 고른 것은 어느 것인가요?',ARRAY['M4-2-u6-X13']::text[],false,'{"seq":22,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"『수학』 152쪽 7 — 동연이는 「도형을 아래쪽으로 3번 뒤집었어.」라고 했어요(이동 후는 위아래가 바뀐 모양). 이동 후와 같은 도형이 되도록 아래쪽으로 뒤집을 수 있는 횟수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1번, 3번, 5번","correct":true},{"t":"2번, 4번","mis":"M4-2-u6-X13"},{"t":"3번","mis":"M4-2-u6-X13"},{"t":"1번, 2번, 3번","mis":"M4-2-u6-X13"}],"explanation":["아래쪽으로 한 번 뒤집으면 위아래가 바뀌고, 두 번이면 처음으로 돌아와요.","그래서 1번, 3번, 5번처럼 홀수 번 뒤집으면 위아래가 바뀐 모양이에요.","동연이의 설명은 맞아요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[90.0,90.0],[18.0,90.0],[36.0,54.0]]],"cap":"이동 전"},{"w":108,"h":108,"grid":18,"poly":[[[36.0,90.0],[72.0,90.0],[72.0,54.0],[90.0,18.0],[18.0,18.0],[36.0,54.0]]],"cap":"이동 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#23','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',4,'essay','teacher','『수학』 147쪽 4 — 마지막 퍼즐 조각을 빈 곳에 넣으려면 조각을 어떻게 돌려야 하는지 두 가지 방법으로 설명하고, 두 방법의 결과가 같은 까닭을 써 보세요. (빈 곳은 튀어나온 부분이 위쪽에, 조각은 튀어나온 부분이 오른쪽에 있어요.)','{}'::text[],false,'{"seq":23,"concept":"M4-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 147쪽 4 — 마지막 퍼즐 조각을 빈 곳에 넣으려면 조각을 어떻게 돌려야 하는지 두 가지 방법으로 설명하고, 두 방법의 결과가 같은 까닭을 써 보세요. (빈 곳은 튀어나온 부분이 위쪽에, 조각은 튀어나온 부분이 오른쪽에 있어요.)","answer_guide":{"answer":"방법 1: 시계 반대 방향으로 90°만큼 돌려요. 방법 2: 시계 방향으로 270°만큼 돌려요. 한 바퀴는 360°라서 시계 반대 방향으로 90°는 시계 방향으로 360° − 90° = 270°와 같은 자리예요.","scoring_points":["시계 반대 방향 90°","시계 방향 270°","360°에서 빼어 같은 까닭"]},"explanation":["튀어나온 부분을 오른쪽에서 위쪽으로 옮겨요.","시계 반대 방향으로 90°예요.","시계 방향으로는 270°예요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"dash":[[[21.6,68.4],[21.6,32.4]],[[21.6,32.4],[34.2,32.4]],[[34.2,32.4],[32.4,21.6]],[[32.4,21.6],[46.8,21.6]],[[46.8,21.6],[45.0,32.4]],[[45.0,32.4],[57.6,32.4]],[[57.6,32.4],[57.6,68.4]],[[57.6,68.4],[21.6,68.4]]],"cap":"빈 곳(점선)"},{"w":90,"h":90,"grid":18,"poly":[[[21.6,27.0],[57.6,27.0],[57.6,39.6],[68.4,37.8],[68.4,52.2],[57.6,50.4],[57.6,63.0],[21.6,63.0]]],"cap":"퍼즐 조각"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#24','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',4,'mc','auto','『수학익힘』 85쪽 4 — 처음 조각을 시계 방향이나 시계 반대 방향으로 돌렸을 때 나올 수 없는 조각은 어느 것인가요?',ARRAY['M4-2-u6-X21']::text[],false,'{"seq":24,"concept":"M4-2-u6-C8","difficulty":4,"kind":"mc","stem":"『수학익힘』 85쪽 4 — 처음 조각을 시계 방향이나 시계 반대 방향으로 돌렸을 때 나올 수 없는 조각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X21"},{"t":"㉰","mis":"M4-2-u6-X21"},{"t":"㉱","mis":"M4-2-u6-X21"}],"explanation":["돌리면 모양은 그대로이고 방향만 바뀌어요.","㉯는 처음 조각을 뒤집은 모양이라 아무리 돌려도 나올 수 없어요.","㉮는 180°, ㉰는 시계 방향으로 270°, ㉱는 360°만큼 돌린 조각이에요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[54.0,36.0],[36.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"처음 조각"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,72.0],[18.0,72.0],[18.0,54.0],[36.0,54.0],[36.0,18.0],[54.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,18.0],[18.0,18.0],[18.0,36.0],[36.0,36.0],[36.0,72.0],[54.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,54.0],[18.0,18.0],[36.0,18.0],[36.0,36.0],[72.0,36.0],[72.0,54.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[54.0,36.0],[36.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_b#25','math',4,2,'u6','','tb_g4_2_math_u6_review_b','unit_review','M4-2-u6-C8',4,'essay','teacher','『수학』 152쪽 7 — 하윤이는 「도형을 시계 방향으로 90°만큼 돌렸어.」라고 했어요(이동 후는 위에 사다리꼴, 아래에 정사각형). 하윤이의 설명이 왜 틀렸는지 쓰고, 바르게 고친 설명을 두 가지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u6-C8","difficulty":4,"kind":"essay","stem":"『수학』 152쪽 7 — 하윤이는 「도형을 시계 방향으로 90°만큼 돌렸어.」라고 했어요(이동 후는 위에 사다리꼴, 아래에 정사각형). 하윤이의 설명이 왜 틀렸는지 쓰고, 바르게 고친 설명을 두 가지 써 보세요.","answer_guide":{"answer":"시계 방향으로 90°만큼 돌리면 위쪽의 정사각형이 오른쪽으로 가는데, 이동 후는 정사각형이 아래쪽으로 갔어요. 바르게: 시계 방향으로 180°만큼 돌렸어요. 또는 시계 반대 방향으로 180°만큼(시계 방향으로 90°만큼 2번) 돌렸어요.","scoring_points":["90°면 정사각형이 오른쪽으로 감","시계 방향 180°","다른 표현(시계 반대 180°, 90°만큼 2번)"]},"explanation":["위쪽 부분이 간 자리를 따라가요.","아래쪽으로 갔으니 180°예요.","180°는 어느 쪽으로 돌려도 같아요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[72.0,54.0],[90.0,90.0],[18.0,90.0],[36.0,54.0]]],"cap":"이동 전"},{"w":108,"h":108,"grid":18,"poly":[[[72.0,90.0],[36.0,90.0],[36.0,54.0],[18.0,18.0],[90.0,18.0],[72.0,54.0]]],"cap":"이동 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#1','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C1',1,'mc','auto','『수학』 134쪽 2 — 점 ㄱ을 오른쪽으로 3 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03']::text[],false,'{"seq":1,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"『수학』 134쪽 2 — 점 ㄱ을 오른쪽으로 3 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"점 ㄹ","correct":true},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"},{"t":"점 ㅁ","mis":"M4-2-u6-X03"}],"explanation":["모눈 한 칸이 1 cm라서 3 cm는 3칸이에요.","점 ㄱ에서 오른쪽으로 3칸 간 자리를 찾아요.","점 ㄹ이에요"],"asset":{"type":"geo","items":[{"w":162,"h":72,"grid":18,"pts":{"ㄱ":[72,18,"nw"],"ㄴ":[144,18,"e"],"ㄷ":[18,18,"w"],"ㄹ":[126,18,"n"],"ㅁ":[108,18,"sw"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#2','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C3',1,'mc','auto','『수학익힘』 80쪽 3 — 점선 도형을 왼쪽으로 4칸 민 도형은 어느 것인가요?',ARRAY['M4-2-u6-X03','M4-2-u6-X02','M4-2-u6-X11']::text[],false,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"『수학익힘』 80쪽 3 — 점선 도형을 왼쪽으로 4칸 민 도형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉰","mis":"M4-2-u6-X03"},{"t":"㉮","mis":"M4-2-u6-X02"},{"t":"㉱","mis":"M4-2-u6-X11"}],"explanation":["밀면 모양과 방향은 그대로예요 — 뒤집힌 모양은 아니에요.","같은 꼭짓점끼리 왼쪽으로 4칸 떨어져 있어야 해요.","㉯예요"],"asset":{"type":"geo","items":[{"w":252,"h":90,"grid":18,"poly":[[[180.0,18.0],[234.0,18.0],[198.0,72.0],[180.0,72.0]]],"dash":[[[108.0,18.0],[162.0,18.0]],[[162.0,18.0],[126.0,72.0]],[[126.0,72.0],[108.0,72.0]],[[108.0,72.0],[108.0,18.0]]],"cap":"㉮"},{"w":252,"h":90,"grid":18,"poly":[[[36.0,18.0],[90.0,18.0],[54.0,72.0],[36.0,72.0]]],"dash":[[[108.0,18.0],[162.0,18.0]],[[162.0,18.0],[126.0,72.0]],[[126.0,72.0],[108.0,72.0]],[[108.0,72.0],[108.0,18.0]]],"cap":"㉯"},{"w":252,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[36.0,72.0],[18.0,72.0]]],"dash":[[[108.0,18.0],[162.0,18.0]],[[162.0,18.0],[126.0,72.0]],[[126.0,72.0],[108.0,72.0]],[[108.0,72.0],[108.0,18.0]]],"cap":"㉰"},{"w":252,"h":90,"grid":18,"poly":[[[90.0,18.0],[36.0,18.0],[72.0,72.0],[90.0,72.0]]],"dash":[[[108.0,18.0],[162.0,18.0]],[[162.0,18.0],[126.0,72.0]],[[126.0,72.0],[108.0,72.0]],[[108.0,72.0],[108.0,18.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=t