INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#3','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',1,'mc','auto','『수학』 143쪽 4 — 교실 밖에서 「4-3」으로 보이도록 창문에 쓰려고 해요. 교실 안에서는 어떻게 써야 하나요?',ARRAY['M4-2-u6-X14','M4-2-u6-X10']::text[],false,'{"seq":3,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학』 143쪽 4 — 교실 밖에서 「4-3」으로 보이도록 창문에 쓰려고 해요. 교실 안에서는 어떻게 써야 하나요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u6-X14"},{"t":"㉰","mis":"M4-2-u6-X14"},{"t":"㉱","mis":"M4-2-u6-X10"}],"explanation":["교실 밖에서 보면 안에서 쓴 글씨가 왼쪽이나 오른쪽으로 뒤집혀 보여요.","그래서 「4-3」을 통째로 왼쪽이나 오른쪽으로 뒤집어 써요 — 순서도 바뀌어요.","맨 왼쪽에는 뒤집은 3, 맨 오른쪽에는 뒤집은 4가 와요 — ㉯예요."],"asset":{"type":"geo","items":[{"w":116.0,"h":64,"poly":[[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[29.4,34.4],[34.6,34.4],[34.6,49.6],[29.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[86.4,9.4],[101.6,9.4],[101.6,14.6],[86.4,14.6]],[[101.4,14.4],[106.6,14.4],[106.6,29.6],[101.4,29.6]],[[86.4,29.4],[101.6,29.4],[101.6,34.6],[86.4,34.6]],[[101.4,34.4],[106.6,34.4],[106.6,49.6],[101.4,49.6]],[[86.4,49.4],[101.6,49.4],[101.6,54.6],[86.4,54.6]]],"cap":"교실 밖에서 보일 모양"},{"w":116.0,"h":64,"poly":[[[29.4,14.4],[34.6,14.4],[34.6,29.6],[29.4,29.6]],[[14.4,29.4],[29.6,29.4],[29.6,34.6],[14.4,34.6]],[[9.4,14.4],[14.6,14.4],[14.6,29.6],[9.4,29.6]],[[9.4,34.4],[14.6,34.4],[14.6,49.6],[9.4,49.6]],[[50.4,29.4],[65.6,29.4],[65.6,34.6],[50.4,34.6]],[[86.4,9.4],[101.6,9.4],[101.6,14.6],[86.4,14.6]],[[81.4,14.4],[86.6,14.4],[86.6,29.6],[81.4,29.6]],[[86.4,29.4],[101.6,29.4],[101.6,34.6],[86.4,34.6]],[[81.4,34.4],[86.6,34.4],[86.6,49.6],[81.4,49.6]],[[86.4,49.4],[101.6,49.4],[101.6,54.6],[86.4,54.6]]],"cap":"㉮"},{"w":116.0,"h":64,"poly":[[[14.4,9.4],