INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#15','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C7',2,'mc','auto','『수학익힘』 84쪽 2 — 처음 도형을 시계 반대 방향으로 270°만큼 돌린 도형은 어느 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":15,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학익힘』 84쪽 2 — 처음 도형을 시계 반대 방향으로 270°만큼 돌린 도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M4-2-u6-X15"},{"t":"㉯","mis":"M4-2-u6-X16"},{"t":"㉰","mis":"M4-2-u6-X18"}],"explanation":["시계 반대 방향은 시곗바늘이 도는 쪽의 반대쪽이에요.","처음 도형의 위쪽 부분이 270°만큼 돌아간 자리를 따라가요.","㉱예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[18.0,36.0],[72.0,18.0],[72.0,72.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,72.0],[72.0,72.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[72.0,54.0],[18.0,72.0],[18.0,18.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
