INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#18','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C8',3,'mc','auto','지도서 424쪽 오류 1 — 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것의 결과가 같은 도형은 어느 것인가요?',ARRAY['M4-2-u6-X18']::text[],false,'{"seq":18,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"지도서 424쪽 오류 1 — 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것의 결과가 같은 도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X18"},{"t":"㉰","mis":"M4-2-u6-X18"},{"t":"모두 같아요","mis":"M4-2-u6-X18"}],"explanation":["왼쪽과 오른쪽이 똑같은 도형만 두 결과가 같아요.","㉮ T 모양은 세로로 반을 접으면 완전히 겹쳐요.","㉯ 깃발 모양과 ㉰ 사각형은 결과가 달라요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[72.0,36.0],[54.0,36.0],[54.0,72.0],[36.0,72.0],[36.0,36.0],[18.0,36.0]]],"cap":"㉮"},{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"㉯"},{"w":90,"h":108,"grid":18,"poly":[[[18.0,36.0],[72.0,18.0],[72.0,72.0],[18.0,72.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#19','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',3,'mc','auto','지도서 425쪽 오류 2 — 「응」을 위쪽이나 아래쪽으로 뒤집으면 어떻게 보이나요?',ARRAY['M4-2-u6-X14','M4-2-u6-X10']::text[],false,'{"seq":19,"concept":"M4-2-u6-C6","difficulty":3,"kind":"mc","stem":"지도서 425쪽 오류 2 — 「응」을 위쪽이나 아래쪽으로 뒤집으면 어떻게 보이나요?","options":[{"t":"「응」으로 보여요","correct":true},{"t":"글자처럼 보이지 않아요","mis":"M4-2-u6-X14"},{"t":"「은」으로 보여요","mis":"M4-2-u6-X10"},{"t":"「을」로 보여요","mis":"M4-2-u6-X10"}],"explanation":["「응」은 윗부분(ㅇ)과 아랫부분(ㅇ)이 같아요.","왼쪽과 오른쪽도 같아요.","그래서 어느 쪽으로 뒤집어도 「응」으로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#20','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C7',3,'sa','auto','『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 홈에서 출발해 1루, 2루, 3루를 거쳐 홈으로 돌아올 때 ㉠ 카드는 모두 몇 장 쓰나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M4-2-u6-C7","difficulty":3,"kind":"sa","stem":"『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 홈에서 출발해 1루, 2루, 3루를 거쳐 홈으로 돌아올 때 ㉠ 카드는 모두 몇 장 쓰나요? 숫자로 쓰세요.","answer":["4"],"explanation":["홈→1루, 1루→2루, 2루→3루, 3루→홈으로 앞으로 가요.","앞으로 갈 때마다 ㉠을 한 장씩 써요.","모두 4장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#21','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C9',3,'mc','auto','『수학』 149쪽 2 「보기」 — 반원 모양으로 만든 무늬의 첫 줄은 어떻게 만들었나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X19','M4-2-u6-X18']::text[],false,'{"seq":21,"concept":"M4-2-u6-C9","difficulty":3,"kind":"mc","stem":"『수학』 149쪽 2 「보기」 — 반원 모양으로 만든 무늬의 첫 줄은 어떻게 만들었나요?","options":[{"t":"반원 모양을 시계 방향으로 180° 돌리기를 반복했어요","correct":true},{"t":"반원 모양을 시계 방향으로 90° 돌리기를 반복했어요","mis":"M4-2-u6-X16"},{"t":"반원 모양을 오른쪽으로 밀기를 반복했어요","mis":"M4-2-u6-X19"},{"t":"반원 모양을 오른쪽으로 뒤집기를 반복했어요","mis":"M4-2-u6-X18"}],"explanation":["첫 줄에서 이웃한 칸의 반원은 아래쪽, 위쪽으로 번갈아 붙어 있어요.","반원 모양은 왼쪽과 오른쪽이 같아서 오른쪽으로 뒤집어도 그대로예요.","180° 돌리기를 반복했어요."],"asset":{"type":"geo","items":[{"w":120,"h":30,"grid":30,"poly":[[[3.6,30.0],[4.47,25.64],[6.94,21.94],[10.64,19.47],[15.0,18.6],[19.36,19.47],[23.06,21.94],[25.53,25.64],[26.4,30.0]],[[56.4,0.0],[55.53,4.36],[53.06,8.06],[49.36,10.53],[45.0,11.4],[40.64,10.53],[36.94,8.06],[34.47,4.36],[33.6,0.0]],[[63.6,30.0],[64.47,25.64],[66.94,21.94],[70.64,19.47],[75.0,18.6],[79.36,19.47],[83.06,21.94],[85.53,25.64],[86.4,30.0]],[[116.4,0.0],[115.53,4.36],[113.06,8.06],[109.36,10.53],[105.0,11.4],[100.64,10.53],[96.94,8.06],[94.47,4.36],[93.6,0.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#22','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C7',3,'mc','auto','지도서 459쪽 — 도형을 시계 방향으로 90°만큼 2번 돌린 것과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":22,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"지도서 459쪽 — 도형을 시계 방향으로 90°만큼 2번 돌린 것과 같은 것은 어느 것인가요?","options":[{"t":"시계 방향으로 180°만큼 돌린 것","correct":true},{"t":"시계 방향으로 90°만큼 돌린 것","mis":"M4-2-u6-X16"},{"t":"처음 도형","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 뒤집은 것","mis":"M4-2-u6-X18"}],"explanation":["90°만큼 2번 돌리면 모두 90° + 90°만큼 돌린 거예요.","그래서 180°만큼 돌린 것과 같아요.","하윤이의 설명을 고칠 때 「90°만큼 2번」이라고 해도 답이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#23','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',4,'essay','teacher','『수학』 143쪽 4 — 교실 밖에서 「4-3」으로 보이도록 교실 안 창문에 쓰려고 해요. 어떻게 써야 하는지 4, -, 3을 하나씩 들어 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M4-2-u6-C6","difficulty":4,"kind":"essay","stem":"『수학』 143쪽 4 — 교실 밖에서 「4-3」으로 보이도록 교실 안 창문에 쓰려고 해요. 어떻게 써야 하는지 4, -, 3을 하나씩 들어 설명해 보세요.","answer_guide":{"answer":"「4-3」을 왼쪽이나 오른쪽으로 뒤집어 써요. 순서도 뒤집히므로 가장 오른쪽에 있던 3을 가장 왼쪽에 왼쪽과 오른쪽을 바꾸어 쓰고, -는 뒤집어도 그대로 -로 쓰고, 4는 왼쪽의 뾰족한 부분이 오른쪽으로 가게 바꾸어 가장 오른쪽에 써요.","scoring_points":["왼쪽이나 오른쪽으로 뒤집어 쓴다","순서가 바뀌어 3이 가장 왼쪽","3과 4는 각각 좌우를 바꾸어 쓰고 -는 그대로"]},"explanation":["교실 밖에서 보면 안에서 쓴 글씨의 왼쪽과 오른쪽이 바뀌어요.","글자 하나하나뿐 아니라 순서까지 뒤집혀요.","3, -, 4 순서로 각각 뒤집어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#24','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C6',4,'mc','auto','『수학익힘』 83쪽 5 — 조각을 오른쪽으로 한 번 뒤집었을 때 조각의 방향이 처음과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11']::text[],false,'{"seq":24,"concept":"M4-2-u6-C6","difficulty":4,"kind":"mc","stem":"『수학익힘』 83쪽 5 — 조각을 오른쪽으로 한 번 뒤집었을 때 조각의 방향이 처음과 같은 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u6-X10"},{"t":"㉰","mis":"M4-2-u6-X10"},{"t":"모두 처음과 달라져요","mis":"M4-2-u6-X11"}],"explanation":["오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어요.","왼쪽과 오른쪽이 똑같은 조각(곧게 이어진 4칸 조각)은 뒤집어도 처음과 같아요.","㉮예요"],"asset":{"type":"geo","items":[{"w":108,"h":90,"grid":18,"poly":[[[18.0,36.0],[90.0,36.0],[90.0,54.0],[18.0,54.0]]],"cap":"㉮"},{"w":108,"h":90,"grid":18,"poly":[[[36.0,36.0],[54.0,36.0],[54.0,18.0],[72.0,18.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[36.0,72.0]]],"cap":"㉯"},{"w":108,"h":90,"grid":18,"poly":[[[36.0,54.0],[54.0,54.0],[54.0,18.0],[72.0,18.0],[72.0,72.0],[36.0,72.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_c#25','math',4,2,'u6','','tb_g4_2_math_u6_review_c','unit_review','M4-2-u6-C2',4,'essay','teacher','『수학』 135쪽 4 — 점 ㄱ은 아래쪽으로 4칸, 오른쪽으로 5칸 옮겨졌는데 소율이는 「아래쪽으로 5칸 이동하고, 오른쪽으로 4칸 이동했어.」라고 했어요. 소율이의 설명에서 잘못된 점을 쓰고, 바르게 고친 설명을 두 가지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u6-C2","difficulty":4,"kind":"essay","stem":"『수학』 135쪽 4 — 점 ㄱ은 아래쪽으로 4칸, 오른쪽으로 5칸 옮겨졌는데 소율이는 「아래쪽으로 5칸 이동하고, 오른쪽으로 4칸 이동했어.」라고 했어요. 소율이의 설명에서 잘못된 점을 쓰고, 바르게 고친 설명을 두 가지 써 보세요.","answer_guide":{"answer":"소율이는 방향마다 칸 수를 서로 바꾸어 붙였어요. 바르게: 아래쪽으로 4칸 이동하고, 오른쪽으로 5칸 이동했어요. 또는 오른쪽으로 5칸 이동하고, 아래쪽으로 4칸 이동했어요.","scoring_points":["칸 수를 바꾸어 붙인 잘못","아래쪽 4칸·오른쪽 5칸","순서를 바꾼 다른 설명"]},"explanation":["이동 전과 이동 후를 견주어 방향마다 칸을 세요.","아래쪽은 4칸, 오른쪽은 5칸이에요.","순서를 바꾸어 말해도 돼요."],"asset":{"type":"geo","items":[{"w":126,"h":108,"grid":18,"pts":{"전":[18,18,"n"],"후":[108,90,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#1','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C1',1,'mc','auto','『수학익힘』 79쪽 3 — 점 ㄱ을 아래쪽으로 2 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)',ARRAY['M4-2-u6-X02','M4-2-u6-X03']::text[],false,'{"seq":1,"concept":"M4-2-u6-C1","difficulty":1,"kind":"mc","stem":"『수학익힘』 79쪽 3 — 점 ㄱ을 아래쪽으로 2 cm 이동했을 때의 자리는 어느 점인가요? (모눈 한 칸은 1 cm예요.)","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X02"},{"t":"점 ㄷ","mis":"M4-2-u6-X03"},{"t":"점 ㄴ","mis":"M4-2-u6-X03"}],"explanation":["모눈 한 칸이 1 cm라서 2 cm는 2칸이에요.","점 ㄱ에서 아래쪽으로 2칸 간 자리를 찾아요.","점 ㅁ이에요"],"asset":{"type":"geo","items":[{"w":90,"h":126,"grid":18,"pts":{"ㄱ":[18,54,"ne"],"ㄴ":[18,72,"e"],"ㄷ":[18,108,"s"],"ㄹ":[18,18,"n"],"ㅁ":[18,90,"w"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#2','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C3',1,'mc','auto','『수학』 138쪽 2 — 점선 도형을 오른쪽으로 7칸 민 도형은 어느 것인가요?',ARRAY['M4-2-u6-X03','M4-2-u6-X02','M4-2-u6-X11']::text[],false,'{"seq":2,"concept":"M4-2-u6-C3","difficulty":1,"kind":"mc","stem":"『수학』 138쪽 2 — 점선 도형을 오른쪽으로 7칸 민 도형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉰","mis":"M4-2-u6-X03"},{"t":"㉮","mis":"M4-2-u6-X02"},{"t":"㉯","mis":"M4-2-u6-X11"}],"explanation":["밀면 모양과 방향은 그대로예요 — 뒤집힌 모양은 아니에요.","같은 꼭짓점끼리 오른쪽으로 7칸 떨어져 있어야 해요.","㉱예요"],"asset":{"type":"geo","items":[{"w":378,"h":108,"grid":18,"poly":[[[36.0,18.0],[90.0,90.0],[18.0,90.0]]],"dash":[[[162.0,18.0],[216.0,90.0]],[[216.0,90.0],[144.0,90.0]],[[144.0,90.0],[162.0,18.0]]],"cap":"㉮"},{"w":378,"h":108,"grid":18,"poly":[[[324.0,18.0],[270.0,90.0],[342.0,90.0]]],"dash":[[[162.0,18.0],[216.0,90.0]],[[216.0,90.0],[144.0,90.0]],[[144.0,90.0],[162.0,18.0]]],"cap":"㉯"},{"w":378,"h":108,"grid":18,"poly":[[[306.0,18.0],[360.0,90.0],[288.0,90.0]]],"dash":[[[162.0,18.0],[216.0,90.0]],[[216.0,90.0],[144.0,90.0]],[[144.0,90.0],[162.0,18.0]]],"cap":"㉰"},{"w":378,"h":108,"grid":18,"poly":[[[288.0,18.0],[342.0,90.0],[270.0,90.0]]],"dash":[[[162.0,18.0],[216.0,90.0]],[[216.0,90.0],[144.0,90.0]],[[144.0,90.0],[162.0,18.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#3','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C6',1,'mc','auto','『수학익힘』 83쪽 퐁당 — 판화는 판에 새긴 그림을 종이에 찍어 내요. 종이에 찍은 그림이 원하는 모양이 되려면 판에 그림을 어떻게 새겨야 하나요?',ARRAY['M4-2-u6-X14','M4-2-u6-X11','M4-2-u6-X18']::text[],false,'{"seq":3,"concept":"M4-2-u6-C6","difficulty":1,"kind":"mc","stem":"『수학익힘』 83쪽 퐁당 — 판화는 판에 새긴 그림을 종이에 찍어 내요. 종이에 찍은 그림이 원하는 모양이 되려면 판에 그림을 어떻게 새겨야 하나요?","options":[{"t":"왼쪽과 오른쪽을 뒤집어 새겨요","correct":true},{"t":"원하는 모양 그대로 새겨요","mis":"M4-2-u6-X14"},{"t":"위쪽으로 밀어 새겨요","mis":"M4-2-u6-X11"},{"t":"시계 방향으로 90°만큼 돌려 새겨요","mis":"M4-2-u6-X18"}],"explanation":["판에 새긴 그림을 종이에 찍으면 뒤집혀 보여요.","왼쪽과 오른쪽이 바뀌어 찍혀요.","그래서 미리 왼쪽과 오른쪽을 뒤집어 새겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#4','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C7',1,'mc','auto','『수학익힘』 84쪽 3 — 도형을 시계 방향으로 몇 도만큼 돌렸나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":4,"concept":"M4-2-u6-C7","difficulty":1,"kind":"mc","stem":"『수학익힘』 84쪽 3 — 도형을 시계 방향으로 몇 도만큼 돌렸나요?","options":[{"t":"시계 방향으로 90°만큼 돌렸어요","correct":true},{"t":"시계 방향으로 180°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"시계 방향으로 270°만큼 돌렸어요","mis":"M4-2-u6-X16"},{"t":"위쪽이나 아래쪽으로 뒤집었어요","mis":"M4-2-u6-X18"}],"explanation":["처음 도형의 위쪽 부분이 어디로 갔는지 따라가요.","시곗바늘이 도는 쪽인지, 반대쪽인지 정해요.","시계 방향으로 90°만큼 돌렸어요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[72.0,18.0],[72.0,72.0],[18.0,72.0],[18.0,54.0],[36.0,54.0],[36.0,36.0],[18.0,36.0]]],"cap":"돌리기 전"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[72.0,72.0],[18.0,72.0],[18.0,18.0],[36.0,18.0],[36.0,36.0],[54.0,36.0],[54.0,18.0]]],"cap":"돌린 후"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#5','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C5',1,'mc','auto','『수학익힘』 82쪽 1 — 처음 도형을 아래쪽으로 뒤집은 도형은 어느 것인가요?',ARRAY['M4-2-u6-X10','M4-2-u6-X18']::text[],false,'{"seq":5,"concept":"M4-2-u6-C5","difficulty":1,"kind":"mc","stem":"『수학익힘』 82쪽 1 — 처음 도형을 아래쪽으로 뒤집은 도형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉱","mis":"M4-2-u6-X10"},{"t":"㉮","mis":"M4-2-u6-X18"},{"t":"㉯","mis":"M4-2-u6-X18"}],"explanation":["아래쪽으로 뒤집으면 위쪽과 아래쪽이 서로 바뀌어요.","모양과 크기는 그대로이고 방향만 바뀌어요.","㉰예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[45.0,45.0],[72.0,18.0],[72.0,45.0],[45.0,72.0],[18.0,45.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[45.0,45.0],[72.0,72.0],[45.0,72.0],[18.0,45.0],[45.0,18.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[45.0,45.0],[18.0,18.0],[45.0,18.0],[72.0,45.0],[45.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[45.0,45.0],[72.0,72.0],[72.0,45.0],[45.0,18.0],[18.0,45.0]]],"cap":"㉰"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[45.0,45.0],[18.0,18.0],[18.0,45.0],[45.0,72.0],[72.0,45.0]]],"cap":"㉱"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#6','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C2',1,'mc','auto','『수학익힘』 78쪽 — 출발점에서 집까지 어떻게 이동해야 하나요?',ARRAY['M4-2-u6-X02','M4-2-u6-X01']::text[],false,'{"seq":6,"concept":"M4-2-u6-C2","difficulty":1,"kind":"mc","stem":"『수학익힘』 78쪽 — 출발점에서 집까지 어떻게 이동해야 하나요?","options":[{"t":"위쪽으로 2칸 이동하고 오른쪽으로 2칸 이동해요","correct":true},{"t":"아래쪽으로 2칸 이동하고 오른쪽으로 2칸 이동해요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 2칸 이동하고 왼쪽으로 2칸 이동해요","mis":"M4-2-u6-X02"},{"t":"위쪽으로 2칸 이동해요","mis":"M4-2-u6-X01"}],"explanation":["가로로 오른쪽으로 2칸, 세로로 위쪽으로 2칸 떨어져 있어요.","방향마다 칸 수를 바르게 붙여요.","말하는 순서를 바꾸어도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":90,"h":72,"grid":18,"pts":{"출발":[18,54,"sw"],"집":[54,18,"ne"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#7','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C7',1,'error','auto','『수학익힘』 85쪽 퐁당 — 초록 조각을 돌려서 빈 곳을 채우려고 해요. 친구는 「조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳을 채울 수 있어.」라고 풀었어요. 잘못된 부분을 바르게 고친 것은 어느 것인가요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":7,"concept":"M4-2-u6-C7","difficulty":1,"kind":"error","stem":"『수학익힘』 85쪽 퐁당 — 초록 조각을 돌려서 빈 곳을 채우려고 해요. 친구는 「조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳을 채울 수 있어.」라고 풀었어요. 잘못된 부분을 바르게 고친 것은 어느 것인가요?","options":[{"t":"시계 방향으로 90°만큼 돌려야 빈 곳을 채울 수 있어요","correct":true,"mis_target":"M4-2-u6-X15"},{"t":"시계 반대 방향으로 180°만큼 돌려야 해요","mis":"M4-2-u6-X16"},{"t":"오른쪽으로 뒤집어야 해요","mis":"M4-2-u6-X18"},{"t":"시계 반대 방향으로 90°가 맞아요","mis":"M4-2-u6-X15"}],"explanation":["조각을 시계 반대 방향으로 90°만큼 돌리면 빈 곳과 모양이 맞지 않아요.","빈 곳은 조각을 시곗바늘이 도는 쪽으로 90°만큼 돌린 모양이에요.","시계 방향으로 90°(또는 시계 반대 방향으로 270°)만큼 돌려요."],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,36.0],[36.0,36.0],[36.0,18.0],[54.0,18.0],[54.0,36.0],[72.0,36.0],[72.0,54.0],[36.0,54.0],[36.0,72.0],[18.0,72.0]]],"cap":"조각"},{"w":90,"h":90,"grid":18,"poly":[[[54.0,18.0],[54.0,36.0],[72.0,36.0],[72.0,54.0],[54.0,54.0],[54.0,72.0],[36.0,72.0],[36.0,36.0],[18.0,36.0],[18.0,18.0]]],"cap":"빈 곳의 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#8','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C4',1,'sa','auto','『수학익힘』 81쪽 5 — 도형을 위쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)','{}'::text[],false,'{"seq":8,"concept":"M4-2-u6-C4","difficulty":1,"kind":"sa","stem":"『수학익힘』 81쪽 5 — 도형을 위쪽으로 몇 칸 밀었나요? 숫자로 쓰세요. (점선은 밀기 전, 색칠한 도형은 민 후예요.)","answer":["3"],"explanation":["같은 꼭짓점끼리 견주어요.","위쪽으로 모눈 선을 넘은 수를 세요.","3칸이에요."],"asset":{"type":"geo","items":[{"w":162,"h":108,"grid":18,"poly":[[[90.0,36.0],[108.0,18.0],[144.0,18.0],[126.0,36.0]]],"dash":[[[18.0,90.0],[36.0,72.0]],[[36.0,72.0],[72.0,72.0]],[[72.0,72.0],[54.0,90.0]],[[54.0,90.0],[18.0,90.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#9','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C3',2,'ox','auto','지도서 435쪽 「이런 활동도 있어요」 — 가게에서 카트를 앞으로 밀면 카트의 모양은 그대로이고 위치만 바뀌어요.',ARRAY['M4-2-u6-X08']::text[],false,'{"seq":9,"concept":"M4-2-u6-C3","difficulty":2,"kind":"ox","stem":"지도서 435쪽 「이런 활동도 있어요」 — 가게에서 카트를 앞으로 밀면 카트의 모양은 그대로이고 위치만 바뀌어요.","answer":"O","reason_options":[{"t":"밀기는 놓인 곳만 바꾸어서","correct":true},{"t":"밀면 물건의 모양도 조금씩 바뀌어서","mis":"M4-2-u6-X08"}],"mis":"M4-2-u6-X08","explanation":["문을 열고 닫거나, 걸레로 바닥을 밀거나, 카트를 미는 것도 밀기예요.","물건을 밀면 모양은 그대로예요.","위치만 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#10','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C6',2,'mc','auto','『수학』 143쪽 2 — 사각형을 위쪽으로 뒤집은 도형은 어느 쪽으로 뒤집은 도형과 같나요?',ARRAY['M4-2-u6-X12']::text[],true,'{"seq":10,"concept":"M4-2-u6-C6","difficulty":2,"kind":"mc","stem":"『수학』 143쪽 2 — 사각형을 위쪽으로 뒤집은 도형은 어느 쪽으로 뒤집은 도형과 같나요?","options":[{"t":"아래쪽","correct":true},{"t":"왼쪽","mis":"M4-2-u6-X12"},{"t":"오른쪽","mis":"M4-2-u6-X12"},{"t":"같은 것이 없어요","mis":"M4-2-u6-X12"}],"explanation":["위쪽이나 아래쪽으로 뒤집으면 모두 위쪽과 아래쪽이 서로 바뀌어요.","그래서 위쪽으로 뒤집은 것과 아래쪽으로 뒤집은 것은 방향이 같아요.","아래쪽이에요."],"variant_rule":{"alt":[{"stem":"『수학』 143쪽 2 — 사각형을 오른쪽으로 뒤집은 도형은 어느 쪽으로 뒤집은 도형과 같나요?","options":[{"t":"왼쪽","correct":true},{"t":"위쪽","mis":"M4-2-u6-X12"},{"t":"아래쪽","mis":"M4-2-u6-X12"},{"t":"같은 것이 없어요","mis":"M4-2-u6-X12"}],"explanation":["왼쪽이나 오른쪽으로 뒤집으면 모두 왼쪽과 오른쪽이 서로 바뀌어요.","그래서 오른쪽으로 뒤집은 것과 왼쪽으로 뒤집은 것은 방향이 같아요.","왼쪽이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#11','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C7',2,'mc','auto','『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 반대 방향으로 270°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?',ARRAY['M4-2-u6-X15','M4-2-u6-X16']::text[],false,'{"seq":11,"concept":"M4-2-u6-C7","difficulty":2,"kind":"mc","stem":"『수학』 145쪽 1 — 집 모양(위에 파란색 지붕, 아래에 노란색 벽)을 시계 반대 방향으로 270°만큼 돌리면 파란색 지붕은 어느 쪽으로 가나요?","options":[{"t":"오른쪽","correct":true},{"t":"왼쪽","mis":"M4-2-u6-X15"},{"t":"아래쪽","mis":"M4-2-u6-X16"},{"t":"위쪽 그대로","mis":"M4-2-u6-X16"}],"explanation":["시계 반대 방향은 시곗바늘이 도는 쪽의 반대쪽이에요.","위쪽에 있던 지붕이 270°만큼 돌아간 자리를 따라가요.","파란색 지붕은 오른쪽으로 가요."],"asset":{"type":"geo","items":[{"w":108,"h":108,"grid":18,"poly":[[[36.0,18.0],[72.0,18.0],[90.0,45.0],[81.0,45.0],[81.0,90.0],[27.0,90.0],[27.0,45.0],[18.0,45.0]]],"cap":"집 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#12','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C8',2,'mc','auto','『수학』 147쪽 2 — 도형을 시계 방향으로 360°만큼 돌린 것과 같은 것은 어느 것인가요?',ARRAY['M4-2-u6-X16','M4-2-u6-X17','M4-2-u6-X18']::text[],false,'{"seq":12,"concept":"M4-2-u6-C8","difficulty":2,"kind":"mc","stem":"『수학』 147쪽 2 — 도형을 시계 방향으로 360°만큼 돌린 것과 같은 것은 어느 것인가요?","options":[{"t":"돌리기 전의 처음 도형","correct":true},{"t":"시계 방향으로 180°만큼 돌린 것","mis":"M4-2-u6-X16"},{"t":"시계 반대 방향으로 90°만큼 돌린 것","mis":"M4-2-u6-X17"},{"t":"아래쪽으로 뒤집은 것","mis":"M4-2-u6-X18"}],"explanation":["한 바퀴는 360°예요.","시계 방향과 시계 반대 방향은 360°에서 빼어 견주어요.","360°는 한 바퀴라 처음 도형과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#13','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C3',2,'mc','auto','『수학익힘』 80쪽 — 하늘색 자동차를 출구로 나가게 하려면 연두색 자동차는 어느 쪽으로 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)',ARRAY['M4-2-u6-X02']::text[],false,'{"seq":13,"concept":"M4-2-u6-C3","difficulty":2,"kind":"mc","stem":"『수학익힘』 80쪽 — 하늘색 자동차를 출구로 나가게 하려면 연두색 자동차는 어느 쪽으로 밀어야 하나요? (그림 속 글자는 자동차의 색이에요. 자동차는 길쭉한 쪽으로만 — 가로로 긴 차는 왼쪽·오른쪽, 세로로 긴 차는 위쪽·아래쪽으로만 움직여요.)","options":[{"t":"아래쪽","correct":true},{"t":"위쪽","mis":"M4-2-u6-X02"},{"t":"오른쪽","mis":"M4-2-u6-X02"},{"t":"왼쪽","mis":"M4-2-u6-X02"}],"explanation":["연두색 자동차는 세로로 긴 차라 위쪽·아래쪽으로만 움직여요.","위쪽은 노란색 자동차가 막고 있어요.","분홍색 자동차를 비킨 다음 아래쪽으로 밀어요."],"asset":{"type":"geo","items":[{"w":201.0,"h":150,"poly":[[[33.0,63.0],[117.0,63.0],[117.0,87.0],[33.0,87.0]],[[3.0,3.0],[87.0,3.0],[87.0,27.0],[3.0,27.0]],[[123.0,3.0],[147.0,3.0],[147.0,57.0],[123.0,57.0]],[[123.0,63.0],[147.0,63.0],[147.0,117.0],[123.0,117.0]],[[33.0,123.0],[147.0,123.0],[147.0,147.0],[33.0,147.0]]],"lab":[[[75.0,74.0],"하늘"],[[45.0,14.0],"보라"],[[135.0,29.0],"노랑"],[[135.0,89.0],"연두"],[[90.0,134.0],"분홍"],[[175.5,74.0],"출구"]],"seg":[[[0,0],[150,0]],[[0,150],[150,150]],[[0,0],[0,150]],[[150,0],[150,60]],[[150,90],[150,150]]],"dash":[[[30,0],[30,150]],[[60,0],[60,150]],[[90,0],[90,150]],[[120,0],[120,150]],[[0,30],[150,30]],[[0,60],[150,60]],[[0,90],[150,90]],[[0,120],[150,120]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
