INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#17','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C2',3,'mc','auto','『수학』 135쪽 5 — 로봇 친구 로니가 집(점 ㄱ)에서 위쪽으로 2칸 이동하고 오른쪽으로 6칸 이동했어요. 로니가 도착한 학교는 어느 점인가요?',ARRAY['M4-2-u6-X06','M4-2-u6-X02']::text[],false,'{"seq":17,"concept":"M4-2-u6-C2","difficulty":3,"kind":"mc","stem":"『수학』 135쪽 5 — 로봇 친구 로니가 집(점 ㄱ)에서 위쪽으로 2칸 이동하고 오른쪽으로 6칸 이동했어요. 로니가 도착한 학교는 어느 점인가요?","options":[{"t":"점 ㅁ","correct":true},{"t":"점 ㄹ","mis":"M4-2-u6-X06"},{"t":"점 ㄷ","mis":"M4-2-u6-X02"},{"t":"점 ㄴ","mis":"M4-2-u6-X02"}],"explanation":["점 ㄱ에서 먼저 위쪽으로 2칸 가요.","그 자리에서 오른쪽으로 6칸 가요.","도착한 곳은 점 ㅁ이에요."],"asset":{"type":"geo","items":[{"w":252,"h":180,"grid":18,"pts":{"ㄱ":[126,126,"n"],"ㄴ":[18,90,"n"],"ㄷ":[234,162,"s"],"ㄹ":[162,18,"n"],"ㅁ":[234,90,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#18','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C8',3,'ox','auto','지도서 424쪽 오류 1 — 깃발 모양을 아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형은 서로 같아요.',ARRAY['M4-2-u6-X18']::text[],false,'{"seq":18,"concept":"M4-2-u6-C8","difficulty":3,"kind":"ox","stem":"지도서 424쪽 오류 1 — 깃발 모양을 아래쪽으로 뒤집은 도형과 시계 방향으로 180°만큼 돌린 도형은 서로 같아요.","answer":"X","reason_options":[{"t":"깃발 모양은 왼쪽과 오른쪽이 달라서 두 결과의 방향이 달라서","correct":true},{"t":"아래쪽 뒤집기와 180° 돌리기는 언제나 같아서","mis":"M4-2-u6-X18"}],"mis":"M4-2-u6-X18","explanation":["아래쪽으로 뒤집으면 위아래만 바뀌어요.","180°만큼 돌리면 위아래와 좌우가 모두 바뀌어요.","깃발 모양은 좌우가 달라 두 결과가 달라요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"grid":18,"poly":[[[18.0,18.0],[72.0,36.0],[36.0,54.0],[36.0,90.0],[18.0,90.0]]],"cap":"깃발 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#19','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C8',3,'mc','auto','지도서 425쪽 오류 2 — 「곰」을 시계 방향으로 360°만큼 돌리면 어떻게 보이나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X26']::text[],false,'{"seq":19,"concept":"M4-2-u6-C8","difficulty":3,"kind":"mc","stem":"지도서 425쪽 오류 2 — 「곰」을 시계 방향으로 360°만큼 돌리면 어떻게 보이나요?","options":[{"t":"「곰」 그대로 보여요","correct":true},{"t":"「문」으로 보여요","mis":"M4-2-u6-X16"},{"t":"글자처럼 보이지 않아요","mis":"M4-2-u6-X26"},{"t":"「몸」으로 보여요","mis":"M4-2-u6-X16"}],"explanation":["360°는 한 바퀴예요.","한 바퀴 돌리면 돌리기 전과 같아요.","그대로 「곰」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#20','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C7',3,'sa','auto','『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 홈에서 출발해 1루, 2루, 3루를 거쳐 홈으로 돌아올 때 ㉡ 카드는 모두 몇 장 쓰나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M4-2-u6-C7","difficulty":3,"kind":"sa","stem":"『수학』 155쪽 수학 되돌아보기 — 야구 경기장에서 홈, 1루, 2루, 3루 사이는 모두 약 27.4 m이고 홈 → 1루 → 2루 → 3루 → 홈 순서로 돌아요. 명령 카드 ㉠ 약 27.4 m 앞으로 가기 · ㉡ 시계 반대 방향으로 90°만큼 돌기 · ㉢ 시계 방향으로 90°만큼 돌기. 홈에서 출발해 1루, 2루, 3루를 거쳐 홈으로 돌아올 때 ㉡ 카드는 모두 몇 장 쓰나요? 숫자로 쓰세요.","answer":["3"],"explanation":["1루, 2루, 3루에서 방향을 바꾸어요.","세 번 모두 시계 반대 방향으로 90°만큼 돌아요.","모두 3장이에요(㉠ ㉡ ㉠ ㉡ ㉠ ㉡ ㉠)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#21','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C10',3,'mc','auto','『수학』 149쪽 2 예 — 왼쪽과 오른쪽이 똑같은 삼각형 모양을 오른쪽으로 뒤집기를 반복하여 첫 줄을 만들었어요. 첫 줄은 어떻게 되나요?',ARRAY['M4-2-u6-X10','M4-2-u6-X11','M4-2-u6-X18']::text[],false,'{"seq":21,"concept":"M4-2-u6-C10","difficulty":3,"kind":"mc","stem":"『수학』 149쪽 2 예 — 왼쪽과 오른쪽이 똑같은 삼각형 모양을 오른쪽으로 뒤집기를 반복하여 첫 줄을 만들었어요. 첫 줄은 어떻게 되나요?","options":[{"t":"같은 삼각형 모양이 그대로 되풀이돼요","correct":true},{"t":"삼각형이 위아래로 번갈아 나와요","mis":"M4-2-u6-X10"},{"t":"삼각형이 오른쪽으로 기울어져요","mis":"M4-2-u6-X11"},{"t":"삼각형이 90°씩 돌아가며 나와요","mis":"M4-2-u6-X18"}],"explanation":["오른쪽으로 뒤집으면 왼쪽과 오른쪽이 바뀌어요.","이 삼각형은 왼쪽과 오른쪽이 똑같아서 뒤집어도 같은 모양이에요.","그래서 같은 모양이 그대로 되풀이돼요."],"asset":{"type":"geo","items":[{"w":60,"h":60,"grid":60,"poly":[[[30.0,7.2],[52.8,52.8],[7.2,52.8]]],"cap":"삼각형 모양"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#22','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C7',3,'mc','auto','『수학』 146쪽 2 — 도형을 시계 방향으로 90°만큼 4번 돌리면 어떻게 되나요?',ARRAY['M4-2-u6-X16','M4-2-u6-X18']::text[],false,'{"seq":22,"concept":"M4-2-u6-C7","difficulty":3,"kind":"mc","stem":"『수학』 146쪽 2 — 도형을 시계 방향으로 90°만큼 4번 돌리면 어떻게 되나요?","options":[{"t":"처음 도형과 같아요","correct":true},{"t":"시계 방향으로 180°만큼 돌린 것과 같아요","mis":"M4-2-u6-X16"},{"t":"아래쪽으로 뒤집은 것과 같아요","mis":"M4-2-u6-X18"},{"t":"시계 반대 방향으로 90°만큼 돌린 것과 같아요","mis":"M4-2-u6-X16"}],"explanation":["90°만큼 4번이면 360°예요.","360°는 한 바퀴예요.","한 바퀴 돌리면 처음 도형과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#23','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C2',4,'essay','teacher','『수학』 135쪽 5 — 로봇 친구 로니가 집에서 학교까지 가는 방법을 로니가 이해할 수 있도록 두 가지 방법으로 설명하고, 두 방법이 모두 맞는 까닭을 써 보세요. (학교는 집보다 위쪽으로 2칸, 오른쪽으로 6칸에 있어요.)','{}'::text[],false,'{"seq":23,"concept":"M4-2-u6-C2","difficulty":4,"kind":"essay","stem":"『수학』 135쪽 5 — 로봇 친구 로니가 집에서 학교까지 가는 방법을 로니가 이해할 수 있도록 두 가지 방법으로 설명하고, 두 방법이 모두 맞는 까닭을 써 보세요. (학교는 집보다 위쪽으로 2칸, 오른쪽으로 6칸에 있어요.)","answer_guide":{"answer":"방법 1: 위쪽으로 2칸 이동한 다음, 오른쪽으로 6칸 이동해요. 방법 2: 오른쪽으로 6칸 이동한 다음, 위쪽으로 2칸 이동해요. 이동하는 순서만 다르고 방향마다 옮기는 칸 수가 같아서 도착하는 곳이 같아요.","scoring_points":["두 방법 모두 방향과 칸 수를 함께 씀","위쪽 2칸·오른쪽 6칸을 바르게 붙임","순서를 바꾸어도 도착하는 곳이 같다는 까닭"]},"explanation":["학교는 집보다 위쪽, 오른쪽에 있어요.","위쪽으로 2칸, 오른쪽으로 6칸이에요.","순서를 바꾸어 말해도 도착하는 곳은 같아요."],"asset":{"type":"geo","items":[{"w":144,"h":72,"grid":18,"pts":{"집":[18,54,"n"],"학교":[126,18,"n"]}}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#24','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C6',4,'mc','auto','『수학익힘』 83쪽 6 — 처음 도형을 한 번 뒤집었을 때 나올 수 없는 도형은 어느 것인가요?',ARRAY['M4-2-u6-X21','M4-2-u6-X13']::text[],false,'{"seq":24,"concept":"M4-2-u6-C6","difficulty":4,"kind":"mc","stem":"『수학익힘』 83쪽 6 — 처음 도형을 한 번 뒤집었을 때 나올 수 없는 도형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉰","mis":"M4-2-u6-X21"},{"t":"㉯","mis":"M4-2-u6-X21"},{"t":"모두 나올 수 있어요","mis":"M4-2-u6-X13"}],"explanation":["한 번 뒤집으면 위아래나 좌우 가운데 한쪽이 꼭 바뀌어요.","처음 도형과 똑같은 도형은 한 번 뒤집어서는 나올 수 없어요.","㉮예요"],"asset":{"type":"geo","items":[{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"처음 도형"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,18.0],[54.0,18.0],[72.0,36.0],[36.0,72.0],[18.0,72.0]]],"cap":"㉮"},{"w":90,"h":90,"grid":18,"poly":[[[72.0,18.0],[36.0,18.0],[18.0,36.0],[54.0,72.0],[72.0,72.0]]],"cap":"㉯"},{"w":90,"h":90,"grid":18,"poly":[[[18.0,72.0],[54.0,72.0],[72.0,54.0],[36.0,18.0],[18.0,18.0]]],"cap":"㉰"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_math_u6_review_d#25','math',4,2,'u6','','tb_g4_2_math_u6_review_d','unit_review','M4-2-u6-C8',4,'essay','teacher','지도서 424쪽 오류 1 — 친구가 「도형을 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것은 언제나 같아.」라고 했어요. 친구의 생각이 맞는지 쓰고, 깃발 모양과 T 모양을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u6-C8","difficulty":4,"kind":"essay","stem":"지도서 424쪽 오류 1 — 친구가 「도형을 아래쪽으로 뒤집은 것과 시계 방향으로 180°만큼 돌린 것은 언제나 같아.」라고 했어요. 친구의 생각이 맞는지 쓰고, 깃발 모양과 T 모양을 예로 들어 설명해 보세요.","answer_guide":{"answer":"언제나 같지는 않아요. T 모양처럼 세로로 반을 접어 완전히 겹치는 도형은 두 결과가 같지만, 깃발 모양처럼 왼쪽과 오른쪽이 다른 도형은 아래쪽으로 뒤집으면 위아래만 바뀌고 180°만큼 돌리면 위아래와 좌우가 모두 바뀌어 결과가 달라요.","scoring_points":["언제나 같지는 않다","T 모양은 같다","깃발 모양은 다르다(좌우가 다름)"]},"explanation":["뒤집기는 한 직선을 기준으로, 돌리기는 한 점을 중심으로 움직여요.","좌우가 같은 도형만 두 결과가 같아요.","그래서 언제나 같지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
